required_providers {
  aws = {
    source  = "hashicorp/aws"
    version = "~> 6.46"
  }
}

default_tags {
  tags = {
    ManagedBy = "terraform"
    Purpose    = "production"
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for RDS."
  type        = string
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "Name of the database."
  type        = string
  default     = "mydb"
}

variable "db_username" {
  description = "Username for the database."
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database."
  type        = string
  sensitive   = true
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "public" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-sg"
  }
}

resource "aws_security_group" "private" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.public.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "private-sg"
  }
}

resource "aws_rds_cluster" "default" {
  cluster_identifier      = "mydb-cluster"
  engine                 = "aurora-postgresql"
  master_username        = var.db_username
  master_password        = var.db_password
  database_name          = var.db_name
  skip_final_snapshot    = true
  vpc_security_group_ids = [aws_security_group.private.id]

  tags = {
    Name = "mydb-cluster"
  }
}

resource "aws_rds_cluster_instance" "default" {
  count              = 2
  cluster_identifier = aws_rds_cluster.default.id
  instance_class    = var.db_instance_class
  engine            = aws_rds_cluster.default.engine

  tags = {
    Name = "mydb-instance-${count.index}"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "MyAPI"
  description = "API for my application"

  tags = {
    Name = "MyAPI"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "items"

  tags = {
    Name = "ItemsResource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "GetItemsMethod"
  }
}

resource "aws_lambda_function" "lambda" {
  function_name = "MyLambdaFunction"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "MyLambdaFunction"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect    = "Allow"
        Sid       = ""
      },
    ]
  })

  tags = {
    Name = "LambdaExecutionRole"
  }
}

resource "aws_iam_policy_attachment" "lambda_policy" {
  name       = "lambda_policy_attachment"
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_dynamodb_table" "table" {
  name         = "MyDynamoDBTable"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "MyDynamoDBTable"
  }
}

resource "aws_kinesis_stream" "stream" {
  name        = "MyKinesisStream"
  shard_count = 1

  tags = {
    Name = "MyKinesisStream"
  }
}

resource "aws_sns_topic" "topic" {
  name = "MySNSTopic"

  tags = {
    Name = "MySNSTopic"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/MyLambdaFunction"

  retention_in_days = 14

  tags = {
    Name = "MyLambdaLogGroup"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "XRayDaemon"

  tags = {
    Name = "XRayDaemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "rds_endpoint" {
  description = "RDS Endpoint"
  value       = aws_rds_cluster.default.endpoint
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = "${aws_api_gateway_rest_api.api.execution_arn}/items"
}",
