variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type for ECS"
  type        = string
  default     = "t3.micro"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment}-public-subnet-${count.index + 1}"
    Environment = var.environment
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name        = "${var.environment}-private-subnet-${count.index + 1}"
    Environment = var.environment
  }
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.environment}-ecs-sg"
    Environment = var.environment
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = {
    Name        = "${var.environment}-ecs-cluster"
    Environment = var.environment
  }
}

resource "aws_ecs_task_definition" "service" {
  family                   = "${var.environment}-service"
  container_definitions    = file("task-definitions/service.json")

  proxy_configuration {
    type          = "APPMESH"
    container_name = "applicationContainerName"
    properties = {
      AppPorts          = "8080"
      EgressIgnoredIPs   = "169.254.170.2,169.254.169.254"
      IgnoredUID        = "1337"
      ProxyEgressPort   = 15001
      ProxyIngressPort   = 15000
    }
  }

  tags = {
    Name        = "${var.environment}-task"
    Environment = var.environment
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment} environment"

  tags = {
    Name        = "${var.environment}-api"
    Environment = var.environment
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = true
    }
  }

  tags = {
    Name        = "${var.environment}-cdn"
    Environment = var.environment
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name        = "${var.environment}-dynamodb-table"
    Environment = var.environment
  }
}

resource "aws_elasticache_cluster" "cache" {
  cluster_id           = "${var.environment}-cache"
  engine               = "redis"
  node_type            = var.instance_type
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"

  tags = {
    Name        = "${var.environment}-elasticache"
    Environment = var.environment
  }
}

resource "aws_sqs_queue" "queue" {
  name = "${var.environment}-queue"

  tags = {
    Name        = "${var.environment}-sqs-queue"
    Environment = var.environment
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/ecs/${var.environment}/logs"

  retention_in_days = 14

  tags = {
    Name        = "${var.environment}-cloudwatch-log-group"
    Environment = var.environment
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name        = "${var.environment}-xray"
    Environment = var.environment
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "ecs_cluster_name" {
  description = "ECS Cluster Name"
  value       = aws_ecs_cluster.main.name
}

output "api_gateway_id" {
  description = "API Gateway ID"
  value       = aws_api_gateway_rest_api.api.id
}

output "dynamodb_table_name" {
  description = "DynamoDB Table Name"
  value       = aws_dynamodb_table.main.name
}

output "elasticache_cluster_id" {
  description = "ElastiCache Cluster ID"
  value       = aws_elasticache_cluster.cache.id
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.queue.id
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch Log Group Name"
  value       = aws_cloudwatch_log_group.log_group.name
}

output "xray_daemon_name" {
  description = "X-Ray Daemon Name"
  value       = aws_xray_daemon.xray.name
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS[ECS]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_API_Gateway --> Amazon_ECS
    Application_Load_Balancer --> Amazon_ECS
    Amazon_ECS --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_ElastiCache
    Amazon_ECS --> Amazon_SQS
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray"
}

