  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.media_bucket.bucket
  s3_key        = "lambda_code.zip"
  environment {
    MEDIA_QUEUE_URL = aws_sqs_queue.media_queue.id
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.bucket_prefix}lambda-exec-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name = "/aws/lambda/${aws_lambda_function.media_processor.function_name}"
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.bucket_prefix}api"
  description = "API for media processing"
}

resource "aws_api_gateway_resource" "media" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "media"
}

resource "aws_api_gateway_method" "post_media" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.media.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda_integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.media.id
  http_method = aws_api_gateway_method.post_media.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.media_processor.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "APIGateway"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "APIGateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = true
    }
  }
  tags = {
    Name = "${var.bucket_prefix}cdn"
  }
}

resource "aws_medialive_channel" "media_live_channel" {
  name = "${var.bucket_prefix}media-live-channel"
  input_attachments {
    input_id = aws_medialive_input.media_input.id
  }
  output_settings {
    output_group {
      name = "HLS"
      output_group_settings {
        hls_group_settings {
          destination = "s3://${aws_s3_bucket.media_bucket.bucket}/output/"
        }
      }
      outputs {
        preset = "HLS"
      }
    }
  }
}

resource "aws_medialive_input" "media_input" {
  name = "${var.bucket_prefix}media-input"
  type = "RTMP"
}

resource "aws_medialive_input_security_group" "input_security_group" {
  name = "${var.bucket_prefix}input-security-group"
  input_security_group_rules {
    cidr = "0.0.0.0/0"
  }
}

resource "aws_medialive_channel" "media_live_channel" {
  name = "${var.bucket_prefix}media-live-channel"
  input_attachments {
    input_id = aws_medialive_input.media_input.id
  }
  output_settings {
    output_group {
      name = "HLS"
      output_group_settings {
        hls_group_settings {
          destination = "s3://${aws_s3_bucket.media_bucket.bucket}/output/"
        }
      }
      outputs {
        preset = "HLS"
      }
    }
  }
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

output "media_bucket_name" {
  value = aws_s3_bucket.media_bucket.bucket
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
