provider "aws" {
  region = var.region
}

locals {
  common_tags = {
    ManagedBy = "terraform"
    Environment = var.environment
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = local.common_tags
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-ecs-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-gateway-sg"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_api_gatewayv2_api" "websocket_api" {
  name                = "${var.environment}-websocket-api"
  protocol_type       = "WEBSOCKET"
  route_selection_expression = "$request.body.action"

  tags = local.common_tags
}

resource "aws_api_gatewayv2_stage" "websocket_stage" {
  api_id = aws_api_gatewayv2_api.websocket_api.id
  name   = "production"

  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "websocket_task" {
  family                   = "${var.environment}-websocket-task"
  network_mode            = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  memory                  = "1024"
  cpu                     = "512"
  execution_role_arn      = aws_iam_role.ecs_execution_role.arn

  container_definitions = jsonencode([
    {
      name      = "websocket-container"
      image     = var.websocket_image
      cpu       = 256
      memory    = 512
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
        }
      ]
    }
  ])

  tags = local.common_tags
}

resource "aws_iam_role" "ecs_execution_role" {
  name = "${var.environment}-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "ecs_execution_policy" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = local.common_tags
}

resource "aws_elasticache_cluster" "main" {
  cluster_id           = "${var.environment}-elasticache"
  engine               = "redis"
  node_type            = var.elasticache_node_type
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"

  tags = local.common_tags
}

resource "aws_kinesis_stream" "main" {
  name        = "${var.environment}-kinesis-stream"
  shard_count = var.kinesis_shard_count

  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "${var.environment}-sns-topic"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name              = "/aws/ecs/${var.environment}/logs"
  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "${var.environment}-xray-daemon"

  tags = local.common_tags
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "websocket_api_id" {
  value = aws_api_gatewayv2_api.websocket_api.id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "elasticache_cluster_id" {
  value = aws_elasticache_cluster.main.cluster_id
}

output "kinesis_stream_name" {
  value = aws_kinesis_stream.main.name
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
