  "terraform": "terraform {
  required_version = "~> 1.9.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }
  backend "s3" {
    bucket         = var.bucket_name
    region         = var.region
    key            = "terraform.tfstate"
    encrypt        = true
