    {
      "decision": "AWS Lambda vs Amazon ECS",
      "chose": "AWS Lambda",
      "reason": "AWS Lambda is cost-effective for sporadic workloads and scales automatically without server management.",
      "when_to_switch": "If workloads become consistently high and require more persistent resource management."
    },
    {
      "decision": "Amazon RDS vs Amazon DynamoDB",
      "chose": "Amazon RDS",
      "reason": "Amazon RDS is better for structured data requiring complex queries and transactions while allowing for per-tenant data isolation.",
      "when_to_switch": "If the application requires extreme read/write scalability and can handle eventual consistency."
    },
