variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-http"
  }
}

resource "aws_security_group" "allow_lambda" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-lambda"
  }
}

resource "aws_lambda_function" "example" {
  function_name = "example_lambda"
  s3_bucket     = "your_lambda_bucket"
  s3_key        = "lambda.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    key = "value"
  }

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.allow_lambda.id]
  }

  tags = {
    Name = "example-lambda"
  }
}

resource "aws_emr_cluster" "example" {
  name          = "example-emr-cluster"
  release_label = "emr-6.3.0"
  applications  = ["Hadoop", "Spark"]

  ec2_attributes {
    subnet_id              = aws_subnet.private[0].id
    emr_managed_master_security_group = aws_security_group.allow_http.id
    emr_managed_slave_security_group  = aws_security_group.allow_http.id
  }

  tags = {
    Name = "example-emr-cluster"
  }
}

resource "aws_ecs_cluster" "example" {
  name = "example-ecs-cluster"

  tags = {
    Name = "example-ecs-cluster"
  }
}

resource "aws_s3_bucket" "example" {
  bucket = "example-bucket"

  tags = {
    Name = "example-bucket"
  }
}

resource "aws_athena_database" "example" {
  name   = "example_database"
  bucket = aws_s3_bucket.example.bucket

  tags = {
    Name = "example-athena-database"
  }
}

resource "aws_redshift_cluster" "example" {
  cluster_identifier = "example-cluster"
  node_type         = "dc2.large"
  master_username   = "admin"
  master_password   = "YourPassword123"
  cluster_type      = "single-node"

  tags = {
    Name = "example-redshift-cluster"
  }
}

resource "aws_dynamodb_table" "example" {
  name         = "example-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "example-dynamodb-table"
  }
}

resource "aws_kinesis_stream" "example" {
  name        = "example-stream"
  shard_count = 1

  tags = {
    Name = "example-kinesis-stream"
  }
}

resource "aws_sqs_queue" "example" {
  name = "example-queue"

  tags = {
    Name = "example-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/example_lambda"

  tags = {
    Name = "example-cloudwatch-log-group"
  }
}

resource "aws_xray_group" "example" {
  filter_expression = "service(\"example_lambda\")"

  tags = {
    Name = "example-xray-group"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "lambda_function_name" {
  value = aws_lambda_function.example.function_name
}

output "emr_cluster_id" {
  value = aws_emr_cluster.example.id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.example.name
}

output "s3_bucket_name" {
  value = aws_s3_bucket.example.bucket
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.example.name
}

output "kinesis_stream_name" {
  value = aws_kinesis_stream.example.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.example.id
