  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"ecs_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group_rule\" \"allow_http\" {\n  type              = \"ingress\"\n  from_port        = 80\n  to_port          = 80\n  protocol         = \"tcp\"\n  security_group_id = aws_security_group.ecs_sg.id\n  cidr_blocks      = [\"0.0.0.0/0\"]\n}\n\nresource \"aws_ecs_cluster\" \"ml_cluster\" {\n  name = \"ml-cluster\"\n}\n\nresource \"aws_lambda_function\" \"ml_inference\" {\n  function_name = \"mlInference\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n  source_code_hash = filebase64sha256(\"function.zip\")\n}\n\nresource \"aws_dynamodb_table\" \"predictions\" {\n  name         = \"predictions_table\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_lambda_function.ml_inference.invoke_arn\n    origin_id   = \"mlInferenceOrigin\"\n  }\n  enabled = true\n  default_cache_behavior {\n    target_origin_id = \"mlInferenceOrigin\"\n    viewer_protocol_policy = \"redirect-to-https\"\n    allowed_methods = [\"GET\", \"HEAD\", \"OPTIONS\"]\n  }\n}",
  "diagram": "graph TD\n    User([User])\n    User-->CloudFront([Amazon CloudFront])\n    CloudFront-->ALB([AWS Application Load Balancer])\n    ALB-->ECS([Amazon ECS])\n    ECS-->DynamoDB([Amazon DynamoDB])\n    ECS-->Lambda([AWS Lambda])\n    Lambda-->SNS([Amazon SNS])\n    CloudFront-->CloudWatch([Amazon CloudWatch])"
}

