resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-gateway-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-api-gateway-sg"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-lambda-sg"

  ingress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-lambda-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-ecs-sg"

  ingress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-ecs-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-rds-sg"

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = 20
  identifier = "${var.environment}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = "14.1"
  db_name = "my_database"
  username = "awsadmin"
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "${var.environment}-rds-instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = aws_s3_bucket.lambda_bucket.bucket
  s3_key = "lambda.zip"

  tags = {
    Name = "${var.environment}-lambda"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name = "${var.environment}-api"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part = "myresource"

  tags = {
    Name = "${var.environment}-api-resource"
  }
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  resource_id = aws_api_gateway_resource.my_resource.id
  http_method = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri = aws_lambda_function.my_lambda.invoke_arn
    http_method = "POST"
  }

  tags = {
    Name = "${var.environment}-api-method"
  }
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "${var.environment}-ecs-cluster"

  tags = {
    Name = "${var.environment}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "my_task" {
  family = "${var.environment}-task"
  network_mode = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu = "256"
  memory = "512"

  container_definitions = jsonencode([{
    name = "my_container"
    image = "my_image"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort = 80
      protocol = "tcp"
    }]
  }])

  tags = {
    Name = "${var.environment}-ecs-task"
  }
}

resource "aws_kinesis_stream" "my_kinesis_stream" {
  name = "${var.environment}-kinesis-stream"
  shard_count = 1

  tags = {
    Name = "${var.environment}-kinesis-stream"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "my_firehose" {
  name = "${var.environment}-firehose"
  destination = "s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.firehose_bucket.arn
    buffering_interval = 300
    buffering_size = 5
  }

  tags = {
    Name = "${var.environment}-firehose"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "${var.environment}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "my_xray_daemon" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

output "api_gateway_url" {
  value = "${aws_api_gateway_rest_api.my_api.execution_arn}/myresource"
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type = string
  default = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)."
  type = string
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets."
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets."
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets."
  type = number
  default = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets."
  type = number
  default = 2
}

variable "rds_instance_class" {
  description = "RDS instance class."
  type = string
  default = "db.t3.micro"
}

variable "rds_password" {
  description = "Password for the RDS database."
  type = string
}

variable "lambda_bucket_name" {
  description = "S3 bucket name for Lambda code."
  type = string
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = var.lambda_bucket_name

  tags = {
    Name = "${var.environment}-lambda-bucket"
  }
}

resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "${var.environment}-firehose-bucket"

  tags = {
    Name = "${var.environment}-firehose-bucket"
  }
