provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Owner = "Your Name"
      Environment = "Production"
    }
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "redshift_password" {
  description = "Password for the database in the Redshift cluster."
  type        = string
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "Main VPC"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_security_group" "redshift_security_group" {
  name   = "redshift_security_group"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.private[0].cidr_block] # Allow access from private subnet
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Redshift Security Group"
  }
}

resource "aws_redshift_cluster" "audiophile_cluster" {
  cluster_identifier = "tf-redshift-cluster"
  database_name      = "crinacle_audiophile_ratings"
  master_username    = "admin"
  master_password    = var.redshift_password
  node_type          = "dc2.large"
  cluster_type       = "single-node"
  skip_final_snapshot = true
  publicly_accessible = false
  automated_snapshot_retention_period = 0
  vpc_security_group_ids = [aws_security_group.redshift_security_group.id]
  tags = {
    Name = "Audiophile Redshift Cluster"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${substr(md5(aws_redshift_cluster.audiophile_cluster.id), 0, 8)}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "Data Bucket"
  }
}

resource "aws_lambda_function" "data_processor" {
  function_name = "data_processor"
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda_function.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec_role.arn

  tags = {
    Name = "Data Processor Lambda"
  }
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "Lambda Execution Role"
  }
}

resource "aws_kinesis_stream" "data_stream" {
  name        = "data_stream"
  shard_count = 1

  tags = {
    Name = "Data Kinesis Stream"
  }
}

resource "aws_sqs_queue" "data_queue" {
  name = "data_queue"

  tags = {
    Name = "Data SQS Queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/data_processor"

  retention_in_days = 14

  tags = {
    Name = "Data Processor Log Group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray_daemon"

  tags = {
    Name = "X-Ray Daemon"
  }
}

output "redshift_endpoint" {
  value = aws_redshift_cluster.audiophile_cluster.endpoint
  description = "The endpoint of the Redshift cluster."
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
  description = "The name of the S3 bucket."
}

output "kinesis_stream_name" {
  value = aws_kinesis_stream.data_stream.name
  description = "The name of the Kinesis data stream."
}

output "sqs_queue_url" {
  value = aws_sqs_queue.data_queue.id
  description = "The URL of the SQS queue."
}",
