  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_db_instance\" \"default\" {\n  engine         = \"mysql\"\n  instance_class = \"db.t3.medium\"\n  allocated_storage = 20\n  db_name = \"financial_data\"\n  username = \"admin\"\n  password = \"password\"\n  vpc_security_group_ids = [aws_security_group.allow_http.id]\n}\n\nresource \"aws_lambda_function\" \"reconciliation_job\" {\n  filename         = \"reconciliation_job.zip\"\n  function_name    = \"ReconciliationJob\"\n  role             = aws_iam_role.lambda_exec.arn\n  handler          = \"index.handler\"\n  source_code_hash = filebase64sha256(\"reconciliation_job.zip\")\n  runtime          = \"nodejs14.x\"\n}\n\nresource \"aws_ecs_cluster\" \"main\" {\n  name = \"financial-reconciliation-cluster\"\n}\n\nresource \"aws_application_load_balancer\" \"main\" {\n  name            = \"financial-recon-alb\"\n  internal        = false\n  security_groups = [aws_security_group.allow_http.id]\n  subnets         = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]\n}\n\nresource \"aws_sqs_queue\" \"reconciliation_queue\" {\n  name = \"reconciliation-queue\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Triggers| AWS_Lambda([AWS Lambda])\n    AWS_Lambda -->|Sends Message| SQS([Amazon SQS])\n    SQS -->|Processes| ECS([Amazon ECS])\n    ECS -->|Reads/Writes| RDS([Amazon RDS])\n    ECS -->|Stores| S3([Amazon S3])\n    ECS -->|Sends Metrics| CloudWatch([Amazon CloudWatch])\n    AWS_Lambda -->|Routes| ALB([AWS Application Load Balancer])\n"
}

