  "terraform": "variable "aws_region" {
  description = "Region for the AWS services to run in."
  type = string
  default = "us-east-1"
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type = string
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  type = string
  default = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway"
  type = string
  default = "my_api_gateway"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution"
  type = string
  default = "my_cloudfront_distribution"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  type = string
  default = "my_dynamodb_table"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue"
  type = string
  default = "my_sqs_queue"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic"
  type = string
  default = "my_sns_topic"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main_vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public_subnet_${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private_subnet_${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda_security_group"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "my_database"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"

  tags = {
    Name = "my_api_gateway"
  }
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id   = "api_gateway_origin"
  }

  enabled = true
  is_ipv6_enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "api_gateway_origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "POST", "OPTIONS"]
    cached_methods = ["GET", "OPTIONS"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = var.cloudfront_distribution_name
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "my_dynamodb_table"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = var.sqs_queue_name

  tags = {
    Name = "my_sqs_queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = var.sns_topic_name

  tags = {
    Name = "my_sns_topic"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "my_log_group"
  }
}

resource "aws_xray_daemon" "my_xray" {
  name = "my_xray_daemon"
  vpc_id = aws_vpc.main.id
  security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "my_xray_daemon"
  }
}

output "rds_instance_endpoint" {
  description = "The endpoint of the RDS instance"
  value = aws_db_instance.rds_instance.endpoint
