    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_ecs_cluster\" \"main\" {}\n\nresource \"aws_application_load_balancer\" \"main\" {\n  name = \"main-lb\"\n  internal = false\n  security_groups = [aws_security_group.allow_http.id]\n  subnets = [aws_subnet.public.id]\n}\n\nresource \"aws_dynamodb_table\" \"news_data\" {\n  name           = \"news-data\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"news-cache\"\n  engine = \"redis\"\n  node_type = \"cache.t3.medium\"\n  num_cache_nodes = 3\n  subnet_group_name = aws_subnet.private.id\n}\n\nresource \"aws_kinesis_stream\" \"news_stream\" {\n  name = \"news-stream\"\n  shard_count = 1\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"news-logs\"\n}\n\nresource \"aws_lambda_function\" \"processor\" {\n  function_name = \"news-processor\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  memory_size = 512\n  timeout = 30\n}\n",
