variable "region" {
  description = "The AWS region to deploy resources"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  type        = string
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "my_api_gateway"
}

variable "s3_bucket_name" {
  description = "S3 bucket name for storage"
  type        = string
  default     = "my-s3-bucket"
}

variable "dynamodb_table_name" {
  description = "DynamoDB table name"
  type        = string
  default     = "my_dynamodb_table"
}

variable "kinesis_stream_name" {
  description = "Kinesis Data Stream name"
  type        = string
  default     = "my_kinesis_stream"
}

variable "firehose_name" {
  description = "Kinesis Data Firehose name"
  type        = string
  default     = "my_firehose"
}

variable "redshift_cluster_id" {
  description = "Redshift cluster identifier"
  type        = string
  default     = "my-redshift-cluster"
}

variable "glue_database_name" {
  description = "Glue database name"
  type        = string
  default     = "my_glue_database"
}

variable "glue_table_name" {
  description = "Glue table name"
  type        = string
  default     = "my_glue_table"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"

  tags = {
    Name = var.api_gateway_name
  }
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = var.s3_bucket_name

  tags = {
    Name        = var.s3_bucket_name
    Description = "S3 bucket for Lambda function code"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_kinesis_stream" "my_stream" {
  name        = var.kinesis_stream_name
  shard_count = 1

  tags = {
    Name = var.kinesis_stream_name
  }
}

resource "aws_kinesis_firehose_delivery_stream" "my_firehose" {
  name        = var.firehose_name
  destination = "s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.lambda_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn
  }

  tags = {
    Name = var.firehose_name
  }
}

resource "aws_redshift_cluster" "my_redshift" {
  cluster_identifier = var.redshift_cluster_id
  node_type         = "dc2.large"
  master_username   = "masteruser"
  master_password   = "SuperSecretPassword"
  cluster_type      = "single-node"

  tags = {
    Name = var.redshift_cluster_id
  }
}

resource "aws_glue_catalog_database" "my_glue_database" {
  name = var.glue_database_name

  tags = {
    Name = var.glue_database_name
  }
}

resource "aws_glue_catalog_table" "my_glue_table" {
  database_name = aws_glue_catalog_database.my_glue_database.name
  name          = var.glue_table_name

  storage_descriptor {
    location = "s3://${aws_s3_bucket.lambda_bucket.bucket}"
    input_format = "org.apache.hadoop.mapred.TextInputFormat"
    output_format = "org.apache.hadoop.hive.ql.io.HiveOutputFormat"
    columns {
      name = "id"
      type = "string"
    }
  }

  tags = {
    Name = var.glue_table_name
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "LambdaLogs"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "lambda_function_name" {
  description = "Lambda Function Name"
  value       = aws_lambda_function.my_lambda.function_name
}

output "api_gateway_id" {
  description = "API Gateway ID"
  value       = aws_api_gateway_rest_api.my_api.id
}

output "dynamodb_table_name" {
  description = "DynamoDB Table Name"
  value       = aws_dynamodb_table.my_table.name
}

output "kinesis_stream_name" {
  description = "Kinesis Stream Name"
  value       = aws_kinesis_stream.my_stream.name
}

output "firehose_name" {
  description = "Kinesis Firehose Name"
  value       = aws_kinesis_firehose_delivery_stream.my_firehose.name
}

output "redshift_cluster_id" {
  description = "Redshift Cluster ID"
  value       = aws_redshift_cluster.my_redshift.cluster_identifier
}

output "glue_database_name" {
  description = "Glue Database Name"
  value       = aws_glue_catalog_database.my_glue_database.name
}

output "glue_table_name" {
  description = "Glue Table Name"
  value       = aws_glue_catalog_table.my_glue_table.name
}",
