variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_lambda_function" "example" {
  function_name = "example_lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  tags = {
    Name = "example_lambda"
  }
}

resource "aws_api_gateway_rest_api" "example" {
  name        = "example_api"
  description = "Example API Gateway"

  tags = {
    Name = "example_api"
  }
}

resource "aws_cloudfront_distribution" "example" {
  origin {
    domain_name = aws_api_gateway_rest_api.example.execution_arn
    origin_id   = "api_gateway_origin"

    custom_origin {
      domain_name = aws_api_gateway_rest_api.example.execution_arn
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "api_gateway_origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "POST", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
  }

  tags = {
    Name = "example_cloudfront"
  }
}

resource "aws_global_accelerator" "example" {
  name = "example-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  tags = {
    Name = "example_global_accelerator"
  }
}

resource "aws_dynamodb_table" "example" {
  name         = "example_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "example_dynamodb_table"
  }
}

resource "aws_kinesis_stream" "example" {
  name        = "example_stream"
  shard_count = 1

  tags = {
    Name = "example_kinesis_stream"
  }
}

resource "aws_sns_topic" "example" {
  name = "example_topic"

  tags = {
    Name = "example_sns_topic"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/example_lambda"

  retention_in_days = 14

  tags = {
    Name = "example_cloudwatch_log_group"
  }
}

resource "aws_xray_daemon" "example" {
  name = "example_xray_daemon"

  tags = {
    Name = "example_xray_daemon"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "lambda_function_name" {
  description = "The name of the Lambda function"
  value       = aws_lambda_function.example.function_name
}

output "api_gateway_id" {
  description = "The ID of the API Gateway"
  value       = aws_api_gateway_rest_api.example.id
}

output "dynamodb_table_name" {
  description = "The name of the DynamoDB table"
  value       = aws_dynamodb_table.example.name
}

output "kinesis_stream_name" {
  description = "The name of the Kinesis stream"
  value       = aws_kinesis_stream.example.name
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic"
  value       = aws_sns_topic.example.arn
}

output "cloudwatch_log_group_name" {
  description = "The name of the CloudWatch log group"
  value       = aws_cloudwatch_log_group.example.name
