        "monthly_usd": 75.0,
        "unit": "data transfer for 4K videos"
      },
      {
        "service": "Amazon S3",
        "monthly_usd": 15.0,
        "unit": "storage for video content"
      },
      {
        "service": "AWS Lambda",
        "monthly_usd": 10.0,
