  "terraform": "resource \"aws_vpc\" \"main\" {  cidr_block = \"10.0.0.0/16\"}\n\nresource \"aws_subnet\" \"subnet\" {  vpc_id     = aws_vpc.main.id  cidr_block = \"10.0.1.0/24\"  availability_zone = \"us-east-1a\"}\n\nresource \"aws_security_group\" \"sg\" {  vpc_id = aws_vpc.main.id  ingress {    from_port   = 80    to_port     = 80    protocol    = \"tcp\"    cidr_blocks = [\"0.0.0.0/0\"]  }}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {  origin {    domain_name = \"<your-s3-bucket>.s3.amazonaws.com\"    origin_id   = \"S3Origin\"  }\n\n  enabled = true\n  default_root_object = \"index.html\"\n  viewer_certificate {    cloudfront_default_certificate = true  }\n}\n\nresource \"aws_lambda_function\" \"video_processor\" {  function_name = \"videoProcessor\"  handler = \"index.handler\"  runtime = \"nodejs14.x\"  role = aws_iam_role.lambda_exec.arn}\n\nresource \"aws_s3_bucket\" \"video_bucket\" {  bucket = \"<your-s3-bucket>\"  acl    = \"private\"}\n\nresource \"aws_iam_role\" \"lambda_exec\" {  name = \"lambda_exec_role\"  assume_role_policy = jsonencode({    Version = \"2012-10-17\"    Statement = [{      Action = \"sts:AssumeRole\"      Principal = {        Service = \"lambda.amazonaws.com\"      }      Effect = \"Allow\"      Sid = \"\"    }]  })}\n\nresource \"aws_iam_role_policy\" \"lambda_policy\" {  name = \"lambda_policy\"  role = aws_iam_role.lambda_exec.id  policy = jsonencode({    Version = \"2012-10-17\"    Statement = [{      Action = [\"s3:GetObject\"]      Effect = \"Allow\"      Resource = \"${aws_s3_bucket.video_bucket.arn}/*\"    }]  })}",
