variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_type" {
  description = "DB instance type for RDS."
  type        = string
  default     = "db.t3.micro"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "my_lambda_function"
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  type        = string
  default     = "my_ecs_cluster"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "my_dynamodb_table"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue."
  type        = string
  default     = "my_sqs_queue"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic."
  type        = string
  default     = "my_sns_topic"
}

provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "public" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-sg"
  }
}

resource "aws_security_group" "private" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.public.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "private-sg"
  }
}

resource "aws_db_instance" "default" {
  identifier         = "mydb"
  engine             = "mysql"
  instance_class     = var.db_instance_type
  allocated_storage   = 20
  username           = "admin"
  password           = var.rds_password
  db_name            = "mydatabase"
  vpc_security_group_ids = [aws_security_group.private.id]
  skip_final_snapshot = true

  tags = {
    Name = "mydb-instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_ecs_cluster" "default" {
  name = var.ecs_cluster_name

  tags = {
    Name = var.ecs_cluster_name
  }
}

resource "aws_dynamodb_table" "default" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_sqs_queue" "default" {
  name = var.sqs_queue_name

  tags = {
    Name = var.sqs_queue_name
  }
}

resource "aws_sns_topic" "default" {
  name = var.sns_topic_name

  tags = {
    Name = var.sns_topic_name
  }
}

resource "aws_cloudwatch_log_group" "default" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  tags = {
    Name = "cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "default" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "db_instance_endpoint" {
  value = aws_db_instance.default.endpoint
}

output "lambda_function_arn" {
  value = aws_lambda_function.my_lambda.arn
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.default.name
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.default.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.default.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.default.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_Route_53[Route 53]
