provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Owner = "Security"
    }
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "my-ecs-cluster"
}

variable "alb_name" {
  description = "Name of the Application Load Balancer"
  type        = string
  default     = "my-alb"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution"
  type        = string
  default     = "my-cloudfront"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "alb_security_group" {
  name   = "alb_security_group"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb_security_group"
  }
}

resource "aws_security_group" "rds_security_group" {
  name   = "rds_security_group"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.alb_security_group.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = var.alb_name
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_security_group.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = false

  tags = {
    Name = var.alb_name
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = var.ecs_cluster_name

  tags = {
    Name = var.ecs_cluster_name
  }
}

resource "aws_ecs_task_definition" "ecs_task" {
  family                   = "my-task"
  requires_compatibilities  = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "my-container"
    image     = "my-image:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort     = 80
      protocol     = "tcp"
    }]
  }])

  tags = {
    Name = "ecs_task"
  }
}

resource "aws_ecs_service" "ecs_service" {
  name            = "my-service"
  cluster         = aws_ecs_cluster.ecs_cluster.id
  task_definition = aws_ecs_task_definition.ecs_task.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.rds_security_group.id]
    assign_public_ip = false
  }

  tags = {
    Name = "ecs_service"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my-queue"

  tags = {
    Name = "my_queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/ecs/my-service"

  retention_in_days = 14

  tags = {
    Name = "log_group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray_daemon"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "alb_dns_name" {
  value = aws_lb.application_load_balancer.dns_name
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.ecs_cluster.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Application_Load_Balancer
    Application_Load_Balancer --> Amazon_ECS
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_SQS
    Amazon_ECS -->|metrics| Amazon_CloudWatch"
}

