resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port = 443
    to_port = 443
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-lambda-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = 20
  identifier = "${var.environment}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = "14.1"
  db_name = var.db_name
  username = var.db_username
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "${var.environment}-rds-instance"
  }
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  filename = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  environment {
    DB_HOST = aws_db_instance.rds_instance.endpoint
    DB_NAME = var.db_name
    DB_USER = var.db_username
    DB_PASSWORD = var.rds_password
  }

  tags = {
    Name = "${var.environment}-api-lambda"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${var.environment}-api"
  description = "API for ${var.environment} application"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "items"

  tags = {
    Name = "${var.environment}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri = aws_lambda_function.api_lambda.invoke_arn
    http_method = "POST"
  }

  tags = {
    Name = "${var.environment}-api-method"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "apiOrigin"

    custom_origin_config {
      http_port = 80
      https_port = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD", "OPTIONS"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "${var.environment}-cdn"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "${var.environment}-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "${var.environment}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.api_lambda.function_name
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_RDS[(RDS)]
