provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.name}-private-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "${var.name}-lambda-sg"
  description = "Allow Lambda to access RDS and Glue"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.rds_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-lambda-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${var.name}-rds-sg"
  description = "Allow access to RDS from Lambda"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-rds-sg"
  }
}

resource "aws_security_group" "redshift_sg" {
  name        = "${var.name}-redshift-sg"
  description = "Allow access to Redshift from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks  = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-redshift-sg"
  }
}

resource "aws_db_instance" "rds" {
  identifier         = "${var.name}-rds"
  engine             = "mysql"
  instance_class     = var.rds_instance_type
  allocated_storage   = 20
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  username           = var.db_username
  password           = var.db_password
  skip_final_snapshot = true

  tags = {
    Name = "${var.name}-rds"
  }
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "${var.name}-rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.name}-rds-subnet-group"
  }
}

resource "aws_lambda_function" "transform" {
  function_name = "${var.name}-transform"
  s3_bucket     = aws_s3_bucket.data_staging.bucket
  s3_key        = "lambda/transform.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn

  tags = {
    Name = "${var.name}-transform"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid = ""
      }
    ]
  })

  tags = {
    Name = "${var.name}-lambda-exec-role"
  }
}

resource "aws_s3_bucket" "data_staging" {
  bucket = "${var.name}-data-staging"

  tags = {
    Name = "${var.name}-data-staging"
  }
}

resource "aws_kinesis_stream" "data_stream" {
  name        = "${var.name}-data-stream"
  shard_count = 1

  tags = {
    Name = "${var.name}-data-stream"
  }
}

resource "aws_glue_catalog_database" "etl_database" {
  name = "${var.name}_etl_db"

  tags = {
    Name = "${var.name}_etl_db"
  }
}

resource "aws_glue_job" "etl_job" {
  name     = "${var.name}-etl-job"
  role_arn = aws_iam_role.glue_role.arn
  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.data_staging.bucket}/scripts/etl_script.py"
  }

  tags = {
    Name = "${var.name}-etl-job"
  }
}

resource "aws_iam_role" "glue_role" {
  name = "${var.name}-glue-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Effect = "Allow"
        Sid = ""
      }
    ]
  })

  tags = {
    Name = "${var.name}-glue-role"
  }
}

resource "aws_redshift_cluster" "redshift" {
  cluster_identifier = "${var.name}-redshift"
  node_type         = "dc2.large"
  master_username   = var.redshift_username
  master_password   = var.redshift_password
  cluster_type      = "single-node"
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]

  tags = {
    Name = "${var.name}-redshift"
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/${aws_lambda_function.transform.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.name}-lambda-logs"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.name}-xray-daemon"
  image = "amazon/aws-xray-daemon"
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.rds.endpoint
}

output "redshift_endpoint" {
  value = aws_redshift_cluster.redshift.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.transform.function_name
