  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")
  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.lambda_sg.id]
  }

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "my_api"
  description = "My API Gateway"
  tags = {
    Name = "my_api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.resource.id
  http_method             = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  tags = {
    Name = "my_table"
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
}

resource "aws_eventbridge_rule" "event_rule" {
  name        = "my_event_rule"
  event_pattern = jsonencode({
    source = ["aws.lambda"]
  })
}

resource "aws_eventbridge_target" "event_target" {
  rule      = aws_eventbridge_rule.event_rule.name
  arn       = aws_lambda_function.my_lambda.arn
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.invoke_url
  description = "The endpoint of the API Gateway"
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_EventBridge[EventBridge]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_EventBridge
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray"
}

