  "terraform": "locals {
  environment = var.environment
  common_tags = {
    Environment = local.environment
    Project     = var.project_name
  }
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

# Public Subnet
resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

# Private Subnet
resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-alb-sg"
  tags = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Application Load Balancer
resource "aws_lb" "app_lb" {
  name               = "${local.environment}-app-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false
  tags = local.common_tags
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "rds_instance" {
  allocated_storage    = var.db_allocated_storage
  identifier          = "${local.environment}-rds"
  instance_class      = var.db_instance_class
  engine              = "postgres"
  engine_version      = var.db_engine_version
  db_name             = var.db_name
  username            = var.db_username
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  tags = local.common_tags
}

# Security Group for RDS
resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-rds-sg"
  tags = local.common_tags

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "app_cluster" {
  name = "${local.environment}-ecs-cluster"
  tags = local.common_tags
}

# ECS Task Definition
resource "aws_ecs_task_definition" "app_task" {
  family                   = "${local.environment}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "app"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

# ECS Service
resource "aws_ecs_service" "app_service" {
  name            = "${local.environment}-service"
  cluster         = aws_ecs_cluster.app_cluster.id
  task_definition = aws_ecs_task_definition.app_task.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  tags = local.common_tags
}

# Security Group for ECS
resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-ecs-sg"
  tags = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "app_distribution" {
  origin {
    domain_name = aws_lb.app_lb.dns_name
    origin_id   = "app-alb"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "app-alb"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = local.common_tags
}

# ElastiCache Redis Cluster
resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "${local.environment}-redis"
  engine               = "redis"
  node_type            = var.redis_node_type
  number_cache_nodes   = var.redis_node_count
  parameter_group_name = "default.redis3.2"
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.redis_subnet_group.name
  security_group_ids   = [aws_security_group.redis_sg.id]
  tags = local.common_tags
}

# Security Group for ElastiCache
resource "aws_security_group" "redis_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-redis-sg"
  tags = local.common_tags

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# SQS Queue
resource "aws_sqs_queue" "app_queue" {
  name = "${local.environment}-queue"
  tags = local.common_tags
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "app_log_group" {
  name = "${local.environment}-log-group"
  retention_in_days = 14
  tags = local.common_tags
}

# X-Ray Daemon
resource "aws_ecs_task_definition" "xray_task" {
  family                   = "${local.environment}-xray"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "xray-daemon"
    image     = "amazon/aws-xray-daemon"
    essential = true
    portMappings = [{
      containerPort = 2000
      hostPort      = 2000
      protocol      = "udp"
    }]
  }])

  tags = local.common_tags
}

# Outputs
output "alb_dns_name" {
  value = aws_lb.app_lb.dns_name
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.app_distribution.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    AWS_App_Mesh[App Mesh]
    Amazon_ECS_with_Fargate[ECS with Fargate]
    AWS_Lambda[Lambda]
    Amazon_RDS[(RDS)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_CloudFront --> AWS_App_Mesh
    Application_Load_Balancer --> Amazon_ECS_with_Fargate
    Application_Load_Balancer --> AWS_Lambda
    AWS_App_Mesh --> Amazon_ECS_with_Fargate
    AWS_App_Mesh --> AWS_Lambda
    Amazon_ECS_with_Fargate --> Amazon_RDS
    Amazon_ECS_with_Fargate --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS_with_Fargate --> Amazon_SQS
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS_with_Fargate -->|metrics| Amazon_CloudWatch
