resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.aws_region}a"
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}b"
  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "public_sg" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "public-sg"
  }
}

resource "aws_security_group" "private_sg" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.public_sg.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "private-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = var.db_allocated_storage
  identifier          = "rds-terraform"
  instance_class      = var.db_instance_class
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "mydatabase"
  username            = "admin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.private_sg.id]
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.eks_cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.21"

  vpc_config {
    subnet_ids = [aws_subnet.private_subnet.id]
  }

  depends_on = [aws_iam_role_policy_attachment.cluster_policy]
}

resource "aws_iam_role" "cluster" {
  name = "${var.eks_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = "example.com"
    origin_id   = "exampleOrigin"
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "CloudFront Distribution for my application"
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "exampleOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = var.cloudfront_distribution_name
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "my-redis-cluster"
  engine               = "redis"
  node_type            = var.elasticache_node_type
  number_cache_nodes   = 1
  parameter_group_name = "default.redis3.2"
  security_group_ids   = [aws_security_group.private_sg.id]
}

resource "aws_sqs_queue" "my_queue" {
  name = "my-queue"
}

resource "aws_sns_topic" "my_topic" {
  name = "my-topic"
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/my-log-group"
  retention_in_days = 14
}

resource "aws_xray_daemon" "xray" {
  name = "xray-daemon"
  image = "amazon/aws-xray-daemon"
  cpu = 256
  memory = 512
  desired_count = 1
  network_configuration {
    subnets = [aws_subnet.private_subnet.id]
    security_groups = [aws_security_group.private_sg.id]
  }
