{
  "scenario_summary": "The client needs an AWS architecture to run 200 microservices with independent scaling.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Application Load Balancer (ALB)",
        "Amazon API Gateway"
      ],
      "compute": [
        "Amazon ECS with Fargate",
