{
  "scenario_summary": "The client needs a scalable CI/CD platform to support 500 engineering teams.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "AWS Application Load Balancer",
        "Amazon API Gateway"
      ],
      "compute": [
        "AWS Lambda",
        "Amazon EC2",
        "Amazon ECS"
      ],
      "database": [
        "Amazon RDS",
        "Amazon DynamoDB"
