    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"ci_cd_function\" {\n  function_name = \"ci_cd_function\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n  source_code_hash = filebase64sha256(\"function.zip\")\n  vpc_config {\n    subnet_ids         = [aws_subnet.private.id]\n    security_group_ids = [aws_security_group.allow_http.id]\n  }\n}\n\nresource \"aws_ec2_instance\" \"ci_cd_instance\" {\n  ami           = \"ami-12345678\"\n  instance_type = \"t2.medium\"\n  subnet_id     = aws_subnet.private.id\n  security_groups = [aws_security_group.allow_http.name]\n}\n\nresource \"aws_db_instance\" \"ci_cd_db\" {\n  engine         = \"mysql\"\n  instance_class = \"db.t3.medium\"\n  allocated_storage = 20\n  db_name       = \"cicd\"\n  username      = \"admin\"\n  password      = \"password\"\n  subnet_group_name = aws_db_subnet_group.default.name\n}\n\nresource \"aws_db_subnet_group\" \"default\" {\n  name       = \"default\"\n  subnet_ids = [aws_subnet.private.id]\n}\n\nresource \"aws_sqs_queue\" \"ci_cd_queue\" {\n  name = \"ci_cd_queue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"ci_cd_log_group\" {\n  name = \"/aws/lambda/ci_cd_function\"\n}\n\nresource \"aws_application_load_balancer\" \"ci_cd_alb\" {\n  name            = \"ci_cd_alb\"\n  internal        = false\n  load_balancer_type = \"application\"\n  security_groups = [aws_security_group.allow_http.id]\n  subnets        = [aws_subnet.public.id]\n}",
