    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"ticket_processor\" {\n  function_name = \"ticketProcessor\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"ticket_api\" {\n  name = \"TicketAPI\"\n}\n\nresource \"aws_dynamodb_table\" \"tickets\" {\n  name         = \"Tickets\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  hash_key     = \"ticket_id\"\n  attribute {\n    name = \"ticket_id\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_sqs_queue\" \"ticket_queue\" {\n  name = \"ticketQueue\"\n}\n\nresource \"aws_elastic_load_balancing_load_balancer\" \"main_lb\" {\n  name               = \"mainLB\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets           = [aws_subnet.public.id]\n}\n\nresource \"aws_cloudwatch_log_group\" \"lambda_logs\" {\n  name = \"/aws/lambda/ticketProcessor\"\n}",
    "diagram": "graph TD\n    User([User])\n    User-->API[API Gateway]\n    API-->Lambda[AWS Lambda]\n    Lambda-->DB1[Amazon DynamoDB]\n    Lambda-->DB2[Amazon RDS]\n    Lambda-->SQS[Amazon SQS]\n    LoadBalancer[Elastic Load Balancer]-->API\n    CloudFront[Amazon CloudFront]-->LoadBalancer\n    Monitoring[CloudWatch]-->Lambda"
  }
}

