    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_internet_gateway\" \"gw\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"chat_api\" {\n  name        = \"Chat API\"\n}\n\nresource \"aws_api_gateway_resource\" \"websocket\" {\n  rest_api_id = aws_api_gateway_rest_api.chat_api.id\n  parent_id   = aws_api_gateway_rest_api.chat_api.root_resource_id\n  path_part   = \"chat\"\n}\n\nresource \"aws_lambda_function\" \"chat_function\" {\n  function_name = \"ChatHandler\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"messages\" {\n  name         = \"Messages\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"MessageId\"\n    type = \"S\"\n  }\n  key_schema {\n    attribute_name = \"MessageId\"\n    key_type      = \"HASH\"\n  }\n}\n",
