  "trade_offs": [
    {
      "decision": "AWS Lambda vs AWS ECS for compute",
      "chose": "AWS Lambda",
      "reason": "Lambda is serverless and automatically scales with demand, making it ideal for scheduled jobs without the need for managing infrastructure.",
      "when_to_switch": "If the report generation requires longer execution times or complex orchestration of multiple services, ECS may be a better fit."
    },
    {
      "decision": "Amazon RDS vs Amazon DynamoDB for database",
      "chose": "Amazon RDS",
      "reason": "RDS provides a managed relational database service that is suitable for structured data and complex queries needed for report generation.",
      "when_to_switch": "If the data model is more flexible and requires high scalability with low-latency access, DynamoDB would be more appropriate."
    },
