  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_cloudfront_distribution\" \"cd\" {\n  origin {\n    domain_name = aws_elastic_load_balancer.main.dns_name\n    origin_id   = \"my-origin\"\n  }\n}\n\nresource \"aws_application_load_balancer\" \"main\" {\n  name               = \"my-alb\"\n  internal           = false\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"my_function\" {\n  function_name = \"my_lambda_function\"\n  runtime       = \"nodejs14.x\"\n  handler       = \"index.handler\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"my_table\" {\n  name         = \"my_dynamodb_table\"\n  billing_mode = \"PAY_PER_REQUEST\"\n}\n\nresource \"aws_kinesis_stream\" \"my_stream\" {\n  name        = \"my_kinesis_stream\"\n  shard_count = 1\n}\n\nresource \"aws_cloudwatch_log_group\" \"my_log_group\" {\n  name = \"my_log_group\"\n}",
