variable "region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)."
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags       = local.common_tags
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "api_sg" {
  name        = "${var.environment}-api-sg"
  vpc_id      = aws_vpc.main.id
  tags        = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")
  environment {
    TABLE_NAME = aws_dynamodb_table.api_table.name
  }
  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_dynamodb_table" "api_table" {
  name         = "${var.environment}-api-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags     = local.common_tags
}

resource "aws_sqs_queue" "fifo_queue" {
  name                      = "${var.environment}-fifo-queue.fifo"
  fifo_queue                = true
  content_based_deduplication = true
  tags                      = local.common_tags
}

resource "aws_sns_topic" "notification_topic" {
  name = "${var.environment}-notification-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name              = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "${var.environment}-xray-daemon"
  tags = local.common_tags
}

output "api_lambda_arn" {
  value = aws_lambda_function.api_lambda.arn
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.api_table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.fifo_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.notification_topic.arn
