  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet2\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_iot_topic_rule\" \"sensor_data\" {\n  sql = \"SELECT * FROM 'sensor/data'\"\n}\n\nresource \"aws_kinesis_stream\" \"sensor_stream\" {\n  name        = \"sensor-stream\"\n  shard_count = 1\n}\n\nresource \"aws_lambda_function\" \"process_data\" {\n  function_name = \"ProcessSensorData\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n}\n\nresource \"aws_dynamodb_table\" \"sensor_data\" {\n  name           = \"SensorData\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  hash_key       = \"sensor_id\"\n  attribute {\n    name = \"sensor_id\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"SensorAPI\"\n}\n\nresource \"aws_ec2_instance\" \"processing_instance\" {\n  ami           = \"ami-0c55b159cbfafe01e\"\n  instance_type = \"t3.medium\"\n  vpc_security_group_ids = [aws_security_group.api_sg.id]\n  subnet_id = aws_subnet.subnet1.id\n}",
