  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"api_gateway_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group\" \"lambda_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group\" \"ecs_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"RecommendationAPI\"\n}\n\nresource \"aws_lambda_function\" \"recommendation_function\" {\n  function_name = \"RecommendationFunction\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  vpc_config {\n    subnet_ids         = [aws_subnet.private.id]\n    security_group_ids = [aws_security_group.lambda_sg.id]\n  }\n}\n\nresource \"aws_ecs_cluster\" \"recommendation_cluster\" {\n  cluster_name = \"RecommendationCluster\"\n}\n\nresource \"aws_dynamodb_table\" \"recommendations_table\" {\n  name         = \"Recommendations\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"UserId\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_elasticache_cluster\" \"recommendation_cache\" {\n  cluster_id = \"RecommendationCache\"\n  engine = \"redis\"\n  node_type = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway.api.execution_arn\n    origin_id   = \"APIGatewayOrigin\"\n  }\n}\n",
