    protocol    = "tcp"
    security_groups = [aws_security_group.api_gateway_sg.id]
  }

  tags = {
    Name = "${var.name}-ecs-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  tags = {
    Name = "${var.name}-rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  count               = var.rds_shard_count
  allocated_storage    = 20
  identifier          = "${var.name}-rds-${count.index}"
  instance_class      = var.rds_instance_class
  engine             = var.rds_engine
  engine_version      = var.rds_engine_version
  db_name             = var.rds_db_name
  username            = var.rds_username
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "${var.name}-rds-${count.index}"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "${var.name}-lambda"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.name}-api"
  description = "API for ${var.name}"

  tags = {
    Name = "${var.name}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "${var.name}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.name}-api-method"
  }
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn

  tags = {
    Name = "${var.name}-api-integration"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiGateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id       = "apiGateway"
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "${var.name}-cloudfront"
  }
}

resource "aws_elasticache_cluster" "cache" {
  cluster_id           = "${var.name}-cache"
  engine               = "redis"
  node_type            = var.cache_node_type
  num_cache_nodes      = var.cache_node_count
  parameter_group_name = "default.redis3.2"
  port                 = 6379
  availability_zone    = element(data.aws_availability_zones.available.names, 0)

  tags = {
    Name = "${var.name}-cache"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "${var.name}-queue"

  tags = {
    Name = "${var.name}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "${var.name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.name}-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.name}-xray-daemon"

  tags = {
    Name = "${var.name}-xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "rds_endpoint" {
  description = "RDS Endpoint"
  value       = aws_db_instance.rds_instance.*.endpoint
}

output "lambda_function_name" {
  description = "Lambda Function Name"
  value       = aws_lambda_function.my_lambda.function_name
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.cdn.id
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.queue.id
