variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., production, staging)."
  default     = "production"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  default     = "my_api_gateway"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket."
  default     = "my-s3-bucket-${var.environment}"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index}.0/24"
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 2}.0/24"
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_s3_bucket" "app_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"
  tags   = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  s3_bucket     = aws_s3_bucket.app_bucket.bucket
  s3_key        = "lambda_function.zip" # Assume the zip file is uploaded to S3
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  tags          = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "my_integration" {
  rest_api_id             = aws_api_gateway_rest_api.my_api.id
  resource_id             = aws_api_gateway_resource.my_resource.id
  http_method             = aws_api_gateway_method.my_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name              = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_S3[(S3)]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_S3
    AWS_Lambda -->|metrics| Amazon_CloudWatch"
}

