{
  "scenario_summary": "The client needs a serverless webhook processing system capable of handling 1 million events per day.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon API Gateway"
      ],
      "compute": [
        "AWS Lambda"
      ],
      "database": [
        "Amazon DynamoDB"
      ],
      "messaging": [
        "Amazon EventBridge"
      ],
      "monitoring": [
        "Amazon CloudWatch"
      ]
    },
    "reasoning": "The architecture leverages AWS Lambda for compute, which allows for automatic scaling and only incurs costs based on actual usage, making it cost-effective for handling variable workloads like webhook events. Amazon API Gateway serves as the entry point for incoming webhook requests, providing a secure and scalable way to manage APIs. By using Amazon EventBridge, we can efficiently route events from the API Gateway to various processing components, enabling an event-driven architecture that can scale seamlessly with demand.

For data storage, Amazon DynamoDB is chosen due to its ability to handle high throughput and low latency, making it suitable for storing event data. It also integrates well with AWS Lambda, allowing for efficient data retrieval and storage without the need for server management. Monitoring is handled through Amazon CloudWatch, which provides insights into application performance and operational health, ensuring that any issues can be quickly identified and addressed."
  },
  "trade_offs": [
    {
      "decision": "AWS Lambda vs EC2",
      "chose": "AWS Lambda",
      "reason": "AWS Lambda is a serverless compute service that automatically scales with the number of events, reducing operational overhead and costs associated with provisioning and managing servers.",
      "when_to_switch": "If the processing requirements exceed the Lambda limits (e.g., execution time or memory), then transitioning to EC2 instances may be necessary."
    },
    {
      "decision": "Amazon API Gateway vs Application Load Balancer",
      "chose": "Amazon API Gateway",
      "reason": "API Gateway is designed specifically for managing APIs, providing features like request validation, throttling, and authorization, which are essential for a webhook processing system.",
      "when_to_switch": "If there is a need for more advanced routing or if the application evolves to require WebSocket support, then an Application Load Balancer might be more appropriate."
    },
    {
      "decision": "Amazon EventBridge vs Amazon SQS",
      "chose": "Amazon EventBridge",
      "reason": "EventBridge provides a more flexible event routing mechanism that can integrate with multiple AWS services and third-party applications, making it ideal for an event-driven architecture.",
      "when_to_switch": "If the system requires guaranteed message delivery and simple queueing without complex event routing, Amazon SQS could be a better fit."
    },
    {
      "decision": "Amazon DynamoDB vs Amazon RDS",
      "chose": "Amazon DynamoDB",
      "reason": "DynamoDB offers a fully managed NoSQL database with high availability and scalability, which is well-suited for the variable workloads of webhook events.",
      "when_to_switch": "If the application requires complex queries or transactions that are better suited for a relational database, then Amazon RDS would be more appropriate."
    }
  ],
  "cost": {
    "monthly_breakdown": [
      {
        "service": "Amazon CloudFront",
        "monthly_usd": 10.0,
        "unit": "per 1TB transfer"
      },
      {
        "service": "Amazon API Gateway",
        "monthly_usd": 3.5,
        "unit": "per 1M requests"
      },
      {
        "service": "AWS Lambda",
        "monthly_usd": 0.2,
        "unit": "per 1M requests"
      },
      {
        "service": "Amazon DynamoDB",
        "monthly_usd": 25.0,
        "unit": "estimated (moderate traffic)"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 10.0,
        "unit": "estimated"
      },
      {
        "service": "Data Transfer (egress)",
        "monthly_usd": 9.0,
        "unit": "per 100GB egress"
      }
    ],
    "total_monthly_usd": 57.7,
    "spike_estimate_usd": 77.9,
    "optimization": "Switch to 1-year Reserved Instances for EC2/RDS/ElastiCache to save 30-40% on compute costs. Use S3 Intelligent-Tiering for infrequently accessed data."
  },
  "terraform": "terraform {
  required_version = "~> 1.9.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.49.0"
    }
  }
  backend "s3" {
    bucket         = "dev-aman-tf-bucket"
    region         = "us-east-1"
    key            = "eks/terraform.tfstate"
    dynamodb_table = "Lock-Files"
    encrypt        = true
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  default     = "my_lambda_function"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  vpc_id      = aws_vpc.main.id
  description = "Security group for Lambda function"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-security-group"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "my_dynamodb_table"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    TABLE_NAME = aws_dynamodb_table.my_table.name
  }

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })

  tags = {
    Name = "lambda-execution-role"
  }
}

resource "aws_iam_policy_attachment" "lambda_policy" {
  name       = "lambda_policy_attachment"
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "my_api"
  description = "My API Gateway"

  tags = {
    Name = "my_api_gateway"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "my_api_resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "my_api_method"
  }
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.resource.id
  http_method             = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn

  tags = {
    Name = "my_api_integration"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "lambda_log_group"
  }
}

resource "aws_eventbridge_rule" "rule" {
  name        = "my_event_rule"
  description = "Event rule for triggering Lambda"
  event_pattern = jsonencode({
    source = ["aws.events"]
  })

  tags = {
    Name = "my_event_rule"
  }
}

resource "aws_eventbridge_target" "target" {
  rule      = aws_eventbridge_rule.rule.name
