  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_internet_gateway\" \"gw\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"HRManagementAPI\"\n}\n\nresource \"aws_lb\" \"app_lb\" {\n  name               = \"app-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.lb_sg.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_dynamodb_table\" \"hr_table\" {\n  name           = \"HRData\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"EmployeeID\"\n    type = \"S\"\n  }\n  hash_key = \"EmployeeID\"\n}\n\nresource \"aws_lambda_function\" \"hr_lambda\" {\n  function_name = \"HRManagementFunction\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_sqs_queue\" \"hr_queue\" {\n  name = \"HRQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/HRManagementFunction\"\n}",
