locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project_name
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count             = var.public_subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(var.availability_zones, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = var.private_subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(var.availability_zones, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  environment = {
    DB_ENDPOINT = aws_neptune_cluster.cluster_endpoint
  }
  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for ${var.project_name}"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.api_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "APIGateway"
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "APIGateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]
    forwarded_values {
      query_string = false
    }
  }

  tags = local.common_tags
}

resource "aws_global_accelerator_accelerator" "accelerator" {
  name = "${var.environment}-accelerator"
  enabled = true
  ip_address_type = "IPV4"
  tags = local.common_tags
}

resource "aws_neptune_cluster" "neptune" {
  cluster_identifier = "${var.environment}-neptune-cluster"
  engine            = "neptune"
  tags              = local.common_tags
}

resource "aws_sns_topic" "notifications" {
  name = "${var.environment}-notifications"
  tags = local.common_tags
}

resource "aws_sqs_queue" "queue" {
  name = "${var.environment}-queue"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_domain" {
  value = aws_cloudfront_distribution.cdn.domain_name
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Global_Accelerator[Global Accelerator]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_Neptune[(Neptune)]
    Amazon_SNS[SNS]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> AWS_Global_Accelerator
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Global_Accelerator --> AWS_Lambda
    AWS_Global_Accelerator --> Amazon_ECS
    AWS_Lambda --> Amazon_Neptune
    Amazon_ECS --> Amazon_Neptune
    AWS_Lambda --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS --> Amazon_SNS
    Amazon_ECS --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Amazon_ECS -->|metrics| Amazon_CloudWatch
