variable "aws_region" {
  description = "AWS region to launch resources."
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)."
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags       = local.common_tags
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "lambda_role" {
  name               = "${var.environment}-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-my-lambda"
  role          = aws_iam_role.lambda_role.arn
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  environment {
    TABLE_NAME = aws_dynamodb_table.my_table.name
  }
  tags = local.common_tags
}

resource "aws_dynamodb_table" "my_table" {
  name         = "${var.environment}-my-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags     = local.common_tags
}

resource "aws_sqs_queue" "my_fifo_queue" {
  name                      = "${var.environment}-my-queue.fifo"
  fifo_queue                = true
  content_based_deduplication = true
  tags                      = local.common_tags
}

resource "aws_sns_topic" "my_topic" {
  name = "${var.environment}-my-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "${var.environment}-xray-daemon"
  tags = local.common_tags
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_fifo_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.my_topic.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SQS_FIFO[SQS FIFO]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_SQS_FIFO
    AWS_Lambda -->|metrics| Amazon_CloudWatch"
}

