      "chose": "Amazon DynamoDB",
      "reason": "Amazon DynamoDB offers a fully managed NoSQL database solution that scales automatically, which is ideal for the variable transaction load of a logistics platform.",
      "when_to_switch": "If the application requires complex joins or transactions that are better suited for a relational database, Amazon RDS would be more appropriate."
    },
