locals {
  common_tags = {
    ManagedBy = "terraform"
    Environment = var.environment
    Purpose = "Production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index}"
  })
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-ecs-sg"
  })
}

resource "aws_cloudfront_distribution" "api_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "APIGateway"

    custom_origin_config {
      origin_protocol_policy = "https-only"
      http_port             = 80
      https_port            = 443
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "APIGateway"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "POST", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-cloudfront"
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment} environment"

  tags = local.common_tags
}

resource "aws_global_accelerator" "main" {
  name = "${var.environment}-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  listener {
    port_range {
      from_port = 80
      to_port   = 80
    }
    protocol = "TCP"
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-global-accelerator"
  })
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "api_task" {
  family                   = "${var.environment}-api-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "api"
    image     = var.api_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_code.bucket
  s3_key        = aws_s3_bucket_object.lambda_code.key

  tags = local.common_tags
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "${var.environment}-aurora-cluster"
  engine                 = "aurora-postgresql"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true
  database_name          = var.db_name

  tags = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = local.common_tags
}

resource "aws_sqs_queue" "main" {
  name = "${var.environment}-sqs-queue"

  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "${var.environment}-sns-topic"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "${var.environment}-xray-daemon"

  tags = local.common_tags
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.api_distribution.id
}

output "api_gateway_id" {
  value = aws_api_gateway_rest_api.api.id
}

output "ecs_cluster_id" {
  value = aws_ecs_cluster.main.id
}

output "aurora_cluster_id" {
  value = aws_rds_cluster.aurora.id
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}

output "lambda_function_name" {
  value = aws_lambda_function.api_lambda.function_name
}",
