  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_security_group\" \"allow_https\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lb\" \"app_lb\" {\n  name               = \"app-load-balancer\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id, aws_security_group.allow_https.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"data_processor\" {\n  function_name = \"DataProcessor\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_ecs_cluster\" \"genomics_cluster\" {\n  name = \"GenomicsCluster\"\n}\n\nresource \"aws_rds_instance\" \"genomics_db\" {\n  identifier = \"genomics-db\"\n  engine     = \"mysql\"\n  instance_class = \"db.t3.micro\"\n  allocated_storage = 20\n  db_subnet_group_name = aws_db_subnet_group.default.name\n  vpc_security_group_ids = [aws_security_group.allow_http.id]\n}\n\nresource \"aws_s3_bucket\" \"genomics_data\" {\n  bucket = \"genomics-data-bucket\"\n}\n\nresource \"aws_sqs_queue\" \"data_queue\" {\n  name = \"DataQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"logs\" {\n  name = \"log-group\"\n}",
