variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Main VPC"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  map_public_ip_on_launch = true

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Allow HTTP"
  }
}

resource "aws_security_group" "allow_https" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Allow HTTPS"
  }
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway_rest_api.main.execution_arn
    origin_id   = "APIGateway"

    custom_origin {
      domain_name = aws_api_gateway_rest_api.main.execution_arn
      http_port   = 80
      https_port  = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "APIGateway"

    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "Main CloudFront Distribution"
  }
}

resource "aws_api_gateway_rest_api" "main" {
  name        = "Main API"
  description = "Main API for the application"

  tags = {
    Name = "Main API"
  }
}

resource "aws_lambda_function" "main" {
  function_name = "MainLambdaFunction"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "Main Lambda Function"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "MainECSCluster"

  tags = {
    Name = "Main ECS Cluster"
  }
}

resource "aws_ecs_task_definition" "main" {
  family                   = "MainTaskDefinition"
  network_mode             = "awsvpc"
  requires_compatibilities  = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "MainContainer"
    image     = "my-image:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort     = 80
      protocol     = "tcp"
    }]
  }])

  tags = {
    Name = "Main ECS Task Definition"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "main-rds-cluster"
  engine                 = "aurora-postgresql"
  master_username        = "admin"
  master_password        = "password"
  skip_final_snapshot    = true
  database_name          = "mydatabase"

  tags = {
    Name = "Main RDS Cluster"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "MainDynamoDBTable"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "Main DynamoDB Table"
  }
}

resource "aws_elasticache_cluster" "main" {
  cluster_id           = "main-elasticache"
  engine               = "redis"
  node_type            = "cache.t2.micro"
  num_cache_nodes      = 1

  tags = {
    Name = "Main ElastiCache Cluster"
  }
}

resource "aws_sqs_queue" "main" {
  name = "MainSQSQueue"

  tags = {
    Name = "Main SQS Queue"
  }
}

resource "aws_sns_topic" "main" {
  name = "MainSNSTopic"

  tags = {
    Name = "Main SNS Topic"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/MainLambdaFunction"

  retention_in_days = 14

  tags = {
    Name = "Main CloudWatch Log Group"
  }
}

resource "aws_cloudtrail" "main" {
  name                          = "MainCloudTrail"
  s3_bucket_name                = aws_s3_bucket.main.bucket
  is_multi_region_trail         = true
  enable_logging                = true

  tags = {
    Name = "Main CloudTrail"
  }
}

resource "aws_xray_daemon" "main" {
  name = "MainXRayDaemon"

  tags = {
    Name = "Main X-Ray Daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
