provider "aws" {
  region  = var.region
  profile = "default"

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "ap-southeast-1"
}

variable "api_gateway_name" {
  description = "The name of the API Gateway"
  default     = "my-api-gateway"
}

variable "lambda_function_name" {
  description = "The name of the Lambda function"
  default     = "my-lambda-function"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

data "aws_availability_zones" "available" {}

module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name                  = "my-vpc"
  cidr                  = var.vpc_cidr
  azs                   = data.aws_availability_zones.available.names
  public_subnets       = var.public_subnet_cidrs
  private_subnets      = var.private_subnet_cidrs
  enable_nat_gateway    = true
  single_nat_gateway    = true
  enable_dns_support    = true
  enable_dns_hostnames  = true
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  description = "Security group for Lambda function"
  vpc_id      = module.vpc.vpc_id

  ingress {
    description = "Allow API Gateway to invoke Lambda"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x" # Change as per your code
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip" # Path to your zipped Lambda function code
  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    # Add environment variables if needed
  }

  vpc_config {
    subnet_ids         = module.vpc.private_subnets
    security_group_ids = [aws_security_group.lambda_sg.id]
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.lambda_function_name}-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect    = "Allow"
        Sid       = ""
      },
    ]
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = var.api_gateway_name
  description = "API Gateway for Lambda integration"
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource" # Change as needed
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id             = aws_api_gateway_rest_api.api.id
  resource_id             = aws_api_gateway_resource.resource.id
  http_method             = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_lambda_permission" "allow_api_gateway" {
  statement_id  = "AllowAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.my_lambda.function_name
  principal     = "apigateway.amazonaws.com"

  # The source ARN allows only the specific API Gateway to invoke the Lambda function
  source_arn = "${aws_api_gateway_rest_api.api.execution_arn}/*/*"
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name              = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14 # Change as needed
}

output "api_gateway_url" {
  value = "${aws_api_gateway_rest_api.api.execution_arn}/myresource"
  description = "The URL of the API Gateway"
}",
  "diagram": "graph TD
    User([User / Client])
    AWS_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    AWS_CloudWatch[CloudWatch]
    User --> AWS_API_Gateway
    AWS_API_Gateway --> AWS_Lambda
    AWS_Lambda -->|metrics| AWS_CloudWatch"
}

