    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"chat_api\" {\n  name        = \"ChatAPI\"\n  description = \"API for chat application\"\n}\n\nresource \"aws_lambda_function\" \"chat_handler\" {\n  function_name = \"ChatHandler\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n  # Add your code and other settings here\n}\n\nresource \"aws_dynamodb_table\" \"chat_messages\" {\n  name         = \"ChatMessages\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"message_id\"\n    type = \"S\"\n  }\n  # Additional attributes and settings\n}\n\nresource \"aws_sns_topic\" \"chat_notifications\" {\n  name = \"ChatNotifications\"\n}\n\nresource \"aws_cloudfront_distribution\" \"chat_cdn\" {\n  # CloudFront settings here\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_security_group\" \"allow_https\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}",
