variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "project_name" {
  description = "The name of the project"
  default     = "my_project"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.region}b"

  tags = {
    Name = "${var.project_name}-private-subnet"
  }
}

resource "aws_security_group" "public_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-public-sg"
  }
}

resource "aws_security_group" "private_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    security_groups = [aws_security_group.public_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-private-sg"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = {
    Name = "${var.project_name}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "${var.project_name}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri  = aws_lambda_function.my_lambda.invoke_arn
    http_method = "POST"
  }

  tags = {
    Name = "${var.project_name}-api-method"
  }
}

resource "aws_cloudfront_distribution" "distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiGateway"

    custom_origin_config {
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  is_ipv6_enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "${var.project_name}-cloudfront"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "task" {
  family                   = "${var.project_name}-task"
  network_mode             = "awsvpc"
  requires_compatibilities  = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "${var.project_name}-container"
    image     = "my_image:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort     = 80
      protocol     = "tcp"
    }]
  }])

  tags = {
    Name = "${var.project_name}-task"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "${var.project_name}-dynamodb-table"
  }
}

resource "aws_elasticache_cluster" "my_cache" {
  cluster_id           = "${var.project_name}-cache"
  engine               = "redis"
  node_type            = "cache.t2.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"

  tags = {
    Name = "${var.project_name}-elasticache"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  tags = {
    Name = "${var.project_name}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.project_name}-xray-daemon"

  tags = {
    Name = "${var.project_name}-xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}

output "private_subnet_id" {
  value = aws_subnet.private.id
}

output "lambda_function_arn" {
  value = aws_lambda_function.my_lambda.arn
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.ecs_cluster.name
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}

output "elasticache_cluster_id" {
  value = aws_elasticache_cluster.my_cache.cluster_id
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Elastic_Load_Balancer[Elastic Load Balancer]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> AWS_Elastic_Load_Balancer
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Elastic_Load_Balancer --> AWS_Lambda
    AWS_Elastic_Load_Balancer --> Amazon_ECS
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
