  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"telemedicine_function\" {\n  function_name = \"telemedicineHandler\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids         = [aws_subnet.private.id]\n    security_group_ids = [aws_security_group.allow_http.id]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"TelemedicineAPI\"\n}\n\nresource \"aws_rds_cluster\" \"aurora_cluster\" {\n  engine = \"aurora\"\n  master_username = \"admin\"\n  master_password = \"password\"\n  skip_final_snapshot = true\n  db_subnet_group_name = aws_db_subnet_group.default.name\n}\n\nresource \"aws_dynamodb_table\" \"user_sessions\" {\n  name = \"UserSessions\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"SessionID\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_sqs_queue\" \"telemedicine_queue\" {\n  name = \"TelemedicineQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"telemedicine_logs\" {\n  name = \"telemedicine-logs\"\n}\n",
  "diagram": "graph TD\n    User([User])\n    User -->|API Calls| ALB[AWS Application Load Balancer]\n    ALB -->|Route Requests| APIG[Amazon API Gateway]\n    APIG -->|Invoke| Lambda[AWS Lambda]\n    Lambda -->|Read/Write| DB[Amazon Aurora]\n    Lambda -->|Access| NoSQL[Amazon DynamoDB]\n    Lambda -->|Send| Queue[Amazon SQS]\n    Lambda -->|Log| Logs[Amazon CloudWatch]\n"
}

{
  "scenario_summary": "The client needs a high-performance recommendation engine that serves personalized results under 50ms.",
  "architecture": {
    "layers": {
