resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "Example CloudFront Distribution"
  }
}

resource "aws_ecs_cluster" "cluster" {
  name = "example-cluster"

  tags = {
    Name = "Example ECS Cluster"
  }
}

resource "aws_ecs_task_definition" "task" {
  family                   = "example-task"
  network_mode             = "awsvpc"
  requires_compatibilities  = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "example-container"
    image     = "nginx:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort     = 80
      protocol     = "tcp"
    }]
  }])

  tags = {
    Name = "Example ECS Task Definition"
  }
}

resource "aws_opensearch_domain" "domain" {
  domain_name = "example-domain"
  elasticsearch_version = "7.10"

  node_to_node_encryption_options {
    enabled = true
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
    volume_type = "gp2"
  }

  tags = {
    Name = "Example OpenSearch Domain"
  }
}

resource "aws_dynamodb_table" "table" {
  name         = "example-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "Example DynamoDB Table"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "example-queue"

  tags = {
    Name = "Example SQS Queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/example_lambda"

  retention_in_days = 14

  tags = {
    Name = "Example CloudWatch Log Group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "xray-daemon"

  tags = {
    Name = "Example X-Ray Daemon"
  }
}

output "vpc_id" {
