provider "aws" {
  region  = var.region
  profile = "default"

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "ap-southeast-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow Lambda functions to access resources"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_lambda_function" "example" {
  function_name = "example_lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "example_lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect    = "Allow"
        Sid       = ""
      },
    ]
  })

  tags = {
    Name = "lambda_exec_role"
  }
}

resource "aws_ec2_instance" "example" {
  ami           = "ami-0c55b159cbfafe1f0" # Replace with a valid AMI ID
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.lambda_sg.name]

  tags = {
    Name = "example_ec2_instance"
  }
}

resource "aws_ecs_cluster" "example" {
  name = "example-cluster"

  tags = {
    Name = "example-cluster"
  }
}

resource "aws_rds_cluster" "example" {
  cluster_identifier      = "example-cluster"
  engine                 = "aurora"
  master_username        = "admin"
  master_password        = "password"
  skip_final_snapshot    = true
  database_name          = "exampledb"
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "example_rds_cluster"
  }
}

resource "aws_dynamodb_table" "example" {
  name         = "example_table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "example_dynamodb_table"
  }
}

resource "aws_sqs_queue" "example" {
  name = "example_queue"

  tags = {
    Name = "example_sqs_queue"
  }
}

resource "aws_sns_topic" "example" {
  name = "example_topic"

  tags = {
    Name = "example_sns_topic"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/example_lambda"

  retention_in_days = 14

  tags = {
    Name = "example_cloudwatch_log_group"
  }
}

resource "aws_config_configuration_recorder" "example" {
  name     = "example_recorder"
  role_arn = aws_iam_role.lambda_exec.arn

  recording_group {
    all_supported = true
    include_global_resource_types = true
  }
}

resource "aws_cloudtrail" "example" {
  name                          = "example_trail"
  s3_bucket_name                = "example-cloudtrail-bucket"
  is_multi_region_trail        = true
  enable_logging                = true

  tags = {
    Name = "example_cloudtrail"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "lambda_function_name" {
  value = aws_lambda_function.example.function_name
