{
  "scenario_summary": "The client needs a scalable architecture to support a high-throughput real-time leaderboard for a mobile game with 2 million players.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon API Gateway",
        "Elastic Load Balancing"
