variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "environment" {
  description = "Environment name"
  default     = "prod"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "example" {
  function_name = "${var.environment}-example-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"
  tags          = local.common_tags
}

resource "aws_api_gateway_rest_api" "example" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment} environment"
  tags        = local.common_tags
}

resource "aws_cloudfront_distribution" "example" {
  origin {
    domain_name = aws_api_gateway_rest_api.example.execution_arn
    origin_id   = "apiGatewayOrigin"

    custom_origin {
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "POST", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = local.common_tags
}

resource "aws_global_accelerator_accelerator" "example" {
  name = "${var.environment}-accelerator"
  enabled = true
  ip_address_type = "IPV4"
  tags = local.common_tags
}

resource "aws_dynamodb_table" "example" {
  name         = "${var.environment}-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags     = local.common_tags
}

resource "aws_elasticache_cluster" "example" {
  cluster_id           = "${var.environment}-cache"
  engine              = "redis"
  node_type           = "cache.t2.micro"
  num_cache_nodes     = 1
  parameter_group_name = "default.redis3.2"
  tags                = local.common_tags
}

resource "aws_sqs_queue" "example" {
  name = "${var.environment}-queue"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/${aws_lambda_function.example.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "example" {
  name = "${var.environment}-xray-daemon"
  tags = local.common_tags
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = aws_api_gateway_rest_api.example.execution_arn
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.example.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Global_Accelerator[Global Accelerator]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> AWS_Global_Accelerator
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Global_Accelerator --> AWS_Lambda
    AWS_Global_Accelerator --> Amazon_ECS
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray"
}

{
  "scenario_summary": "The client needs a globally distributed CDN to deliver 4K video content efficiently.",
