  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"SocialMediaAPI\"\n}\n\nresource \"aws_lambda_function\" \"process_messages\" {\n  function_name = \"processMessages\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"messages\" {\n  name         = \"Messages\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"MessageId\"\n    type = \"S\"\n  }\n  hash_key = \"MessageId\"\n}\n\nresource \"aws_sns_topic\" \"message_topic\" {\n  name = \"MessageTopic\"\n}\n\nresource \"aws_sqs_queue\" \"message_queue\" {\n  name = \"MessageQueue\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.api.invoke_url\n    origin_id   = \"APIGateway\"\n  }\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/processMessages\"\n}",
