resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-api-sg"
  tags = local.common_tags

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-ecs-sg"
  tags = local.common_tags

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    security_groups = [aws_security_group.api_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-rds-sg"
  tags = local.common_tags

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = var.rds_allocated_storage
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = var.rds_engine_version
  db_name = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  publicly_accessible = false
  skip_final_snapshot = true
  tags = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${local.environment}-my-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  filename = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  environment {
    variables = {
      DB_HOST = aws_db_instance.rds_instance.address
      DB_USER = var.rds_username
      DB_PASS = var.rds_password
    }
  }
  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${local.environment}-api"
  description = "API for ${local.environment} environment"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "myresource"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "APIGatewayOrigin"
  }

  enabled = true
  default_cache_behavior {
    target_origin_id = "APIGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
  }

  tags = local.common_tags
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id = "${local.environment}-redis"
  engine = "redis"
  node_type = var.redis_node_type
  num_cache_nodes = var.redis_node_count
  parameter_group_name = "default.redis3.2"
  security_group_ids = [aws_security_group.ecs_sg.id]
  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${local.environment}-my-queue"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_cloudtrail" "trail" {
  name = "${local.environment}-cloudtrail"
  s3_bucket_name = aws_s3_bucket.trail_bucket.bucket
  is_multi_region_trail = true
  enable_logging = true
  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "cloudfront_domain" {
  value = aws_cloudfront_distribution.cdn.domain_name
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type = string
}

variable "bucket_prefix" {
  description = "Bucket prefix for the S3"
  type = string
  default = "myapp-"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets"
  type = number
  default = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets"
  type = number
  default = 2
}

variable "rds_allocated_storage" {
  description = "Allocated storage for RDS"
  type = number
  default = 20
}

variable "rds_instance_class" {
  description = "Instance class for RDS"
  type = string
  default = "db.t3.micro"
}

variable "rds_engine_version" {
  description = "Engine version for RDS"
  type = string
  default = "14.1"
}

variable "rds_db_name" {
  description = "Database name for RDS"
  type = string
  default = "mydatabase"
}

variable "rds_username" {
  description = "Username for RDS"
  type = string
  default = "admin"
}

variable "rds_password" {
  description = "Password for RDS"
  type = string
  sensitive = true
}

variable "redis_node_type" {
  description = "Node type for ElastiCache Redis"
  type = string
  default = "cache.t3.micro"
}

variable "redis_node_count" {
  description = "Number of nodes for ElastiCache Redis"
  type = number
  default = 1
}

variable "common_tags" {
  description = "Common tags for all resources"
  type = map(string)
  default = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

