provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type for Batch jobs"
  default     = "t3.micro"
}

variable "rds_instance_type" {
  description = "RDS instance type"
  default     = "db.t3.micro"
}

variable "rds_password" {
  description = "RDS master password"
  type        = string
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "batch_sg" {
  name        = "batch-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow Batch jobs to communicate"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "batch-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = var.rds_instance_type
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "mydatabase"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds-instance"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "batch-compute-env"
  type                     = "MANAGED"
  state                   = "ENABLED"

  compute_resources {
    type              = "SPOT"
    min_vCpus        = 0
    max_vCpus        = 16
    desired_vCpus    = 0
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.batch_sg.id]

    tags = {
      Name = "batch-compute-resources"
    }
  }

  service_role = aws_iam_role.batch_service_role.arn
}

resource "aws_iam_role" "batch_service_role" {
  name = "batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })
}

resource "aws_s3_bucket" "bucket" {
  bucket = "my-unique-bucket-name"
  acl    = "private"

  tags = {
    Name = "my-s3-bucket"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "my-queue"

  tags = {
    Name = "my-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/batch/logs"

  retention_in_days = 14

  tags = {
    Name = "batch-log-group"
  }
}

resource "aws_eventbridge_rule" "event_rule" {
  name        = "my-event-rule"
  description = "Trigger for my event"
  event_pattern = jsonencode({
    source = ["aws.batch"]
  })

  tags = {
    Name = "my-event-rule"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.cdn_identity.id
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "my-cloudfront-distribution"
  }
}

resource "aws_cloudfront_origin_access_identity" "cdn_identity" {
