variable "region" {
 type = string
 description = "AWS region."
 default = "us-east-1"
}

variable "vpc_cidr" {
 type = string
 description = "CIDR block for the VPC."
 default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
 type = list(string)
 description = "CIDR blocks for public subnets."
 default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
 type = list(string)
 description = "CIDR blocks for private subnets."
 default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "lambda_function_name" {
 type = string
 description = "Name of the Lambda function."
 default = "MyLambdaFunction"
}

variable "s3_bucket_name" {
 type = string
 description = "Name of the S3 bucket."
 default = "my-app-bucket"
}

variable "cloudfront_price_class" {
 type = string
 description = "Price class for CloudFront."
 default = "PriceClass_100"
}

variable "cloudfront_aliases" {
 type = list(string)
 description = "Alternative domain names (CNAMEs) for CloudFront."
 default = []
}

variable "cloudfront_certificate_arn" {
 type = string
 description = "ACM certificate ARN for CloudFront (required if using aliases)."
 default = null
}

resource "aws_vpc" "main" {
 cidr_block = var.vpc_cidr

 tags = {
   Name = "Main VPC"
   Environment = "Production"
 }
}

resource "aws_subnet" "public" {
 count = length(var.public_subnet_cidrs)
 vpc_id = aws_vpc.main.id
 cidr_block = element(var.public_subnet_cidrs, count.index)
 availability_zone = element(data.aws_availability_zones.available.names, count.index)

 tags = {
   Name = "Public Subnet ${count.index + 1}"
   Environment = "Production"
 }
}

resource "aws_subnet" "private" {
 count = length(var.private_subnet_cidrs)
 vpc_id = aws_vpc.main.id
 cidr_block = element(var.private_subnet_cidrs, count.index)
 availability_zone = element(data.aws_availability_zones.available.names, count.index)

 tags = {
   Name = "Private Subnet ${count.index + 1}"
   Environment = "Production"
 }
}

resource "aws_internet_gateway" "main" {
 vpc_id = aws_vpc.main.id

 tags = {
   Name = "Main Internet Gateway"
   Environment = "Production"
 }
}

resource "aws_route_table" "public" {
 vpc_id = aws_vpc.main.id

 route {
   cidr_block = "0.0.0.0/0"
   gateway_id = aws_internet_gateway.main.id
 }

 tags = {
   Name = "Public Route Table"
   Environment = "Production"
 }
}

resource "aws_route_table_association" "public" {
 count = length(aws_subnet.public)
 subnet_id = aws_subnet.public[count.index].id
 route_table_id = aws_route_table.public.id
}

resource "aws_s3_bucket" "app_bucket" {
 bucket = var.s3_bucket_name
 acl    = "private"

 tags = {
   Name = var.s3_bucket_name
   Environment = "Production"
 }
}

resource "aws_s3_bucket_lifecycle_configuration" "app_bucket" {
 bucket = aws_s3_bucket.app_bucket.id

 rule {
   id     = "TransitionToGlacier"
   status = "Enabled"

   transitions {
     days          = 30
     storage_class = "GLACIER"
   }

   expiration {
     days = 365
   }
 }
}

resource "aws_lambda_function" "app_lambda" {
 function_name = var.lambda_function_name
 s3_bucket     = aws_s3_bucket.app_bucket.id
 s3_key        = "lambda_function.zip"
 handler       = "index.handler"
 runtime       = "nodejs14.x"
 role          = aws_iam_role.lambda_exec.arn

 tags = {
   Name = var.lambda_function_name
   Environment = "Production"
 }
}

resource "aws_iam_role" "lambda_exec" {
 name = "${var.lambda_function_name}-exec"

 assume_role_policy = jsonencode({
   Version = "2012-10-17"
   Statement = [
     {
       Action = "sts:AssumeRole"
       Principal = {
         Service = "lambda.amazonaws.com"
       }
       Effect = "Allow"
       Sid    = ""
     },
   ]
 })

 tags = {
   Name = "${var.lambda_function_name}-exec"
   Environment = "Production"
 }
}

resource "aws_api_gateway_rest_api" "api" {
 name = "MyAPI"
 description = "API for my application"

 tags = {
   Name = "MyAPI"
   Environment = "Production"
 }
}

resource "aws_api_gateway_resource" "resource" {
 rest_api_id = aws_api_gateway_rest_api.api.id
 parent_id   = aws_api_gateway_rest_api.api.root_resource_id
 path_part   = "myresource"

 tags = {
   Name = "MyResource"
   Environment = "Production"
 }
}

resource "aws_api_gateway_method" "method" {
 rest_api_id   = aws_api_gateway_rest_api.api.id
 resource_id   = aws_api_gateway_resource.resource.id
 http_method   = "GET"
 authorization = "NONE"

 integration {
   type = "AWS_PROXY"
   uri  = aws_lambda_function.app_lambda.invoke_arn
 }

 tags = {
   Name = "MyMethod"
   Environment = "Production"
 }
}

resource "aws_cloudfront_distribution" "cdn" {
 origin {
   domain_name = aws_s3_bucket.app_bucket.bucket_regional_domain_name
   origin_id   = "S3Origin"

   s3_origin_config {
     origin_access_identity = aws_cloudfront_origin_access_identity.cdn.iam_arn
   }
 }

 enabled             = true
 is_ipv6_enabled     = true
 default_root_object = "index.html"

 price_class = var.cloudfront_price_class

 restrictions {
   geo_restriction {
     restriction_type = "none"
   }
 }

 viewer_certificate {
   acm_certificate_arn = var.cloudfront_certificate_arn
   ssl_support_method  = "sni-only"
 }

 tags = {
   Name = "MyCDN"
   Environment = "Production"
 }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
 name = "/aws/lambda/${aws_lambda_function.app_lambda.function_name}"

 retention_in_days = 14

 tags = {
   Name = "LambdaLogs"
   Environment = "Production"
 }
}

output "vpc_id" {
