variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "environment" {
  description = "The environment for the deployment (e.g., dev, prod)"
  default     = "prod"
}

variable "db_instance_class" {
  description = "The instance class for the RDS database"
  default     = "db.t3.micro"
}

variable "db_password" {
  description = "The password for the RDS database master user"
  type        = string
  sensitive   = true
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                 = aws_vpc.main.id
  cidr_block             = "10.0.${count.index}.0/24"
  availability_zone      = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
  tags                   = local.common_tags
}

resource "aws_subnet" "private" {
  count          = 2
  vpc_id        = aws_vpc.main.id
  cidr_block    = "10.0.${count.index + 2}.0/24"
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags          = local.common_tags
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

module "rds" {
  source = "terraform-aws-modules/rds/aws"
  name   = "${local.common_tags.Project}-aurora"
  engine = "aurora-postgresql"
  engine_version = "12.4"
  instance_class = var.db_instance_class
  allocated_storage = 20
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags = local.common_tags
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.common_tags.Project}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${local.common_tags.Project}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"
  tags          = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.common_tags.Project}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${local.common_tags.Project}-api"
  description = "API for my project"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"
  }

  enabled             = true
  default_root_object = ""

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
  }

  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${local.common_tags.Project}-queue"
  tags = local.common_tags
}

resource "aws_sns_topic" "my_topic" {
  name = "${local.common_tags.Project}-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "xray" {
  name = "${local.common_tags.Project}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
  description = "The endpoint of the API Gateway"
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.distribution.id
  description = "The ID of the CloudFront distribution"
