  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"HotelBookingAPI\"\n}\n\nresource \"aws_lambda_function\" \"booking_function\" {\n  function_name = \"BookingFunction\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_ecs_cluster\" \"cluster\" {\n  name = \"HotelBookingCluster\"\n}\n\nresource \"aws_rds_cluster\" \"aurora\" {\n  cluster_identifier = \"hotel-booking-cluster\"\n  engine = \"aurora\"\n  master_username = \"admin\"\n  master_password = \"Password123\"\n  skip_final_snapshot = true\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"hotel-cache\"\n  engine = \"redis\"\n  node_type = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}\n\nresource \"aws_sqs_queue\" \"booking_queue\" {\n  name = \"BookingQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/BookingFunction\"\n}",
