    {
      "decision": "Amazon S3 vs Amazon EFS for video storage",
      "chose": "Amazon S3",
      "reason": "Amazon S3 provides lower costs and better scalability for storing large video files compared to Amazon EFS.",
      "when_to_switch": "If low-latency access to frequently accessed files becomes a requirement, Amazon EFS might be more appropriate."
    },
    {
      "decision": "Amazon API Gateway vs AWS Load Balancer",
      "chose": "Amazon API Gateway",
      "reason": "Amazon API Gateway provides built-in features for managing APIs, including traffic management and authorization, suitable for handling user uploads.",
      "when_to_switch": "If there is a need for more complex networking configurations or if the application grows into a microservices architecture."
    }
  ],
