  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_security_group\" \"allow_https\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_elastic_load_balancing_v2_load_balancer\" \"main\" {\n  name               = \"main-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"ci_cd_lambda\" {\n  filename         = \"function.zip\"\n  function_name    = \"ciCdFunction\"\n  handler          = \"index.handler\"\n  runtime          = \"nodejs14.x\"\n  role             = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_rds_instance\" \"main\" {\n  identifier = \"main-db\"\n  engine     = \"mysql\"\n  instance_class = \"db.t3.micro\"\n  allocated_storage = 20\n  db_name = \"cidc\"\n  username = \"admin\"\n  password = \"Password123\"\n  skip_final_snapshot = true\n}\n\nresource \"aws_dynamodb_table\" \"ci_cd_table\" {\n  name         = \"ciCdTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sqs_queue\" \"ci_cd_queue\" {\n  name = \"ciCdQueue\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"ci_cd_api\" {\n  name = \"ciCdApi\"\n}\n",
  "diagram": "graph TD\n    User([User])\n    User -->|Access CI/CD| ELB[Elastic Load Balancer]\n    ELB -->|Route to| Lambda[AWS Lambda]\n    ELB -->|Route to| ECS[Amazon ECS]\n    Lambda -->|Read/Write| RDS[Amazon RDS]\n    Lambda -->|Read/Write| DynamoDB[Amazon DynamoDB]\n    Lambda -->|Send Messages| SQS[Amazon SQS]\n    CloudWatch[CloudWatch] -->|Monitor| Lambda\n    CloudWatch -->|Monitor| ECS"
}

{
  "scenario_summary": "The client needs an event-driven architecture for an e-commerce order fulfillment system.",
  "architecture": {
