  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1b\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"order_processor\" {\n  function_name = \"orderProcessor\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"OrderAPI\"\n}\n\nresource \"aws_dynamodb_table\" \"orders\" {\n  name           = \"Orders\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"OrderId\"\n    type = \"S\"\n  }\n  hash_key = \"OrderId\"\n}\n\nresource \"aws_sqs_queue\" \"order_queue\" {\n  name = \"OrderQueue\"\n}\n\nresource \"aws_sns_topic\" \"order_topic\" {\n  name = \"OrderTopic\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.api.execution_arn\n    origin_id   = \"APIGateway\"\n  }\n}\n",
  "diagram": "graph TD\n    User([User])\n    User-->API[API Gateway]\n    API-->Lambda[AWS Lambda]\n    Lambda-->SQS[Amazon SQS]\n    SQS-->DynamoDB[Amazon DynamoDB]\n    Lambda-->SNS[Amazon SNS]\n    SNS-->RDS[Amazon RDS]\n    CloudFront[Amazon CloudFront]-->User"
}

{
