variable "aws_region" {
  description = "AWS region to launch resources."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type."
  default     = "t2.micro"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "PublicSubnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.private_subnet_cidrs, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "PrivateSubnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow SSH and HTTP access to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow SSH from anywhere"
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow HTTP from anywhere"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = {
    Name = "EC2SecurityGroup"
  }
}

resource "aws_instance" "web" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "WebServer"
  }
}

resource "aws_lambda_function" "example" {
  function_name = "example_lambda"
  s3_bucket     = "your-bucket-name"
  s3_key        = "lambda_function.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    key = "value"
  }

  tags = {
    Name = "ExampleLambda"
  }
}

resource "aws_ecs_cluster" "example" {
  name = "example-cluster"

  tags = {
    Name = "ExampleECSCluster"
  }
}

resource "aws_rds_instance" "example" {
  identifier              = "example-db"
  engine                 = "mysql"
  instance_class         = "db.t2.micro"
  allocated_storage       = 20
  db_subnet_group_name    = aws_db_subnet_group.example.name
  vpc_security_group_ids  = [aws_security_group.ec2_sg.id]
  username               = "admin"
  password               = "password"
  skip_final_snapshot    = true

  tags = {
    Name = "ExampleRDS"
  }
}

resource "aws_dynamodb_table" "example" {
  name         = "example_table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "ExampleDynamoDB"
  }
}

resource "aws_sqs_queue" "example" {
  name = "example-queue"

  tags = {
    Name = "ExampleSQS"
  }
}

resource "aws_sns_topic" "example" {
  name = "example-topic"

  tags = {
    Name = "ExampleSNS"
  }
}

resource "aws_cloudtrail" "example" {
  name                          = "example-cloudtrail"
  s3_bucket_name                = "your-cloudtrail-bucket"
  is_multi_region_trail         = true
  enable_logging                = true

  tags = {
    Name = "ExampleCloudTrail"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name              = "example-log-group"
  retention_in_days = 14

  tags = {
    Name = "ExampleCloudWatchLogGroup"
  }
}

resource "aws_config_configuration_recorder" "example" {
  name     = "example-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "example" {
  name           = "example-delivery-channel"
  s3_bucket_name = "your-config-bucket"

  depends_on = [aws_config_configuration_recorder.example]
}

resource "aws_transit_gateway" "example" {
  description = "Example Transit Gateway"

  tags = {
    Name = "ExampleTransitGateway"
