        {
          "service": "Amazon S3",
          "monthly_usd": 20.0,
          "unit": "Storage for uploaded videos"
        },
        {
          "service": "AWS Lambda",
          "monthly_usd": 15.0,
          "unit": "Invocation costs for transcoding"
        },
        {
          "service": "Amazon DynamoDB",
          "monthly_usd": 10.0,
          "unit": "Storage and read/write costs"
        },
        {
          "service": "Amazon SQS",
          "monthly_usd": 5.0,
          "unit": "Message processing"
        },
        {
          "service": "Amazon CloudFront",
