    {
      "decision": "EC2 vs Lambda for compute",
      "chose": "EC2",
      "reason": "EC2 provides more control over the environment and is suitable for long-running processes typical in banking applications, while Lambda is limited to short execution times.",
      "when_to_switch": "If the application can be decomposed into smaller, stateless functions that can run under the 15-minute execution limit, Lambda could be considered for cost savings and automatic scaling."
    },
    {
      "decision": "RDS vs DynamoDB for database",
      "chose": "RDS",
      "reason": "RDS offers relational database capabilities with ACID compliance, which is crucial for banking transactions, while DynamoDB is better suited for high-speed key-value access.",
      "when_to_switch": "If the application requires rapid scaling with high throughput and can tolerate eventual consistency, DynamoDB would be a better fit."
    },
    {
      "decision": "SQS vs SNS for messaging",
      "chose": "SQS",
      "reason": "SQS provides reliable message queuing with guaranteed delivery, which is essential for processing banking transactions without loss, while SNS is more suited for pub/sub scenarios.",
      "when_to_switch": "If the architecture requires real-time notifications to multiple subscribers, SNS would be more appropriate."
    },
    {
      "decision": "Global Accelerator vs Route 53 for networking",
      "chose": "Global Accelerator",
      "reason": "Global Accelerator provides improved performance and availability by routing traffic to the optimal endpoint, while Route 53 primarily handles DNS resolution.",
