  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

variable "region" {
  description = "AWS region to launch resources."
  default     = "ap-south-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_instance_type" {
  description = "Instance type for RDS."
  default     = "db.t3.micro"
}

variable "batch_instance_type" {
  description = "Instance type for AWS Batch."
  default     = "optimal"
}

variable "key_name" {
  description = "Name of the key pair for EC2 instances."
  default     = "terraform-poc01"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "batch_sg" {
  name        = "batch_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow AWS Batch to access resources"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "batch_sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS from private subnets"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [for subnet in aws_subnet.private : subnet.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = var.rds_instance_type
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "batch-compute-environment"
  type                     = "MANAGED"
  state                    = "ENABLED"

  compute_resources {
    type              = "SPOT"
    min_vcpus        = 0
    max_vcpus        = 16
    desired_vcpus    = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.batch_instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.batch_sg.id]

    tags = {
      Name = "batch_compute_resources"
    }
  }

  service_role = "AWSBatchServiceRole"
}

resource "aws_s3_bucket" "bucket" {
  bucket = "my-unique-bucket-name-123456"
  acl    = "private"

  tags = {
    Name = "my_s3_bucket"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "my-sqs-queue"

  tags = {
    Name = "my_sqs_queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = "/aws/batch/logs"
  retention_in_days = 14

  tags = {
    Name = "batch_log_group"
  }
}

resource "aws_step_functions_state_machine" "state_machine" {
  name     = "my-state-machine"
  role_arn = "arn:aws:iam::123456789012:role/service-role/MyRole"

  definition = jsonencode({
    StartAt = "MyTask",
    States = {
      MyTask = {
        Type = "Task",
        Resource = "arn:aws:lambda:us-east-1:123456789012:function:my-function",
        End = true
      }
    }
  })

  tags = {
    Name = "my_step_function"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.bucket.bucket
}

output "sqs_queue_url" {
  value = aws_sqs_queue.queue.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_VPC[VPC]
    AWS_PrivateLink[PrivateLink]
    AWS_Batch[Batch]
    EC2_Spot_Instances[EC2 Spot Instances]
    Amazon_RDS[(RDS)]
    Amazon_S3[(S3)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_Step_Functions[Step Functions]
    User --> Amazon_VPC
    User --> AWS_PrivateLink
    Amazon_VPC --> AWS_Batch
    Amazon_VPC --> EC2_Spot_Instances
    AWS_PrivateLink --> AWS_Batch
    AWS_PrivateLink --> EC2_Spot_Instances
    AWS_Batch --> Amazon_RDS
    AWS_Batch --> Amazon_S3
    EC2_Spot_Instances --> Amazon_RDS
    EC2_Spot_Instances --> Amazon_S3
    AWS_Batch --> Amazon_SQS
    EC2_Spot_Instances --> Amazon_SQS
    AWS_Batch -->|metrics| Amazon_CloudWatch
    AWS_Batch -->|metrics| AWS_Step_Functions
    EC2_Spot_Instances -->|metrics| Amazon_CloudWatch
    EC2_Spot_Instances -->|metrics| AWS_Step_Functions"
}

