  "terraform": "locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Purpose     = "Production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = local.common_tags
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  environment {
    DYNAMODB_TABLE = aws_dynamodb_table.main.name
  }

  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-dynamodb"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = local.common_tags
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "${var.environment}-rds-cluster"
  engine                 = "aurora-postgresql"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true
  vpc_security_group_ids = [aws_security_group.api_sg.id]

  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${var.environment}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "api"
    image     = var.api_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_ecs_service" "api" {
  name            = "${var.environment}-api-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.api.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.api_sg.id]
    assign_public_ip = false
  }

  tags = local.common_tags
}

resource "aws_sqs_queue" "main" {
  name = "${var.environment}-sqs-queue"

  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "${var.environment}-sns-topic"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "${var.environment}-xray-daemon"

  tags = local.common_tags
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "rds_cluster_endpoint" {
  value = aws_rds_cluster.main.endpoint
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}",
