variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "environment" {
  description = "The environment for the deployment (e.g., dev, prod)"
  default     = "prod"
}

variable "api_gateway_name" {
  description = "The name of the API Gateway"
  default     = "MyApiGateway"
}

variable "lambda_function_name" {
  description = "The name of the Lambda function"
  default     = "MyLambdaFunction"
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket"
  default     = "my-s3-bucket-${var.environment}"
}

variable "cloudfront_distribution_name" {
  description = "The name of the CloudFront distribution"
  default     = "MyCloudFrontDistribution"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index}.0/24"
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 2}.0/24"
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

resource "aws_s3_bucket" "main" {
  bucket = var.s3_bucket_name
  acl    = "private"
  tags   = local.common_tags
}

resource "aws_lambda_function" "main" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.main.bucket
  s3_key        = "lambda.zip" # Assuming the zip file is uploaded to S3
  tags          = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${var.environment}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "main" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "lambda" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "lambda"
}

resource "aws_api_gateway_method" "get" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.lambda.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.lambda.id
  http_method             = aws_api_gateway_method.get.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.main.invoke_arn
}

resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${aws_lambda_function.main.function_name}"
  retention_in_days = 14
  tags              = local.common_tags
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway_rest_api.main.execution_arn
    origin_id   = "ApiGatewayOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "ApiGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = local.common_tags
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.main.execution_arn
}

output "lambda_function_arn" {
  value = aws_lambda_function.main.arn
}

output "cloudfront_distribution_domain" {
  value = aws_cloudfront_distribution.main.domain_name
}",
  "diagram": "graph TD
    User([User / Client])
    CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_S3[(S3)]
    Amazon_S3_Standard_IA[(S3 Standard-IA)]
    Amazon_S3_Glacier[(S3 Glacier)]
    Amazon_CloudWatch[CloudWatch]
    User --> CloudFront
    CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_S3
    AWS_Lambda --> Amazon_S3_Standard_IA
    AWS_Lambda --> Amazon_S3_Glacier
    AWS_Lambda -->|metrics| Amazon_CloudWatch"
}

