  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lb\" \"main\" {\n  name               = \"app-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"app\" {\n  function_name = \"insurancePortalFunction\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids = [aws_subnet.private.id]\n    security_group_ids = [aws_security_group.allow_http.id]\n  }\n}\n\nresource \"aws_rds_cluster\" \"aurora\" {\n  cluster_identifier = \"insurance-portal-cluster\"\n  engine            = \"aurora\"\n  master_username   = \"admin\"\n  master_password   = \"password\"\n  skip_final_snapshot = true\n  db_subnet_group_name = aws_db_subnet_group.main.name\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"insurance-portal-cache\"\n  engine     = \"redis\"\n  node_type = \"cache.t2.micro\"\n  num_cache_nodes = 1\n  subnet_group_name = aws_elasticache_subnet_group.main.name\n}\n\nresource \"aws_sqs_queue\" \"queue\" {\n  name = \"insurance-portal-queue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"insurance-portal-logs\"\n}",
