provider "aws" {
  region  = var.aws_region
  profile = "default"
}

data "aws_availability_zones" "available" {}

# VPC Module
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  name = "${var.environment}-vpc"
  cidr = var.vpc_cidr

  azs                  = data.aws_availability_zones.available.names
  private_subnets     = var.private_subnets
  public_subnets      = var.public_subnets
  enable_nat_gateway   = true
  single_nat_gateway   = true
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

# Security Group for RDS
resource "aws_security_group" "rds_security_group" {
  name        = "${var.environment}-rds-sg"
  vpc_id      = module.vpc.vpc_id
  description = "Allow access to RDS from application servers"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "rds_instance" {
  allocated_storage    = var.rds_allocated_storage
  identifier          = "${var.environment}-rds"
  instance_class      = var.rds_instance_class
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = var.db_name
  username            = var.db_username
  password            = var.db_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "${var.environment}-rds"
  }
}

# Security Group for EC2
resource "aws_security_group" "ec2_security_group" {
  name        = "${var.environment}-ec2-sg"
  vpc_id      = module.vpc.vpc_id
  description = "Allow access to EC2 instances"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-ec2-sg"
  }
}

# EC2 Instance with Reserved Instances
resource "aws_instance" "app_instance" {
  count             = var.ec2_instance_count
  ami               = var.ec2_ami
  instance_type    = var.ec2_instance_type
  subnet_id        = element(module.vpc.private_subnets, count.index)
  security_groups   = [aws_security_group.ec2_security_group.name]

  tags = {
    Name = "${var.environment}-app-instance-${count.index}"
  }
}

# Elastic Load Balancer
resource "aws_elb" "app_elb" {
  name               = "${var.environment}-app-elb"
  availability_zones = module.vpc.public_subnets

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.environment}-app-elb"
  }
}

# AWS Lambda Function
resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-my-lambda"
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    variables = {
      DB_HOST = aws_db_instance.rds_instance.endpoint
    }
  }

  tags = {
    Name = "${var.environment}-my-lambda"
  }
}

# Amazon SQS Queue
resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-my-queue"

  tags = {
    Name = "${var.environment}-my-queue"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.environment}-lambda-log-group"
  }
}

# AWS X-Ray Daemon
resource "aws_lambda_function" "xray_daemon" {
  function_name = "${var.environment}-xray-daemon"
  s3_bucket     = var.xray_s3_bucket
