{
  "scenario_summary": "The client needs a resilient architecture capable of handling AWS region outages with automatic failover.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "AWS Global Accelerator",
        "Application Load Balancer"
      ],
      "compute": [
        "Amazon ECS with Fargate",
        "AWS Lambda"
      ],
      "database": [
        "Amazon RDS with Multi-AZ",
        "Amazon DynamoDB"
