provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_username" {
  description = "Username for the RDS database."
  type        = string
}

variable "db_password" {
  description = "Password for the RDS database."
  type        = string
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  type        = string
  default     = "my-ecs-cluster"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "my-lambda-function"
}

variable "rds_instance_type" {
  description = "Instance type for RDS."
  type        = string
  default     = "db.t3.micro"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "my-dynamodb-table"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic."
  type        = string
  default     = "my-sns-topic"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue."
  type        = string
  default     = "my-sqs-queue"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_db_instance" "default" {
  identifier         = "my-rds-instance"
  engine             = "mysql"
  engine_version     = "8.0"
  instance_class     = var.rds_instance_type
  allocated_storage   = 20
  username           = var.db_username
  password           = var.db_password
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  multi_az           = true
  skip_final_snapshot = true

  tags = {
    Name = "my-rds-instance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "my-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "my-db-subnet-group"
  }
}

resource "aws_dynamodb_table" "default" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_sns_topic" "default" {
  name = var.sns_topic_name

  tags = {
    Name = var.sns_topic_name
  }
}

resource "aws_sqs_queue" "default" {
  name = var.sqs_queue_name

  tags = {
    Name = var.sqs_queue_name
  }
}

resource "aws_lambda_function" "default" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })

  tags = {
    Name = "lambda_exec_role"
  }
}

resource "aws_cloudwatch_log_group" "default" {
  name = "/aws/lambda/${aws_lambda_function.default.function_name}"

  retention_in_days = 14

  tags = {
    Name = "cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "default" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

resource "aws_cloudfront_distribution" "default" {
  origin {
    domain_name = aws_s3_bucket.lambda_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "cloudfront-distribution"
  }
}

resource "aws_global_accelerator" "default" {
  name = "my-global-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  tags = {
    Name = "global-accelerator"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "rds_endpoint" {
  description = "RDS Endpoint"
  value       = aws_db_instance.default.endpoint
}

output "dynamodb_table_name" {
  description = "DynamoDB Table Name"
  value       = aws_dynamodb_table.default.name
}

output "sns_topic_arn" {
  description = "SNS Topic ARN"
  value       = aws_sns_topic.default.arn
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.default.id
}

output "lambda_function_name" {
  description = "Lambda Function Name"
  value       = aws_lambda_function.default.function_name
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.default.id
}

output "global_accelerator_arn" {
  description = "Global Accelerator ARN"
  value       = aws_global_accelerator.default.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    AWS_Global_Accelerator[Global Accelerator]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS_with_Fargate[ECS with Fargate]
    AWS_Lambda[Lambda]
    Amazon_RDS_with_Multi_AZ[(RDS with Multi-AZ)]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SNS[SNS]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> AWS_Global_Accelerator
    Amazon_CloudFront --> Application_Load_Balancer
    AWS_Global_Accelerator --> Amazon_ECS_with_Fargate
    AWS_Global_Accelerator --> AWS_Lambda
    Application_Load_Balancer --> Amazon_ECS_with_Fargate
    Application_Load_Balancer --> AWS_Lambda
    Amazon_ECS_with_Fargate --> Amazon_RDS_with_Multi_AZ
    Amazon_ECS_with_Fargate --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_RDS_with_Multi_AZ
    AWS_Lambda --> Amazon_DynamoDB
    Amazon_ECS_with_Fargate --> Amazon_SNS
    Amazon_ECS_with_Fargate --> Amazon_SQS
    AWS_Lambda --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS_with_Fargate -->|metrics| Amazon_CloudWatch
    Amazon_ECS_with_Fargate -->|metrics| AWS_X_Ray
    AWS_Lambda -->|metrics| Amazon_CloudWatch
