  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"LeaderboardAPI\"\n}\n\nresource \"aws_lambda_function\" \"leaderboard_function\" {\n  function_name = \"UpdateLeaderboard\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"leaderboard_table\" {\n  name           = \"Leaderboard\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"PlayerID\"\n    type = \"S\"\n  }\n  key_schema {\n    attribute_name = \"PlayerID\"\n    key_type = \"HASH\"\n  }\n}\n\nresource \"aws_kinesis_stream\" \"score_updates\" {\n  name = \"ScoreUpdates\"\n  shard_count = 1\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.api.execution_arn\n    origin_id   = \"APIGateway\"\n  }\n}\n\nresource \"aws_ecs_cluster\" \"game_cluster\" {\n  name = \"GameLeaderboardCluster\"\n}",
