    Amazon_SageMaker_with_GPU_instances_e_g[SageMaker with GPU instances (e.g.]
    Amazon_S3_for_data_storage[(S3 for data storage)]
    Amazon_RDS_for_metadata_management[(RDS for metadata management)]
    Amazon_SQS_for_job_queueing[SQS for job queueing]
