variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "Main VPC"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ECS Security Group"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Lambda Security Group"
  }
}

resource "aws_rds_cluster" "main" {
  engine         = "aurora"
  engine_mode    = "provisioned"
  master_username = "admin"
  master_password = "password"
  database_name   = "mydb"
  skip_final_snapshot = true
  storage_encrypted = true

  availability_zones = data.aws_availability_zones.available.names

  tags = {
    Name = "RDS Cluster"
  }
}

resource "aws_dynamodb_table" "global_table" {
  name         = "my-global-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  global_secondary_index {
    name            = "GSI1"
    hash_key        = "gsi1pk"
    projection_type = "ALL"

    attribute {
      name = "gsi1pk"
      type = "S"
    }
  }

  tags = {
    Name = "Global DynamoDB Table"
  }
}

resource "aws_sqs_queue" "main" {
  name = "my-queue"

  tags = {
    Name = "SQS Queue"
  }
}

resource "aws_sns_topic" "main" {
  name = "my-topic"

  tags = {
    Name = "SNS Topic"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "My Lambda Function"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/my_lambda_function"

  tags = {
    Name = "CloudWatch Log Group"
  }
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_s3_bucket.lambda_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.main.id
    }
  }

  enabled             = true
  default_root_object = "index.html"

  tags = {
    Name = "CloudFront Distribution"
  }
}

resource "aws_global_accelerator" "main" {
  name = "my-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  tags = {
    Name = "Global Accelerator"
  }
}

resource "aws_route53_zone" "main" {
  name = "example.com"

  tags = {
    Name = "Route 53 Zone"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "rds_endpoint" {
  value = aws_rds_cluster.main.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.global_table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
}

output "global_accelerator_arn" {
  value = aws_global_accelerator.main.arn
}

output "route53_zone_id" {
  value = aws_route53_zone.main.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_Route_53[Route 53]
    AWS_Global_Accelerator[Global Accelerator]
    Amazon_ECS[ECS]
    AWS_Lambda[Lambda]
    Amazon_RDS[(RDS)]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SQS[SQS]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_Route_53
    Amazon_CloudFront --> AWS_Global_Accelerator
    Amazon_Route_53 --> Amazon_ECS
    Amazon_Route_53 --> AWS_Lambda
    AWS_Global_Accelerator --> Amazon_ECS
    AWS_Global_Accelerator --> AWS_Lambda
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_SQS
    Amazon_ECS --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray"
}

{
