    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"CRM API\"\n}\n\nresource \"aws_lambda_function\" \"crm_function\" {\n  function_name = \"CRMFunction\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"crm_table\" {\n  name         = \"CRMTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sns_topic\" \"crm_topic\" {\n  name = \"CRMTopic\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"crm_logs\" {\n  name = \"/aws/lambda/CRMFunction\"\n}",
