  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.49.0"
    }
  }
  required_version = "~> 1.9.3"
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_class" {
  description = "RDS instance class"
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "Database name"
  default     = "mydb"
}

variable "db_username" {
  description = "Database username"
  default     = "admin"
}

variable "db_password" {
  description = "Database password"
  sensitive   = true
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-lambda-sg"
  }
}

resource "aws_db_instance" "default" {
  identifier         = "${var.environment}-db"
  engine             = "postgres"
  instance_class     = var.db_instance_class
  allocated_storage   = 20
  db_name            = var.db_name
  username           = var.db_username
  password           = var.db_password
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]
  db_subnet_group_name = aws_db_subnet_group.default.name

  tags = {
    Name = "${var.environment}-db-instance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.environment}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.environment}-db-subnet-group"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-my-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  environment {
    DB_HOST     = aws_db_instance.default.endpoint
    DB_USERNAME = var.db_username
    DB_PASSWORD = var.db_password
  }

  tags = {
    Name = "${var.environment}-my-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      }
    ]
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for my application"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "${var.environment}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type             = "AWS_PROXY"
    integration_http_method = "POST"
    uri              = aws_lambda_function.my_lambda.invoke_arn
  }

  tags = {
    Name = "${var.environment}-api-method"
  }
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = "${var.environment}-my-bucket"
  acl    = "private"

  tags = {
    Name = "${var.environment}-my-bucket"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "${var.environment}-my-topic"

  tags = {
    Name = "${var.environment}-my-topic"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-my-queue"

  tags = {
    Name = "${var.environment}-my-queue"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.environment}-my-log-group"
  }
}

resource "aws_cloudtrail" "my_cloudtrail" {
  name                          = "${var.environment}-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.my_bucket.bucket
  is_multi_region_trail         = true
  enable_log_file_validation     = true
  include_global_service_events  = true

  tags = {
    Name = "${var.environment}-cloudtrail"
  }
}

output "api_endpoint" {
  value = "${aws_api_gateway_rest_api.api.execution_arn}/myresource"
}

output "db_endpoint" {
  value = aws_db_instance.default.endpoint
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    AWS_SageMaker[SageMaker]
    AWS_Lambda[Lambda]
    Amazon_RDS[(RDS)]
    Amazon_S3[(S3)]
    Amazon_SNS[SNS]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_CloudTrail[CloudTrail]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> AWS_Lambda
    Amazon_API_Gateway --> AWS_SageMaker
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> AWS_SageMaker
    AWS_Lambda --> AWS_Lambda
    AWS_SageMaker --> Amazon_RDS
    AWS_SageMaker --> Amazon_S3
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_S3
    AWS_SageMaker --> Amazon_SNS
    AWS_SageMaker --> Amazon_SQS
    AWS_Lambda --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    AWS_SageMaker -->|metrics| Amazon_CloudWatch
    AWS_SageMaker -->|metrics| AWS_CloudTrail
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_CloudTrail"
}

{
  "scenario_summary": "The client needs a cost-optimized AWS architecture for a SaaS dashboard to serve 20,000 daily active users.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Application Load Balancer",
        "Amazon API Gateway"
      ],
      "compute": [
        "AWS Lambda",
        "Amazon ECS"
      ],
      "database": [
        "Amazon DynamoDB"
      ],
      "messaging": [
        "Amazon SNS"
      ],
      "monitoring": [
        "Amazon CloudWatch"
      ]
    },
    "reasoning": "The architecture leverages Amazon CloudFront as a CDN to cache static assets and reduce latency for global users. By using AWS Lambda, we ensure that the dashboard can easily scale with demand, as Lambda automatically handles the scaling based on the number of requests. For the compute layer, Amazon ECS with Fargate is used to host any containerized services, providing flexibility and cost savings by allowing us to pay for only the resources we use. The use of Amazon DynamoDB as the database ensures no server management overhead and offers auto-scaling capabilities to handle unpredictable workloads effectively.\n\nUsing Amazon API Gateway, we can manage the APIs securely and efficiently, with built-in throttling and caching features. For messaging, Amazon SNS is incorporated to facilitate any asynchronous communication or notifications needed by the application. The entire solution is monitored using Amazon CloudWatch, which enables us to gather metrics and set up alarms based on usage patterns. This architecture emphasizes reliability and cost-effectiveness while providing a solid foundation for scaling as the user base grows.",
    "trade_offs": [
      {
        "decision": "AWS Lambda vs Amazon EC2",
        "chose": "AWS Lambda",
        "reason": "AWS Lambda is more cost-effective for variable workloads because it charges based on the number of requests and execution time, while EC2 requires provisioning for peak usage which can lead to higher costs.",
        "when_to_switch": "If the application requires consistent and predictable workloads that exceed Lambda's limits or needs specific OS-level access."
      },
      {
        "decision": "Amazon DynamoDB vs Amazon RDS",
        "chose": "Amazon DynamoDB",
        "reason": "DynamoDB offers a fully managed, serverless database that scales automatically and has a predictable pricing model based on read/write capacity, which is better suited for high traffic scenarios.",
        "when_to_switch": "If complex transactions or relational data models become necessary that are better suited for a relational database like RDS."
      },
      {
        "decision": "Application Load Balancer vs Network Load Balancer",
        "chose": "Application Load Balancer",
        "reason": "Application Load Balancer provides advanced routing features, such as path-based routing and host-based routing, which are ideal for microservices architectures, while being cost-effective for HTTP/HTTPS traffic.",
        "when_to_switch": "If the application needs to handle millions of requests per second with low latency and TCP traffic, a Network Load Balancer would be preferable."
      }
    ],
    "cost": {
      "monthly_breakdown": [
        {
          "service": "AWS Lambda",
          "monthly_usd": 45.0,
          "unit": "1M requests"
        },
        {
          "service": "Amazon DynamoDB",
          "monthly_usd": 50.0,
          "unit": "25GB storage"
        },
        {
          "service": "Amazon CloudFront",
          "monthly_usd": 10.0,
          "unit": "data transfer"
        },
        {
          "service": "Application Load Balancer",
