          "monthly_usd": 5.0,
          "unit": "100,000 notifications"
        },
        {
          "service": "Amazon CloudWatch",
          "monthly_usd": 5.0,
          "unit": "basic monitoring"
        }
      ],
      "total_monthly_usd": 150.0,
      "spike_estimate_usd": 200.0,
      "optimization": "Implement DynamoDB On-Demand mode to optimize costs during variable workloads and leverage AWS Free Tier for new users."
    },
    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet2\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"function\" {\n  function_name = \"my_lambda_function\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"my_api\"\n}\n\nresource \"aws_dynamodb_table\" \"my_table\" {\n  name         = \"my_table\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  key_schema {\n    attribute_name = \"id\"\n    key_type      = \"HASH\"\n  }\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.api.execution_arn\n    origin_id   = \"api_origin\"\n  }\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/my_lambda_function\"\n}",
    "diagram": "graph TD\n    User([User])\n    User -->|HTTP Request| ALB(Application Load Balancer)\n    ALB -->|Route to| API[API Gateway]\n    API -->|Invoke| Lambda[AWS Lambda]\n    Lambda -->|Read/Write| DB[Amazon DynamoDB]\n    DB -->|Triggers| SNS[Amazon SNS]\n    API -->|Cache| CDN[Amazon CloudFront]\n    CDN -->|Serve| User"
  }
}

