resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_security_group" "api_sg" {
  name        = "${local.name_prefix}-api-sg"
  description = "Security group for API Gateway"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${local.name_prefix}-lambda"
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn

  environment {
    variables = {
      DB_HOST = aws_rds_instance.my_rds.address
    }
  }

  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = "${local.name_prefix}-api"
  description = "API for the application"

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = local.common_tags
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri  = aws_lambda_function.my_lambda.invoke_arn
    http_method = "POST"
  }

  tags = local.common_tags
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "${local.name_prefix}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "my_task" {
  family                   = "${local.name_prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = var.ecs_cpu
  memory                   = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "my-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_dynamodb_table" "my_table" {
  name         = "${local.name_prefix}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = local.common_tags
}

resource "aws_rds_instance" "my_rds" {
  identifier              = "${local.name_prefix}-rds"
  engine                 = "postgres"
  instance_class         = var.db_instance_class
  allocated_storage       = var.db_allocated_storage
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  skip_final_snapshot    = true
  vpc_security_group_ids  = [aws_security_group.api_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.my_db_subnet_group.name

  tags = local.common_tags
}

resource "aws_db_subnet_group" "my_db_subnet_group" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${local.name_prefix}-queue"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "my_xray" {
  name = "${local.name_prefix}-xray-daemon"

  tags = local.common_tags
}

output "api_gateway_url" {
  value = "${aws_api_gateway_rest_api.my_api.execution_arn}/myresource"
}

output "rds_endpoint" {
  value = aws_rds_instance.my_rds.endpoint
}

variable "environment" {
