provider "aws" {
  region = var.aws_region
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "${var.project_name}-public-subnet"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "${var.project_name}-private-subnet"
  }
}

# Security Group for API Gateway
resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-api-gateway-sg"
  }
}

# Security Group for Lambda
resource "aws_security_group" "lambda" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-lambda-sg"
  }
}

# Security Group for ECS
resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-ecs-sg"
  }
}

# S3 Bucket
resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${var.aws_region}"
  acl    = "private"
  versioning {
    enabled = var.versioning == "Enabled"
  }
  tags = {
    Name = "${var.project_name}-data-bucket"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "main" {
  name         = "${var.project_name}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = {
    Name = "${var.project_name}-dynamodb-table"
  }
}

# RDS Instance
resource "aws_db_instance" "main" {
  identifier         = "${var.project_name}-rds"
  engine             = "mysql"
  instance_class     = "db.t3.micro"
  allocated_storage   = 20
  username           = "admin"
  password           = var.rds_password
  db_name            = "${var.project_name}_db"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.ecs.id]
  tags = {
    Name = "${var.project_name}-rds"
  }
}

# Kinesis Data Stream
resource "aws_kinesis_stream" "main" {
  name        = "${var.project_name}-kinesis-stream"
  shard_count = 1
  tags = {
    Name = "${var.project_name}-kinesis-stream"
  }
}

# SQS Queue
resource "aws_sqs_queue" "main" {
  name = "${var.project_name}-sqs-queue"
  tags = {
    Name = "${var.project_name}-sqs-queue"
  }
}

# Lambda Function
resource "aws_lambda_function" "main" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda.zip"
  tags = {
    Name = "${var.project_name}-lambda"
  }
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-lambda-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Effect = "Allow"
      Sid = ""
    }]
  })
}

# API Gateway
resource "aws_api_gateway_rest_api" "main" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"
  tags = {
    Name = "${var.project_name}-api"
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway_rest_api.main.execution_arn
    origin_id   = "api_gateway"
  }
  enabled             = true
  default_root_object = "index.html"
  tags = {
    Name = "${var.project_name}-cloudfront"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "main" {
  name = "${var.project_name}-log-group"
  retention_in_days = 14
  tags = {
    Name = "${var.project_name}-log-group"
  }
}

# X-Ray Group
resource "aws_xray_group" "main" {
  group_name = "${var.project_name}-xray-group"
  tags = {
    Name = "${var.project_name}-xray-group"
  }
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "rds_endpoint" {
  value = aws_db_instance.main.endpoint
}

output "kinesis_stream_name" {
  value = aws_kinesis_stream.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
