  "terraform": "provider "aws" {
  region  = var.region
  profile = "default"

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

variable "region" {
  description = "AWS region"
  default     = "ap-southeast-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type for backup scripts"
  default     = "t3.micro"
}

variable "db_engine" {
  description = "Database engine type"
  default     = "postgresql"
}

variable "db_instance_class" {
  description = "RDS instance class"
  default     = "db.t3.micro"
}

variable "s3_bucket_name" {
  description = "S3 bucket name for backup storage"
  default     = "my-backup-bucket"
}

variable "sns_topic_name" {
  description = "SNS topic name for backup notifications"
  default     = "backup-notifications"
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                 = aws_vpc.main.id
  cidr_block             = var.public_subnet_cidrs[count.index]
  availability_zone      = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                 = aws_vpc.main.id
  cidr_block             = var.private_subnet_cidrs[count.index]
  availability_zone      = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "ec2_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-security-group"
  }
}

resource "aws_instance" "backup_instance" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "backup-instance"
  }
}

resource "aws_db_instance" "db" {
  allocated_storage    = 20
  engine             = var.db_engine
  instance_class     = var.db_instance_class
  name               = "backupdb"
  username           = "admin"
  password           = "password"
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "backup-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "backup-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "backup-db-subnet-group"
  }
}

resource "aws_s3_bucket" "backup" {
  bucket = var.s3_bucket_name

  tags = {
    Name        = var.s3_bucket_name
    Description = "S3 bucket for backup storage"
  }
}

resource "aws_sns_topic" "backup_notifications" {
  name = var.sns_topic_name

  tags = {
    Name = var.sns_topic_name
  }
}

resource "aws_lambda_function" "backup_trigger" {
  function_name = "backup_trigger"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.backup.bucket
  s3_key        = "lambda/backup_trigger.zip"

  tags = {
    Name = "backup-trigger-lambda"
  }
}

resource "aws_cloudwatch_log_group" "backup_logs" {
  name = "/aws/lambda/backup_trigger"

  retention_in_days = 14
}

resource "aws_cloudtrail" "backup_audit" {
  name                          = "backup-audit"
  s3_bucket_name                = aws_s3_bucket.backup.bucket
  is_multi_region_trail         = true
  enable_logging                = true
  include_global_service_events  = true

  tags = {
    Name = "backup-audit"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "backup_instance_id" {
  value = aws_instance.backup_instance.id
}

output "db_instance_endpoint" {
  value = aws_db_instance.db.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.backup.bucket
}

output "sns_topic_arn" {
  value = aws_sns_topic.backup_notifications.arn
}",
