resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${count.index}"
  })
}

resource "aws_security_group" "api_sg" {
  name        = "${var.project_name}-api-sg"
  description = "Security group for API Gateway"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  environment {
    TABLE_NAME = aws_dynamodb_table.my_table.name
  }

  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = local.common_tags
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri  = aws_lambda_function.my_lambda.invoke_arn
  }

  tags = local.common_tags
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = local.common_tags
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "${var.project_name}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "my_task" {
  family                   = "${var.project_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "${var.project_name}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_dynamodb_table" "my_table" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = local.common_tags
}

resource "aws_s3_bucket" "my_bucket" {
  bucket = "${var.project_name}-bucket"
  acl    = "private"

  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.project_name}-queue"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "${var.project_name}-log-group"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "my_xray" {
  name = "${var.project_name}-xray-daemon"

  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.my_api.execution_arn
  description = "The endpoint of the API Gateway"
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
  description = "The name of the Lambda function"
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
  description = "The name of the DynamoDB table"
}

output "s3_bucket_name" {
  value = aws_s3_bucket.my_bucket.bucket
  description = "The name of the S3 bucket"
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
  description = "The URL of the SQS queue"
