resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-ecs-sg"
  tags = local.common_tags
}

resource "aws_security_group_rule" "allow_http" {
  type = "ingress"
  from_port = 80
  to_port = 80
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "allow_https" {
  type = "ingress"
  from_port = 443
  to_port = 443
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${local.environment}-my-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = aws_s3_bucket.lambda_code.bucket
  s3_key = aws_s3_bucket_object.lambda_code.key
  environment {
    variables = {
      DB_ENDPOINT = aws_rds_instance.my_db.endpoint
    }
  }
  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "my_api" {
  name = "${local.environment}-api"
  description = "API for ${local.environment}"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part = "myresource"
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  resource_id = aws_api_gateway_resource.my_resource.id
  http_method = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "my_integration" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  resource_id = aws_api_gateway_resource.my_resource.id
  http_method = aws_api_gateway_method.my_method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id = "myApiOrigin"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "myApiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    forwarded_values {
      query_string = true
    }
  }
  tags = local.common_tags
}

resource "aws_dynamodb_table" "my_table" {
  name = "${local.environment}-my-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = local.common_tags
}

resource "aws_rds_instance" "my_db" {
  identifier = "${local.environment}-db"
  instance_class = var.db_instance_class
  engine = "postgres"
  allocated_storage = var.db_allocated_storage
  db_subnet_group_name = aws_db_subnet_group.my_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.ecs.id]
  tags = local.common_tags
}

resource "aws_db_subnet_group" "my_db_subnet_group" {
  name = "${local.environment}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${local.environment}-my-queue"
  tags = local.common_tags
}

resource "aws_sns_topic" "my_topic" {
  name = "${local.environment}-my-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "my_xray" {
  name = "${local.environment}-xray-daemon"
  tags = local.common_tags
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.my_api.execution_arn
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}

output "rds_instance_endpoint" {
  value = aws_rds_instance.my_db.endpoint
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.my_topic.arn
