provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-allow-http"
  }
}

resource "aws_security_group" "allow_https" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-allow-https"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway.rest_api.api_endpoint
    origin_id   = "apiGateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGateway"

    forwarded_values {
      query_string = false
    }

    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
  }

  tags = {
    Name = "${var.project_name}-cdn"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = {
    Name = "${var.project_name}-api"
  }
}

resource "aws_ecs_cluster" "ecs" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "task" {
  family                   = "${var.project_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([
    {
      name      = "${var.project_name}-container"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])
}

resource "aws_lambda_function" "lambda" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

resource "aws_dynamodb_table" "dynamodb" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "${var.project_name}-dynamodb"
  }
}

resource "aws_db_instance" "rds" {
  identifier = "${var.project_name}-rds"
  engine     = "postgres"
  instance_class = var.rds_instance_class
  allocated_storage = 20
  username = var.rds_username
  password = var.rds_password
  db_name = var.rds_db_name
  skip_final_snapshot = true

  tags = {
    Name = "${var.project_name}-rds"
  }
}

resource "aws_sqs_queue" "sqs" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-sqs"
  }
}

resource "aws_kinesis_stream" "kinesis" {
  name        = "${var.project_name}-stream"
  shard_count = 1

  tags = {
    Name = "${var.project_name}-kinesis"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.project_name}-xray-daemon"

  tags = {
    Name = "${var.project_name}-xray"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
