}

# VPC for the application
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name        = "${var.project_name}-alb-sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-alb-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "main" {
  name               = "${var.project_name}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = false

  tags = {
    Name = "${var.project_name}-alb"
  }
}

# Target Group for ECS
resource "aws_lb_target_group" "ecs" {
  name     = "${var.project_name}-ecs-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.project_name}-ecs-tg"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "main" {
  family                   = "${var.project_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([
    {
      name      = "${var.project_name}-container"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])

  tags = {
    Name = "${var.project_name}-task"
  }
}

# ECS Service
resource "aws_ecs_service" "main" {
  name            = "${var.project_name}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.ecs_desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.alb_sg.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.ecs.arn
    container_name   = "${var.project_name}-container"
    container_port   = 80
  }

  tags = {
    Name = "${var.project_name}-service"
  }
}

# RDS Instance (Multi-AZ)
resource "aws_db_instance" "main" {
  identifier         = "${var.project_name}-rds"
  engine             = "postgres"
  instance_class     = var.rds_instance_class
  allocated_storage   = var.rds_allocated_storage
  multi_az           = true
  username           = var.db_username
  password           = var.db_password
  db_name            = var.db_name
  vpc_security_group_ids = [aws_security_group.alb_sg.id]
  skip_final_snapshot = true

  tags = {
    Name = "${var.project_name}-rds"
  }
}

# SQS Queue
resource "aws_sqs_queue" "main" {
  name = "${var.project_name}-sqs"

  tags = {
    Name = "${var.project_name}-sqs"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "main" {
  name = "${var.project_name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-log-group"
  }
}

# X-Ray Daemon IAM Role
resource "aws_iam_role" "xray" {
  name = "${var.project_name}-xray-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "xray.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${var.project_name}-xray-role"
  }
}

# Outputs
output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "ecs_cluster_name" {
  description = "ECS Cluster Name"
  value       = aws_ecs_cluster.main.name
}

output "rds_endpoint" {
  description = "RDS Endpoint"
  value       = aws_db_instance.main.endpoint
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.main.id
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch Log Group Name"
  value       = aws_cloudwatch_log_group.main.name
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS_with_Fargate[ECS with Fargate]
    Amazon_EC2_Auto_Scaling[EC2 Auto Scaling]
    Amazon_RDS[(RDS)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Application_Load_Balancer
    Application_Load_Balancer --> Amazon_ECS_with_Fargate
    Application_Load_Balancer --> Amazon_EC2_Auto_Scaling
    Amazon_ECS_with_Fargate --> Amazon_RDS
    Amazon_EC2_Auto_Scaling --> Amazon_RDS
    Amazon_ECS_with_Fargate --> Amazon_SQS
    Amazon_EC2_Auto_Scaling --> Amazon_SQS
    Amazon_ECS_with_Fargate -->|metrics| Amazon_CloudWatch
    Amazon_ECS_with_Fargate -->|metrics| AWS_X_Ray
    Amazon_EC2_Auto_Scaling -->|metrics| Amazon_CloudWatch
    Amazon_EC2_Auto_Scaling -->|metrics| AWS_X_Ray"
}

