provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "bucket_prefix" {
  description = "Bucket prefix for the S3"
  type        = string
  default     = "audiophile-e2e-pipeline-"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  type        = string
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "my_api_gateway"
}

variable "ecs_cluster_name" {
  description = "Name of the ECS Cluster"
  type        = string
  default     = "my_ecs_cluster"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  type        = string
  default     = "my_dynamodb_table"
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "my-s3-bucket"
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis Data Stream"
  type        = string
  default     = "my_kinesis_stream"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my_sns_topic"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main_vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public_subnet_${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private_subnet_${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda_sg"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.lambda_function_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${var.lambda_function_name}_role"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name = var.api_gateway_name

  tags = {
    Name = var.api_gateway_name
  }
}

resource "aws_api_gateway_resource" "my_api_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "my_api_resource"
  }
}

resource "aws_api_gateway_method" "my_api_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_api_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    integration_http_method = "POST"
    uri = aws_lambda_function.my_lambda.invoke_arn
  }

  tags = {
    Name = "my_api_method"
  }
}

resource "aws_ecs_cluster" "my_ecs_cluster" {
  name = var.ecs_cluster_name

  tags = {
    Name = var.ecs_cluster_name
  }
}

resource "aws_dynamodb_table" "my_dynamodb" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = "${var.bucket_prefix}${var.aws_region}-lambda-bucket"

  tags = {
    Name        = "lambda_bucket"
    Environment = var.aws_region
  }
}

resource "aws_kinesis_stream" "my_kinesis" {
  name        = var.kinesis_stream_name
  shard_count = 1

  tags = {
    Name = var.kinesis_stream_name
  }
}

resource "aws_sns_topic" "my_sns" {
  name = var.sns_topic_name

  tags = {
    Name = var.sns_topic_name
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "lambda_logs"
  }
}

resource "aws_cloudwatch_metric_alarm" "high_error_rate" {
  alarm_name          = "high_error_rate"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name        = "Errors"
  namespace          = "AWS/Lambda"
  period             = "60"
  statistic          = "Sum"
  threshold          = "1"
  alarm_description  = "This metric monitors lambda function errors"

  dimensions = {
    FunctionName = aws_lambda_function.my_lambda.function_name
  }

  tags = {
    Name = "high_error_rate_alarm"
  }
}

resource "aws_devops_guru_resource_collection" "my_collection" {
  resource_collection {
    cloud_watch_metrics {
      resource_collection_type = "CLOUD_WATCH_METRICS"
      resource_ids             = [aws_lambda_function.my_lambda.arn]
    }
  }

  tags = {
    Name = "devops_guru_collection"
  }
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function"
  value       = aws_lambda_function.my_lambda.arn
}

output "api_gateway_url" {
  description = "URL of the API Gateway"
  value       = "${aws_api_gateway_rest_api.my_api.execution_arn}/myresource"
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.my_dynamodb.name
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket for Lambda"
  value       = aws_s3_bucket.lambda_bucket.bucket
}

output "kinesis_stream_name" {
  description = "Name of the Kinesis Data Stream"
  value       = aws_kinesis_stream.my_kinesis.name
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic"
  value       = aws_sns_topic.my_sns.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_S3[(S3)]
    Amazon_Kinesis_Data_Streams[Kinesis Data Streams]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    Amazon_DevOps_Guru[DevOps Guru]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_S3
    Amazon_ECS --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_S3
    AWS_Lambda --> Amazon_Kinesis_Data_Streams
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS --> Amazon_Kinesis_Data_Streams
    Amazon_ECS --> Amazon_SNS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| Amazon_DevOps_Guru
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| Amazon_DevOps_Guru"
}

{
  "scenario_summary": "The client needs an AWS architecture for a podcast platform that can handle 2,000 daily active users.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon API Gateway",
        "Application Load Balancer"
      ],
