    {
      "decision": "Amazon RDS vs DynamoDB",
      "chose": "Amazon RDS",
      "reason": "RDS provides relational database capabilities with support for complex queries and transactions, which is essential for the existing application workload.",
      "when_to_switch": "If the application evolves to require more scalable, NoSQL capabilities or if the workload becomes highly read-intensive, DynamoDB could be a better fit."
    },
    {
      "decision": "Application Load Balancer vs Network Load Balancer",
      "chose": "Application Load Balancer",
      "reason": "ALB supports advanced routing features and can handle HTTP/HTTPS traffic, making it ideal for web applications that require path-based routing and SSL termination.",
      "when_to_switch": "If the application requires ultra-low latency TCP traffic handling or needs to support millions of requests per second, a Network Load Balancer would be more suitable."
    },
    {
      "decision": "Amazon SQS vs Amazon SNS",
      "chose": "Amazon SQS",
