provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "${var.name}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.name}-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.region}b"

  tags = {
    Name = "${var.name}-private-subnet"
  }
}

resource "aws_security_group" "elb" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-elb-sg"
  }
}

resource "aws_security_group" "ec2" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-ec2-sg"
  }
}

resource "aws_elastic_load_balancer" "main" {
  name               = "${var.name}-elb"
  availability_zones = [aws_subnet.public.availability_zone]

  security_groups = [aws_security_group.elb.id]

  tags = {
    Name = "${var.name}-elb"
  }
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private.id
  security_groups = [aws_security_group.ec2.id]

  tags = {
    Name = "${var.name}-app-instance"
  }
}

resource "aws_rds_cluster" "main" {
  engine         = "mysql"
  engine_version = "8.0"
  cluster_identifier = "${var.name}-rds-cluster"
  master_username = var.db_username
  master_password = var.db_password
  skip_final_snapshot = true
  storage_encrypted = true

  availability_zones = ["${var.region}a", "${var.region}b"]
  db_subnet_group_name = aws_db_subnet_group.main.name

  tags = {
    Name = "${var.name}-rds-cluster"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.name}-db-subnet-group"
  subnet_ids = [aws_subnet.private.id]

  tags = {
    Name = "${var.name}-db-subnet-group"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.name}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "${var.name}-dynamodb-table"
  }
}

resource "aws_sqs_queue" "main" {
  name = "${var.name}-sqs-queue"

  tags = {
    Name = "${var.name}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "${var.name}-log-group"

  tags = {
    Name = "${var.name}-log-group"
  }
}

resource "aws_xray_daemon" "main" {
  name = "${var.name}-xray-daemon"

  tags = {
    Name = "${var.name}-xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_id" {
  value = aws_subnet.public.id
}

output "private_subnet_id" {
  value = aws_subnet.private.id
}

output "elb_dns_name" {
  value = aws_elastic_load_balancer.main.dns_name
}

variable "region" {
  description = "The AWS region to deploy resources"
  type        = string
}

variable "name" {
  description = "The name prefix for all resources"
