  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.49.0"
    }
  }
  required_version = "~> 1.9.3"

  backend "s3" {
    bucket         = var.s3_bucket
    region         = var.region
    key            = "terraform.tfstate"
    dynamodb_table = var.dynamodb_table
    encrypt        = true
  }
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "p4d.24xlarge"
}

variable "s3_bucket" {
  description = "S3 bucket for Terraform state"
}

variable "dynamodb_table" {
  description = "DynamoDB table for state locking"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow EC2 instances to communicate"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow SSH access"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound traffic"
  }

  tags = {
    Name = "ec2-security-group"
  }
}

resource "aws_instance" "p4d_instance" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "p4d-instance"
  }
}

resource "aws_s3_bucket" "model_bucket" {
  bucket = "sagemaker-models-${var.region}-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "SageMaker Model Bucket"
  }
}

resource "aws_efs_file_system" "efs" {
  creation_token = "efs-${random_string.efs_suffix.result}"

  tags = {
    Name = "EFS File System"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = "/aws/sagemaker/logs"
  retention_in_days = 14

  tags = {
    Name = "SageMaker Log Group"
  }
}

resource "aws_cloudtrail" "cloud_trail" {
  name                          = "cloudtrail-${var.region}"
  s3_bucket_name               = aws_s3_bucket.model_bucket.bucket
  is_multi_region_trail        = true
  enable_log_file_validation    = true

  tags = {
    Name = "CloudTrail"
  }
}

resource "aws_directconnect_connection" "dx_connection" {
  name              = "DX-Connection"
  bandwidth         = "1Gbps"
  connection_type   = "dedicated"
  location          = var.dx_location
  vlan              = var.dx_vlan

  tags = {
    Name = "Direct Connect Connection"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "random_string" "efs_suffix" {
  length  = 8
  special = false
}

data "aws_ami" "latest" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

data "aws_availability_zones" "available" {}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnets" {
  value = aws_subnet.public[*].id
}

output "private_subnets" {
  value = aws_subnet.private[*].id
}

output "s3_bucket" {
  value = aws_s3_bucket.model_bucket.bucket
}

output "efs_id" {
  value = aws_efs_file_system.efs.id
}

output "cloudtrail_id" {
  value = aws_cloudtrail.cloud_trail.id
