variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the project."
  type        = string
  default     = "my_project"
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t3.micro"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.project_name}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.project_name}-public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Groups
resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-lambda-sg"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-api-gateway-sg"
  }
}

# S3 Bucket
resource "aws_s3_bucket" "bucket" {
  bucket = "${var.bucket_prefix}${var.project_name}"
  acl    = "private"

  tags = {
    Name = "${var.project_name}-bucket"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "table" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.project_name}-dynamodb-table"
  }
}

# RDS Instance
resource "aws_db_instance" "default" {
  identifier         = "${var.project_name}-db"
  engine             = "mysql"
  instance_class     = "db.t3.micro"
  allocated_storage   = 20
  storage_type       = "gp2"
  username           = "admin"
  password           = var.rds_password
  db_name            = "${var.project_name}_db"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "${var.project_name}-rds"
  }
}

# Lambda Function
resource "aws_lambda_function" "function" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Effect = "Allow"
      Sid    = ""
    }]
  })

  tags = {
    Name = "${var.project_name}-lambda-exec-role"
  }
}

# API Gateway
resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = {
    Name = "${var.project_name}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = {
    Name = "${var.project_name}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.project_name}-api-method"
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiGateway"

    custom_origin_config {
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  is_ipv6_enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGateway"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "${var.project_name}-cloudfront"
  }
}

# Kinesis Data Stream
resource "aws_kinesis_stream" "stream" {
  name        = "${var.project_name}-stream"
  shard_count = 1

  tags = {
    Name = "${var.project_name}-kinesis-stream"
  }
}

# SQS Queue
resource "aws_sqs_queue" "queue" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-sqs-queue"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.function.function_name}"

  tags = {
    Name = "${var.project_name}-cloudwatch-log-group"
  }
}

# X-Ray
resource "aws_xray_group" "group" {
  filter_expression = "service(\"${var.project_name}\")"
  group_name        = "${var.project_name}-xray-group"

  tags = {
    Name = "${var.project_name}-xray-group"
  }
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_S3[(S3)]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_RDS[(RDS)]
    Amazon_Kinesis_Data_Streams[Kinesis Data Streams]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Lambda --> Amazon_S3
