provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "p3.2xlarge"
}

variable "sagemaker_instance_type" {
  description = "SageMaker instance type"
  default     = "ml.p3.2xlarge"
}

variable "db_instance_class" {
  description = "RDS instance class"
  default     = "db.t3.medium"
}

variable "bucket_name" {
  description = "S3 bucket name for data storage"
  default     = "my-data-storage-bucket"
}

variable "db_name" {
  description = "RDS database name"
  default     = "metadata"
}

variable "db_username" {
  description = "RDS database username"
  default     = "admin"
}

variable "db_password" {
  description = "RDS database password"
  default     = "password123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow SSH and HTTP access to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

resource "aws_instance" "p3_instance" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "p3-instance"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = var.bucket_name

  tags = {
    Name        = var.bucket_name
    Environment = "Production"
  }
}

resource "aws_db_instance" "metadata_db" {
  allocated_storage    = 20
  engine             = "postgres"
  engine_version     = "13.3"
  instance_class     = var.db_instance_class
  name               = var.db_name
  username           = var.db_username
  password           = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]
  skip_final_snapshot = true

  tags = {
    Name = "metadata-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_sqs_queue" "job_queue" {
  name = "job-queue"

  tags = {
    Name = "job-queue"
  }
}

resource "aws_sns_topic" "notifications" {
  name = "notifications"

  tags = {
    Name = "notifications"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "application-log-group"

  retention_in_days = 14

  tags = {
    Name = "application-log-group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "ec2_instance_id" {
  description = "EC2 Instance ID"
  value       = aws_instance.p3_instance.id
}

output "s3_bucket_name" {
  description = "S3 Bucket Name"
  value       = aws_s3_bucket.data_bucket.bucket
}

output "rds_instance_endpoint" {
  description = "RDS Instance Endpoint"
  value       = aws_db_instance.metadata_db.endpoint
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.job_queue.id
}

output "sns_topic_arn" {
  description = "SNS Topic ARN"
  value       = aws_sns_topic.notifications.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_VPC[VPC]
    AWS_Transit_Gateway[Transit Gateway]
    Amazon_EC2_with_P3_P4_instances[EC2 with P3/P4 instances]
    Amazon_SageMaker[SageMaker]
    Amazon_S3_for_data_storage[(S3 for data storage)]
    Amazon_RDS_for_metadata_storage[(RDS for metadata storage)]
    Amazon_SQS_for_job_queuing[SQS for job queuing]
    Amazon_SNS_for_notifications[SNS for notifications]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_VPC
    Amazon_CloudFront --> AWS_Transit_Gateway
    Amazon_VPC --> Amazon_EC2_with_P3_P4_instances
    Amazon_VPC --> Amazon_SageMaker
    AWS_Transit_Gateway --> Amazon_EC2_with_P3_P4_instances
    AWS_Transit_Gateway --> Amazon_SageMaker
    Amazon_EC2_with_P3_P4_instances --> Amazon_S3_for_data_storage
    Amazon_EC2_with_P3_P4_instances --> Amazon_RDS_for_metadata_storage
    Amazon_SageMaker --> Amazon_S3_for_data_storage
    Amazon_SageMaker --> Amazon_RDS_for_metadata_storage
    Amazon_EC2_with_P3_P4_instances --> Amazon_SQS_for_job_queuing
    Amazon_EC2_with_P3_P4_instances --> Amazon_SNS_for_notifications
    Amazon_SageMaker --> Amazon_SQS_for_job_queuing
    Amazon_SageMaker --> Amazon_SNS_for_notifications
    Amazon_EC2_with_P3_P4_instances -->|metrics| Amazon_CloudWatch
    Amazon_EC2_with_P3_P4_instances -->|metrics| AWS_X_Ray
    Amazon_SageMaker -->|metrics| Amazon_CloudWatch
    Amazon_SageMaker -->|metrics| AWS_X_Ray"
}

