  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"api_handler\" {\n  function_name = \"ride_sharing_api\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"RideSharingAPI\"\n  description = \"API for ride sharing platform\"\n}\n\nresource \"aws_dynamodb_table\" \"rides\" {\n  name         = \"Rides\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"ride_id\"\n    type = \"S\"\n  }\n  hash_key = \"ride_id\"\n}\n\nresource \"aws_sqs_queue\" \"ride_queue\" {\n  name = \"ride_requests\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"api_logs\" {\n  name = \"/aws/lambda/ride_sharing_api\"\n}",
