provider "aws" {
  region = var.region
}

default_tags {
  tags = {
    ManagedBy = "terraform"
    Purpose    = "production"
  }
}

# VPC Creation
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "${var.name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  count                   = var.public_subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.name}-public-subnet-${count.index}"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  count      = var.private_subnet_count
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.name}-private-subnet-${count.index}"
  }
}

# Security Group for API Gateway
resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-api-gateway-sg"
  }
}

# Security Group for ECS
resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.api_gateway.id]
  }

  tags = {
    Name = "${var.name}-ecs-sg"
  }
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  tags = {
    Name = "${var.name}-rds-sg"
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway.rest_api.invoke_url
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "${var.name}-cloudfront"
  }
}

# API Gateway
resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.name}-api"
  description = "API for ${var.name}"

  tags = {
    Name = "${var.name}-api"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "cluster" {
  name = "${var.name}-ecs-cluster"

  tags = {
    Name = "${var.name}-ecs-cluster"
  }
}

# Fargate Task Definition
resource "aws_ecs_task_definition" "task" {
  family                   = "${var.name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "${var.name}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${var.name}-task"
  }
}

# RDS Instance
resource "aws_db_instance" "db" {
  identifier         = "${var.name}-db"
  engine             = "mysql"
  instance_class     = var.rds_instance_class
  allocated_storage   = var.rds_allocated_storage
  db_name            = var.rds_db_name
  username           = var.rds_username
  password           = var.rds_password
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot = true

  tags = {
    Name = "${var.name}-db"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "table" {
  name           = "${var.name}-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.name}-dynamodb-table"
  }
}

# SQS Queue
resource "aws_sqs_queue" "queue" {
  name = "${var.name}-sqs-queue"

  tags = {
    Name = "${var.name}-sqs-queue"
  }
}

# SNS Topic
resource "aws_sns_topic" "topic" {
  name = "${var.name}-sns-topic"

  tags = {
    Name = "${var.name}-sns-topic"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "log_group" {
  name = "${var.name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.name}-log-group"
  }
}

# X-Ray Group
resource "aws_xray_group" "xray_group" {
  filter_expression = "service(\"${var.name}\")"
  group_name        = "${var.name}-xray-group"

  tags = {
