provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Owner = "Your Name"
      Environment = "production"
    }
  }
}

# VPC for the application
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.region}a"
  map_public_ip_on_launch = true
}

# Private Subnet 1
resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.region}a"
}

# Private Subnet 2
resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = "${var.region}b"
}

# Security Group for EKS
resource "aws_security_group" "eks" {
  vpc_id = aws_vpc.main.id
  name   = "eks-security-group"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# EKS Cluster
resource "aws_eks_cluster" "auto" {
  name     = "eks-auto-cluster"
  role_arn = aws_iam_role.cluster.arn
  version  = "1.31"

  compute_config {
    enabled     = true
    node_pools  = ["general-purpose", "system"]
    node_role_arn = aws_iam_role.node.arn
  }

  kubernetes_network_config {
    elastic_load_balancing {
      enabled = true
    }
  }

  vpc_config {
    subnet_ids = [aws_subnet.private_1.id, aws_subnet.private_2.id]
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  storage_config {
    block_storage {
      enabled = true
    }
  }
}

# IAM Role for EKS Cluster
resource "aws_iam_role" "cluster" {
  name = "eks-auto-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

# Attach policies to EKS Cluster Role
resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

# IAM Role for EKS Nodes
resource "aws_iam_role" "node" {
  name = "eks-auto-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

# Attach policies to EKS Node Role
resource "aws_iam_role_policy_attachment" "node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_registry_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

# Amazon RDS Instance
resource "aws_db_instance" "default" {
  identifier = "mydbinstance"
  engine     = "mysql"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  storage_type = "gp2"
  username = var.db_username
  password = var.db_password
  db_name = var.db_name
  vpc_security_group_ids = [aws_security_group.eks.id]
  db_subnet_group_name = aws_db_subnet_group.default.name
  skip_final_snapshot = true
}

resource "aws_db_subnet_group" "default" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.private_1.id, aws_subnet.private_2.id]
}

# Amazon DynamoDB Table
resource "aws_dynamodb_table" "example" {
  name         = "example-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
}

# Amazon SQS Queue
resource "aws_sqs_queue" "example" {
  name = "example-queue"
}

# Amazon SNS Topic
resource "aws_sns_topic" "example" {
  name = "example-topic"
}

# Amazon CloudWatch Log Group
resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/eks/example"
  retention_in_days = 14
}

# AWS X-Ray Daemon
resource "aws_ecs_task_definition" "xray" {
  family                   = "xray"
  container_definitions    = jsonencode([{
    name      = "xray"
    image     = "amazon/aws-xray-daemon"
    essential = true
    memory    = 512
    cpu       = 256
    portMappings = [{
      containerPort = 2000
      hostPort      = 2000
      protocol      = "udp"
    }]
  }])
}

# Outputs
output "eks_cluster_name" {
  value = aws_eks_cluster.auto.name
}

output "rds_endpoint" {
  value = aws_db_instance.default.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.example.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.example.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.example.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_Elastic_Load_Balancer[Elastic Load Balancer]
    Amazon_Route_53[Route 53]
    Amazon_EKS[EKS]
    ArgoCD[ArgoCD]
    Amazon_RDS[(RDS)]
    Amazon_DynamoDB[(DynamoDB)]
