provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "ecs-cluster"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "api-gateway"
}

variable "load_balancer_name" {
  description = "Name of the Application Load Balancer"
  type        = string
  default     = "app-load-balancer"
}

variable "redis_cache_name" {
  description = "Name of the ElastiCache Redis cluster"
  type        = string
  default     = "redis-cache"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue"
  type        = string
  default     = "sqs-queue"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.aws_region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}b"

  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "ecs_sg" {
  name        = "ecs_security_group"
  description = "Allow traffic for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs_security_group"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_security_group"
  description = "Allow traffic for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.private.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "mydatabase"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = var.ecs_cluster_name

  tags = {
    Name = var.ecs_cluster_name
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = var.load_balancer_name
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.ecs_sg.id]
  subnets            = [aws_subnet.public.id]

  enable_deletion_protection = false

  tags = {
    Name = var.load_balancer_name
  }
}

resource "aws_api_gateway_rest_api" "api_gateway" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"

  tags = {
    Name = var.api_gateway_name
  }
}

resource "aws_elasticache_cluster" "redis_cache" {
  cluster_id           = var.redis_cache_name
  engine               = "redis"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.redis_subnet_group.name

  tags = {
    Name = var.redis_cache_name
  }
}

resource "aws_elasticache_subnet_group" "redis_subnet_group" {
  name       = "${var.redis_cache_name}-subnet-group"
  subnet_ids = [aws_subnet.private.id]

  tags = {
    Name = "${var.redis_cache_name}-subnet-group"
  }
}

resource "aws_sqs_queue" "sqs_queue" {
  name = var.sqs_queue_name

  tags = {
    Name = var.sqs_queue_name
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name              = "/ecs/${var.ecs_cluster_name}"
  retention_in_days = 7

  tags = {
    Name = "ECS Log Group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "X-Ray Daemon"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "load_balancer_dns" {
  value = aws_lb.application_load_balancer.dns_name
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.ecs_cluster.name
}

output "api_gateway_id" {
  value = aws_api_gateway_rest_api.api_gateway.id
}

output "redis_endpoint" {
  value = aws_elasticache_cluster.redis_cache.configuration_endpoint
}

output "sqs_queue_url" {
  value = aws_sqs_queue.sqs_queue.id
