    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_security_group\" \"allow_https\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 443\n    to_port     = 443\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_ecs_cluster\" \"main\" {}\n\nresource \"aws_rds_instance\" \"main\" {\n  allocated_storage    = 20\n  engine             = \"mysql\"\n  instance_class     = \"db.t3.medium\"\n  name               = \"mydatabase\"\n  username           = \"user\"\n  password           = \"password\"\n  db_subnet_group_name = aws_db_subnet_group.main.name\n}\n\nresource \"aws_db_subnet_group\" \"main\" {\n  name       = \"mydb-subnet-group\"\n  subnet_ids = [aws_subnet.private.id]\n}\n\nresource \"aws_lb\" \"main\" {\n  name               = \"my-load-balancer\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id, aws_security_group.allow_https.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"my_function\" {\n  function_name = \"my_function\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n  handler = \"index.handler\"\n  code = {\n    s3_bucket = \"mybucket\"\n    s3_key    = \"myfunction.zip\"\n  }\n}\n",
    "diagram": "graph TD\n    User([User])\n    User -->|Requests| ALB[Application Load Balancer]\n    ALB -->|Routes| ECS[Amazon ECS]\n    ALB -->|Routes| Lambda[AWS Lambda]\n    ECS -->|Reads/Writes| RDS[Amazon RDS]\n    ECS -->|Queries| DynamoDB[Amazon DynamoDB]\n    ECS -->|Sends| SQS[Amazon SQS]\n    ECS -->|Notifies| SNS[Amazon SNS]\n    ECS -->|Monitors| CW[Amazon CloudWatch]\n    Lambda -->|Monitors| CW\n"
  }
}

