    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS_with_Fargate[ECS with Fargate]
