variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_class" {
  description = "RDS instance class"
  default     = "db.t3.micro"
}

variable "db_password" {
  description = "RDS master password"
  type        = string
  sensitive   = true
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_sg" {
  name        = "api-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to API Gateway"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "api-sg"
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access for Lambda functions"

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS from private subnets"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [for subnet in aws_subnet.private : subnet.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = var.db_instance_class
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "mydatabase"
  username            = "awsadmin"
  password            = var.db_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds-instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  environment {
    DB_PASSWORD = var.db_password
  }

  tags = {
    Name = "my-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "lambda-execution-role"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "my_api"
  description = "My API Gateway"

  tags = {
    Name = "my-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "my-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "my-method"
  }
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.my_lambda.invoke_arn

  tags = {
    Name = "my-integration"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = {
    Name = "my-cdn"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "my-dynamodb-table"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"

  tags = {
    Name = "my-sqs-queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my_topic"

  tags = {
    Name = "my-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/my_lambda_function"

  retention_in_days = 14

  tags = {
    Name = "my-log-group"
  }
}

resource "aws_config_configuration_recorder" "recorder" {
  name     = "my_config_recorder"
  role_arn = aws_iam_role.config_role.arn
  recording_group {
    all_supported = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "channel" {
  name           = "my_delivery_channel"
  s3_bucket_name = aws_s3_bucket.config_bucket.bucket
}

resource "aws_s3_bucket" "config_bucket" {
  bucket = "my-config-bucket"

  tags = {
    Name = "my-config-bucket"
  }
}

resource "aws_auditmanager_assessment" "my_assessment" {
  name = "my_assessment"
  framework_id = "my_framework_id"
  assessment_reports {
    report_type = "PDF"
  }
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}",
