{
  "scenario_summary": "The client needs a Kafka-based event bus on AWS MSK to decouple microservices.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon VPC, AWS Transit Gateway"
      ],
