  "terraform": "variable "aws_region" {
  description = "Region for the AWS services to run in."
  type = string
  default = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_class" {
  description = "RDS instance class."
  type = string
  default = "db.t3.micro"
}

variable "db_name" {
  description = "Name of the database."
  type = string
  default = "mydb"
}

variable "db_username" {
  description = "Database master username."
  type = string
  default = "admin"
}

variable "db_password" {
  description = "Password for the database."
  type = string
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type = string
  default = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  type = string
  default = "my_api_gateway"
}

locals {
  common_tags = {
    Environment = "production"
    Project     = "my_project"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags       = local.common_tags
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags = local.common_tags
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_security_group" "allow_lambda" {
  vpc_id = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_rds_instance" "default" {
  identifier = "${local.common_tags["Project"]}-rds"
  engine = "postgres"
  instance_class = var.db_instance_class
  allocated_storage = 20
  db_name = var.db_name
  username = var.db_username
  password = var.db_password
  vpc_security_group_ids = [aws_security_group.allow_http.id]
  db_subnet_group_name = aws_db_subnet_group.default.name
  skip_final_snapshot = true
  tags = local.common_tags
}

resource "aws_db_subnet_group" "default" {
  name       = "${local.common_tags["Project"]}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags       = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.allow_lambda.id]
  }
  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "my_integration" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  resource_id = aws_api_gateway_resource.my_resource.id
  http_method = aws_api_gateway_method.my_method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${local.common_tags["Project"]}-queue"
  tags = local.common_tags
}

resource "aws_sns_topic" "my_topic" {
  name = "${local.common_tags["Project"]}-topic"
  tags = local.common_tags
}

resource "aws_kinesis_stream" "my_stream" {
  name        = "${local.common_tags["Project"]}-stream"
  shard_count = 1
  tags        = local.common_tags
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id   = "api_gateway"
  }
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "high_cpu" {
  alarm_name          = "${local.common_tags["Project"]}-high-cpu"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name        = "CPUUtilization"
  namespace          = "AWS/EC2"
  period             = "60"
  statistic          = "Average"
  threshold          = "80"
  alarm_description  = "This metric monitors ec2 high cpu utilization"
  dimensions = {
    InstanceId = aws_rds_instance.default.id
  }
  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.common_tags["Project"]}-lambda-exec"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_rds_instance.default.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.my_api.execution_invoke_url
}",
