    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"podcast_api\" {\n  name = \"PodcastAPI\"\n}\n\nresource \"aws_lambda_function\" \"podcast_function\" {\n  function_name = \"PodcastFunction\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_ecs_cluster\" \"podcast_cluster\" {\n  name = \"PodcastCluster\"\n}\n\nresource \"aws_dynamodb_table\" \"podcast_table\" {\n  name         = \"PodcastTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_rds_cluster\" \"podcast_db\" {\n  engine = \"aurora\"\n  master_username = \"admin\"\n  master_password = \"password\"\n  db_cluster_identifier = \"podcast-db\"\n}\n\nresource \"aws_sqs_queue\" \"podcast_queue\" {\n  name = \"PodcastQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"podcast_logs\" {\n  name = \"/aws/lambda/podcast_function\"\n}",
