    Amazon_API_Gateway --> Amazon_ECS
    Amazon_API_Gateway --> AWS_Lambda
    Elastic_Load_Balancer --> Amazon_ECS
    Elastic_Load_Balancer --> AWS_Lambda
    Amazon_ECS --> Amazon_Aurora_with_Global_Database
    AWS_Lambda --> Amazon_Aurora_with_Global_Database
    Amazon_ECS --> Amazon_SNS
