provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Owner       = "YourName"
      Environment = var.environment
    }
  }
}

variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment (e.g., dev, staging, prod)"
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_security_group" "public" {
  vpc_id = aws_vpc.main.id
  name = "public-sg"
  description = "Allow HTTP and HTTPS traffic"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Public Security Group"
  }
}

resource "aws_security_group" "private" {
  vpc_id = aws_vpc.main.id
  name = "private-sg"
  description = "Allow internal traffic"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    security_groups = [aws_security_group.public.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Private Security Group"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "MyAPI"
  description = "API for my application"
}

resource "aws_lambda_function" "lambda" {
  function_name = "MyLambdaFunction"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "My Lambda Function"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_exec.name
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "APIGatewayOrigin"

    custom_origin_config {
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "APIGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "CloudFront Distribution"
  }
}

resource "aws_elastic_load_balancer" "elb" {
  name               = "my-elb"
  availability_zones = data.aws_availability_zones.available.names

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "Elastic Load Balancer"
  }
}

resource "aws_ec2_instance" "web" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private[0].id
  security_groups = [aws_security_group.private.id]

  tags = {
    Name = "Web Server"
  }
}

resource "aws_ecs_cluster" "ecs" {
  name = "my-ecs-cluster"

  tags = {
    Name = "ECS Cluster"
  }
}

resource "aws_rds_cluster" "db" {
  cluster_identifier      = "my-rds-cluster"
  engine                 = "aurora"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true

  tags = {
    Name = "RDS Cluster"
  }
}

resource "aws_elasticache_cluster" "cache" {
  cluster_id = "my-elasticache-cluster"
  engine     = "redis"
  node_type  = "cache.t2.micro"
  num_cache_nodes = 1

  tags = {
    Name = "ElastiCache Cluster"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "my-sqs-queue"

  tags = {
    Name = "SQS Queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/my_lambda_function"

  retention_in_days = 14

  tags = {
    Name = "CloudWatch Log Group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "xray-daemon"

  tags = {
    Name = "X-Ray Daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.cdn.id
}",
