resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type             = "AWS_PROXY"
    integration_http_method = "POST"
    uri              = aws_lambda_function.my_lambda.invoke_arn
  }

  tags = {
    Name = "my_api_method"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "my_dynamodb_table"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"

  tags = {
    Name = "my_sqs_queue"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/my_lambda_function"

  retention_in_days = 14

  tags = {
    Name = "my_log_group"
  }
}

resource "aws_eventbridge_rule" "my_rule" {
  name        = "my_event_rule"
  event_pattern = jsonencode({
    source = ["aws.sqs"]
  })

  tags = {
    Name = "my_event_rule"
  }
}

resource "aws_batch_compute_environment" "my_batch_env" {
  compute_environment_name = "my_batch_env"
  type                     = "MANAGED"

  compute_resources {
    type              = "EC2"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_types   = ["optimal"]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.lambda_sg.id]
  }

  service_role = aws_iam_role.batch_service_role.arn

  tags = {
    Name = "my_batch_env"
  }
}

resource "aws_ecs_cluster" "my_ecs_cluster" {
  name = "my_ecs_cluster"

  tags = {
    Name = "my_ecs_cluster"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "lambda_function_arn" {
  value = aws_lambda_function.my_lambda.arn
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    AWS_Batch[Batch]
    Amazon_ECS[ECS]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SQS[SQS]
    Amazon_EventBridge[EventBridge]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> AWS_Batch
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Batch --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_SQS
    AWS_Lambda --> Amazon_EventBridge
    AWS_Batch --> Amazon_SQS
