}

{
  "scenario_summary": "The client needs a global DNS failover architecture using Route 53 health checks.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon Route 53",
        "AWS Global Accelerator"
      ],
      "compute": [
        "Amazon ECS",
        "Amazon EC2"
      ],
      "database": [
        "Amazon RDS"
      ],
      "messaging": [],
      "monitoring": [
        "Amazon CloudWatch"
      ]
    },
    "reasoning": "Amazon Route 53 is chosen for its global DNS capabilities and health check features, which are essential for implementing a reliable DNS failover architecture. By leveraging Route 53's health checks, the system can automatically reroute traffic to healthy endpoints in case of failures. AWS Global Accelerator enhances this setup by providing static IP addresses that act as a fixed entry point to the application, improving performance and reliability across multiple AWS Regions. This combination ensures that the application remains accessible even during regional outages, meeting the client's need for global failover capabilities.

For compute resources, Amazon ECS is selected to manage containerized applications, allowing for easy scaling and management of workloads. Amazon EC2 instances can be used to run ECS tasks, ensuring that there is sufficient capacity to handle failover scenarios. The use of Amazon RDS for database services ensures that the database layer is also resilient, with Multi-AZ deployments providing automatic failover capabilities. This architecture is designed to be cost-effective while ensuring high availability and reliability, as it utilizes managed services that reduce operational overhead and complexity."
  },
  "trade_offs": [
    {
      "decision": "Amazon ECS vs Amazon EC2",
      "chose": "Amazon ECS",
      "reason": "ECS simplifies the deployment and management of containerized applications, providing built-in scaling and load balancing features, which are essential for a failover architecture.",
      "when_to_switch": "If the application requires more granular control over individual instances or needs to run legacy applications that cannot be containerized, then EC2 might be a better fit."
    },
    {
      "decision": "Amazon RDS vs self-managed database on EC2",
      "chose": "Amazon RDS",
      "reason": "RDS provides automated backups, patching, and Multi-AZ deployments for high availability, which are crucial for maintaining database reliability during failover events.",
      "when_to_switch": "If the application has very specific database requirements that RDS cannot meet, such as custom configurations or specific database engines not supported by RDS, then a self-managed database on EC2 may be necessary."
    },
    {
      "decision": "AWS Global Accelerator vs direct Route 53 routing",
      "chose": "AWS Global Accelerator",
      "reason": "Global Accelerator provides static IP addresses and optimizes the path to the application, improving performance and reducing latency for global users, which is beneficial for a global failover architecture.",
      "when_to_switch": "If the application does not require static IPs or the additional performance benefits of Global Accelerator, direct Route 53 routing could be sufficient and more cost-effective."
    },
    {
      "decision": "Amazon CloudFront vs no CDN",
      "chose": "Amazon CloudFront",
      "reason": "CloudFront enhances the global reach and performance of the application by caching content at edge locations, reducing latency for users and improving overall user experience during failover scenarios.",
      "when_to_switch": "If the application is primarily dynamic and does not benefit from caching, or if cost is a significant concern, then using CloudFront may not be necessary."
    }
  ],
  "cost": {
    "monthly_breakdown": [
      {
        "service": "Amazon CloudFront",
        "monthly_usd": 10.0,
        "unit": "per 1TB transfer"
      },
      {
        "service": "Amazon ECS",
        "monthly_usd": 35.42,
        "unit": "task"
      },
      {
        "service": "Amazon RDS",
        "monthly_usd": 115.2,
        "unit": "instance (single-AZ)"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 10.0,
        "unit": "estimated"
      },
      {
        "service": "Data Transfer (egress)",
        "monthly_usd": 9.0,
        "unit": "per 100GB egress"
      }
    ],
    "total_monthly_usd": 179.62,
    "spike_estimate_usd": 242.49,
    "optimization": "Switch to 1-year Reserved Instances for EC2/RDS/ElastiCache to save 30-40% on compute costs. Use S3 Intelligent-Tiering for infrequently accessed data."
  },
  "terraform": "terraform {
  required_version = ">= 1.15.4"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }
}

variable "aws_region" {
  description = "AWS region to launch resources."
  default     = "ap-south-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type."
  default     = "t3.micro"
}

variable "db_instance_class" {
  description = "RDS instance class."
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "Database name."
  default     = "mydb"
}

variable "db_username" {
  description = "Database username."
  default     = "admin"
}

variable "db_password" {
  description = "Database password."
  default     = "password123"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "main-ecs-cluster"

  tags = {
    Name = "main-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = "app-task"
  network_mode            = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "app"
    image     = "nginx:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])
}

resource "aws_ecs_service" "app" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }
}

resource "aws_db_instance" "main" {
  identifier         = "mydb-instance"
  engine             = "mysql"
  instance_class     = var.db_instance_class
  allocated_storage   = 20
  db_name            = var.db_name
  username           = var.db_username
  password           = var.db_password
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.ecs_sg.id]

  tags = {
    Name = "main-db-instance"
  }
}

resource "aws_cloudwatch_log_group" "ecs" {
  name = "/ecs/app"

  retention_in_days = 7
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_ecs_service.app.load_balancer_dns_name
    origin_id   = "ecs-app"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "ecs-app"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "PATCH", "POST", "DELETE"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "cloudfront-distribution"
  }
}

resource "aws_route53_zone" "main" {
  name = "example.com"

  tags = {
    Name = "example.com"
  }
}

resource "aws_global_accelerator" "main" {
  name = "my-global-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  listener {
    port_range {
      from_port = 80
      to_port   = 80
    }

    protocol = "TCP"
  }

  tags = {
    Name = "global-accelerator"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "db_instance_endpoint" {
  value = aws_db_instance.main.endpoint
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
}

output "route53_zone_id" {
  value = aws_route53_zone.main.zone_id
}

output "global_accelerator_arn" {
  value = aws_global_accelerator.main.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_Route_53[Route 53]
    AWS_Global_Accelerator[Global Accelerator]
    Amazon_ECS[ECS]
    Amazon_EC2[EC2]
    Amazon_RDS[(RDS)]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_Route_53
    Amazon_CloudFront --> AWS_Global_Accelerator
    Amazon_Route_53 --> Amazon_ECS
    Amazon_Route_53 --> Amazon_EC2
    AWS_Global_Accelerator --> Amazon_ECS
    AWS_Global_Accelerator --> Amazon_EC2
    Amazon_ECS --> Amazon_RDS
    Amazon_EC2 --> Amazon_RDS
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_EC2 -->|metrics| Amazon_CloudWatch"
}

