resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-ecs-sg"
  tags = local.common_tags
}

resource "aws_security_group_rule" "allow_http" {
  type = "ingress"
  from_port = 80
  to_port = 80
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "allow_https" {
  type = "ingress"
  from_port = 443
  to_port = 443
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = var.api_gateway_url
    origin_id   = "apiGatewayOrigin"
  }

  enabled = true
  default_cache_behavior {
    target_origin_id = "apiGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
  }

  tags = local.common_tags
}

resource "aws_route53_zone" "main" {
  name = var.domain_name
  tags = local.common_tags
}

resource "aws_global_accelerator" "main" {
  name = "${local.name_prefix}-accelerator"
  enabled = true

  ip_address_type = "IPV4"
  # Add listener and endpoint group configurations here
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${local.name_prefix}-api"
  description = "API for ${local.name_prefix}"
  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-ecs-cluster"
  tags = local.common_tags
}

resource "aws_lambda_function" "main" {
  function_name = "${local.name_prefix}-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_role.arn
  s3_bucket = var.lambda_s3_bucket
  s3_key = var.lambda_s3_key
  tags = local.common_tags
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier = "${local.name_prefix}-aurora"
  engine = "aurora-postgresql"
  master_username = var.db_username
  master_password = var.db_password
  skip_final_snapshot = true
  tags = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name = "${local.name_prefix}-dynamodb"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  tags = local.common_tags
}

resource "aws_sqs_queue" "main" {
  name = "${local.name_prefix}-sqs"
  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "${local.name_prefix}-sns"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/${aws_lambda_function.main.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "${local.name_prefix}-xray-daemon"
  tags = local.common_tags
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.cdn.id
}

output "api_gateway_id" {
  value = aws_api_gateway_rest_api.api.id
