provider "aws" {
  region = var.account_region

  default_tags {
    tags = {
      Owner = "Security"
    }
  }
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

# Security Group for ELB
resource "aws_security_group" "elb" {
  vpc_id = aws_vpc.main.id
  name = "${var.project_name}-elb-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-elb-sg"
  }
}

# Security Group for ECS
resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "${var.project_name}-ecs-sg"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.elb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-ecs-sg"
  }
}

# Elastic Load Balancer
resource "aws_elb" "main" {
  name               = "${var.project_name}-elb"
  availability_zones = aws_subnet.public[*].availability_zone

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.project_name}-elb"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "app" {
  family                   = "${var.project_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "${var.project_name}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${var.project_name}-task"
  }
}

# ECS Service
resource "aws_ecs_service" "main" {
  name            = "${var.project_name}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  tags = {
    Name = "${var.project_name}-service"
  }
}

# RDS Instance
resource "aws_db_instance" "main" {
  identifier         = "${var.project_name}-rds"
  engine             = "mysql"
  engine_version     = "8.0"
  instance_class     = "db.t3.micro"
  allocated_storage   = 20
  storage_type       = "gp2"
  username           = var.db_username
  password           = var.db_password
  db_name            = var.db_name
  vpc_security_group_ids = [aws_security_group.ecs.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  skip_final_snapshot = true

  tags = {
    Name = "${var.project_name}-rds"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "main" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = {
    Name = "${var.project_name}-dynamodb-table"
  }
}

# SQS Queue
resource "aws_sqs_queue" "main" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-sqs-queue"
  }
}

# SNS Topic
resource "aws_sns_topic" "main" {
  name = "${var.project_name}-topic"

  tags = {
    Name = "${var.project_name}-sns-topic"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "main" {
  name = "${var.project_name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-log-group"
  }
}

# X-Ray Group
resource "aws_xray_group" "main" {
  filter_expression = "service(\"${var.project_name}\")"
  group_name       = "${var.project_name}-xray-group"

  tags = {
    Name = "${var.project_name}-xray-group"
  }
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "elb_dns_name" {
  value = aws_elb.main.dns_name
}

output "rds_endpoint" {
  value = aws_db_instance.main.endpoint
}",
