    CloudFront[CloudFront]
    Lambda_Edge[Lambda@Edge]
    AWS_Global_Accelerator[Global Accelerator]
    AWS_Lambda[Lambda]
    DynamoDB[(DynamoDB)]
    ElastiCache[(ElastiCache)]
    CloudWatch[CloudWatch]
