provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = var.public_subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count      = var.private_subnet_count
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "elb_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-elb-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.elb_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-ecs-sg"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-lambda-sg"
  }
}

resource "aws_elastic_load_balancer" "main" {
  name               = "${var.project_name}-elb"
  availability_zones = aws_vpc.main.availability_zones

  security_groups = [aws_security_group.elb_sg.id]

  tags = {
    Name = "${var.project_name}-elb"
  }
}

resource "aws_api_gateway_rest_api" "main" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = {
    Name = "${var.project_name}-api"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.project_name}-task"
  network_mode            = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "${var.project_name}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${var.project_name}-task"
  }
}

resource "aws_lambda_function" "main" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.video_storage.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "${var.project_name}-rds"
  engine                 = "postgres"
  master_username        = var.rds_username
  master_password        = var.rds_password
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.ecs_sg.id]

  tags = {
    Name = "${var.project_name}-rds"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

resource "aws_s3_bucket" "video_storage" {
  bucket = "${var.bucket_prefix}${var.project_name}-videos"

  tags = {
    Name        = "${var.project_name}-video-storage"
    Description = "S3 bucket for video storage"
  }
}

resource "aws_elasticache_cluster" "main" {
  cluster_id = "${var.project_name}-cache"
  engine     = "redis"
  node_type  = var.cache_node_type
  num_cache_nodes = 1
  parameter_group_name = "default.redis3.2"

  tags = {
    Name = "${var.project_name}-cache"
  }
}

resource "aws_sqs_queue" "video_uploads" {
  name = "${var.project_name}-video-uploads"

  tags = {
    Name = "${var.project_name}-video-uploads"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/${aws_lambda_function.main.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-cloudwatch-logs"
  }
}

resource "aws_xray_daemon" "main" {
  name = "${var.project_name}-xray-daemon"

  tags = {
    Name = "${var.project_name}-xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "elb_dns_name" {
  description = "DNS Name of the Elastic Load Balancer"
  value       = aws_elastic_load_balancer.main.dns_name
}

output "api_gateway_url" {
  description = "URL of the API Gateway"
  value       = aws_api_gateway_rest_api.main.execution_arn
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Name of the project."
  type        = string
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets."
  type        = number
  default     = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets."
  type        = number
  default     = 2
}

variable "rds_username" {
  description = "Username for the RDS database."
  type        = string
}

variable "rds_password" {
  description = "Password for the RDS database."
  type        = string
}

variable "ecs_cpu" {
  description = "CPU units for ECS task."
  type        = string
  default     = "256"
}

variable "ecs_memory" {
  description = "Memory for ECS task."
  type        = string
  default     = "512"
}

variable "container_image" {
  description = "Container image for ECS."
  type        = string
}

variable "cache_node_type" {
  description = "Node type for ElastiCache."
  type        = string
  default     = "cache.t2.micro"
}

variable "bucket_prefix" {
  description = "Bucket prefix for the S3."
  type        = string
  default     = "audiophile-e2e-pipeline-"
}",
