        "monthly_usd": 0.4,
        "unit": "per 1M messages"
      },
      {
        "service": "Amazon SNS",
        "monthly_usd": 0.5,
        "unit": "per 1M notifications"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 10.0,
        "unit": "estimated"
      },
      {
        "service": "AWS X-Ray",
        "monthly_usd": 5.0,
        "unit": "estimated"
      },
      {
        "service": "Data Transfer (egress)",
        "monthly_usd": 9.0,
        "unit": "per 100GB egress"
      }
