  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public_subnet\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"LogisticsAPI\"\n  description = \"API for logistics platform\"\n}\n\nresource \"aws_lambda_function\" \"process_records\" {\n  function_name = \"ProcessRecords\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  s3_bucket     = \"your_lambda_bucket\"\n  s3_key        = \"lambda_code.zip\"\n}\n\nresource \"aws_dynamodb_table\" \"records\" {\n  name         = \"RecordsTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"RecordID\"\n    type = \"S\"\n  }\n  hash_key = \"RecordID\"\n}\n\nresource \"aws_sqs_queue\" \"record_queue\" {\n  name = \"RecordQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/ProcessRecords\"\n}",
