  },
  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"VideoTranscodingAPI\"\n}\n\nresource \"aws_lambda_function\" \"transcoder\" {\n  function_name = \"TranscoderFunction\"\n  runtime = \"python3.8\"\n  handler = \"transcoder.handler\"\n  role = aws_iam_role.lambda_exec.arn\n  source_code_hash = filebase64sha256(\"./lambda.zip\")\n}\n\nresource \"aws_ecs_cluster\" \"transcoding\" {\n  name = \"VideoTranscodingCluster\"\n}\n\nresource \"aws_s3_bucket\" \"video_bucket\" {\n  bucket = \"user-uploaded-videos\"\n}\n\nresource \"aws_dynamodb_table\" \"video_metadata\" {\n  name         = \"VideoMetadata\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"video_id\"\n    type = \"S\"\n  }\n  hash_key = \"video_id\"\n}\n\nresource \"aws_sqs_queue\" \"transcoding_queue\" {\n  name = \"TranscodingQueue\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name\n    origin_id   = \"S3Origin\"\n  }\n}\n",
  "diagram": "graph TD\n    User([User])\n    User -->|Upload Video| APIGateway[API Gateway]\n    APIGateway -->|Trigger| Lambda[Lambda Function]\n    Lambda -->|Store Video| S3[Amazon S3]\n    Lambda -->|Send Job| SQS[Amazon SQS]\n    SQS -->|Trigger| ECS[Amazon ECS]\n    ECS -->|Transcode| S3\n    S3 -->|Deliver via| CloudFront[Amazon CloudFront]\n    CloudFront -->|Serve Video| User"
}

