provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = {
    Name = "${var.environment}-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = {
    Name = "${var.environment}-private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "${var.environment}-ec2-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow SSH and HTTP access to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ssh_access_cidr]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-ec2-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${var.environment}-rds-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS from EC2 instances"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ec2_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = var.rds_allocated_storage
  identifier          = "${var.environment}-rds"
  instance_class      = var.rds_instance_class
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = var.rds_db_name
  username            = var.rds_username
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "${var.environment}-rds"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key

  tags = {
    Name = "${var.environment}-lambda"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-sqs-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "${var.environment}-sns-topic"

  tags = {
    Name = "${var.environment}-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "${var.environment}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.environment}-log-group"
  }
}

resource "aws_xray_daemon" "my_xray" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

resource "aws_directconnect_connection" "my_connection" {
  name = "${var.environment}-direct-connect"
  bandwidth = var.direct_connect_bandwidth
  connection_type = "dedicated"
  location = var.direct_connect_location
  lag_id = var.direct_connect_lag_id

  tags = {
    Name = "${var.environment}-direct-connect"
  }
}

resource "aws_vpn_connection" "my_vpn" {
  vpn_gateway_id = aws_vpn_gateway.my_vpn_gateway.id
  customer_gateway_id = aws_customer_gateway.my_customer_gateway.id
  type = "ipsec.1"

  tags = {
    Name = "${var.environment}-vpn-connection"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.my_topic.arn
