    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"subnet2\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1b\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress { from_port = 80, to_port = 80, protocol = \"tcp\", cidr_blocks = [\"0.0.0.0/0\"] }\n  ingress { from_port = 443, to_port = 443, protocol = \"tcp\", cidr_blocks = [\"0.0.0.0/0\"] }\n}\n\nresource \"aws_s3_bucket\" \"bucket\" {\n  bucket = \"patient-records-bucket\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin { domain_name = aws_s3_bucket.bucket.bucket_regional_domain_name, origin_id = \"S3Origin\" }\n  enabled = true\n  default_cache_behavior { target_origin_id = \"S3Origin\" }\n}\n\nresource \"aws_lb\" \"app_lb\" {\n  name               = \"app-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets           = [aws_subnet.subnet1.id, aws_subnet.subnet2.id]\n}\n\nresource \"aws_ecs_cluster\" \"ecs_cluster\" {\n  name = \"patient-records-cluster\"\n}\n\nresource \"aws_rds_cluster\" \"db\" {\n  engine = \"aurora\"\n  db_instance_class = \"db.t3.medium\"\n  master_username = \"admin\"\n  master_password = \"password\"\n}\n\nresource \"aws_lambda_function\" \"process_records\" {\n  function_name = \"processRecords\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  s3_bucket = aws_s3_bucket.bucket.id\n  s3_key = \"lambda.zip\"\n}",
