provider "aws" {
  region = var.account_region

  default_tags {
    tags = {
      Owner = "Security"
    }
  }
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-subnet-${count.index}"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-subnet-${count.index}"
  }
}

# Security Group for EC2
resource "aws_security_group" "ec2_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks  = [var.allowed_ssh_ip]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks  = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.project_name}-ec2-sg"
  }
}

# EC2 Instance
resource "aws_instance" "app_server" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.private[0].id
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "${var.project_name}-app-server"
  }
}

# RDS Instance
resource "aws_db_instance" "default" {
  allocated_storage    = var.rds_allocated_storage
  storage_type       = "gp2"
  engine             = "mysql"
  engine_version     = "8.0"
  instance_class     = var.rds_instance_class
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]
  username           = var.db_username
  password           = var.db_password
  db_name            = var.db_name
  skip_final_snapshot = true

  tags = {
    Name = "${var.project_name}-rds"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.project_name}-db-subnet-group"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "default" {
  name         = "${var.project_name}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.project_name}-dynamodb"
  }
}

# ElastiCache Cluster
resource "aws_elasticache_cluster" "default" {
  cluster_id           = "${var.project_name}-cache"
  engine               = "redis"
  node_type            = var.cache_node_type
  num_cache_nodes      = var.cache_node_count
  parameter_group_name = "default.redis3.2"
  subnet_group_name    = aws_elasticache_subnet_group.default.name
  security_group_ids   = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "${var.project_name}-elasticache"
  }
}

resource "aws_elasticache_subnet_group" "default" {
  name       = "${var.project_name}-cache-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.project_name}-cache-subnet-group"
  }
}

# SQS Queue
resource "aws_sqs_queue" "default" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-sqs"
  }
}

# SNS Topic
resource "aws_sns_topic" "default" {
  name = "${var.project_name}-topic"

  tags = {
    Name = "${var.project_name}-sns"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "default" {
  name = "${var.project_name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-cloudwatch"
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "default" {
  origin {
    domain_name = aws_api_gateway_rest_api.default.execution_arn
    origin_id   = "apiGatewayOrigin"
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGatewayOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "${var.project_name}-cloudfront"
  }
}

# API Gateway
resource "aws_api_gateway_rest_api" "default" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = {
    Name = "${var.project_name}-api"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "default" {
  name = "${var.project_name}-ecs-cluster"

  tags = {
    Name = "${var.project_name}-ecs-cluster"
  }
}

# Lambda Function
resource "aws_lambda_function" "default" {
  function_name = "${var.project_name}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "${var.project_name}-lambda-exec-role"
  }
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnets" {
  value = aws_subnet.public[*].id
}

output "private_subnets" {
  value = aws_subnet.private[*].id
}

output "rds_endpoint" {
  value = aws_db_instance.default.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.default.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.default.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.default.arn
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.default.id
}

output "api_gateway_id" {
  value = aws_api_gateway_rest_api.default.id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.default.name
}

output "lambda_function_name" {
  value = aws_lambda_function.default.function_name
}",
