    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_elb\" \"web\" {\n  name               = \"my-load-balancer\"\n  availability_zones = [\"us-east-1a\"]\n  security_groups    = [aws_security_group.allow_http.id]\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"PaymentAPI\"\n}\n\nresource \"aws_lambda_function\" \"payment_processor\" {\n  function_name = \"PaymentProcessor\"\n  handler       = \"index.handler\"\n  role          = aws_iam_role.lambda_exec.arn\n  runtime       = \"nodejs14.x\"\n}\n\nresource \"aws_db_instance\" \"default\" {\n  allocated_storage = 20\n  engine          = \"mysql\"\n  instance_class  = \"db.t2.micro\"\n  identifier      = \"payment-db\"\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"payment-cache\"\n  engine     = \"redis\"\n  node_type  = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}\n\nresource \"aws_sns_topic\" \"payment_notifications\" {\n  name = \"PaymentNotifications\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"payment_logs\" {\n  name = \"PaymentLogs\"\n}",
    "diagram": "graph TD\n    User([User])\n    User -->|Makes Payment| ELB([Elastic Load Balancer])\n    ELB -->|Routes to| Lambda([AWS Lambda])\n    Lambda -->|Reads/Writes| RDS([Amazon RDS])\n    Lambda -->|Caches| Cache([Amazon ElastiCache])\n    Lambda -->|Sends Notifications| SNS([Amazon SNS])\n    CloudFront([Amazon CloudFront]) --> ELB"
  }
}

