provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Owner = "Security"
    }
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t2.micro"
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

variable "redshift_password" {
  description = "Password for the database in the Redshift cluster"
  type        = string
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ec2_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

resource "aws_instance" "app_server" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "app-server"
  }
}

resource "aws_rds_instance" "staging_db" {
  identifier              = "staging-db"
  engine                 = "mysql"
  instance_class         = "db.t2.micro"
  allocated_storage       = 20
  username               = "admin"
  password               = var.rds_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "staging-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "data-bucket"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda_function.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    variable_name = "value"
  }

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/my_lambda_function"

  retention_in_days = 14

  tags = {
    Name = "lambda_logs"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"

  tags = {
    Name = "my_queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my_topic"

  tags = {
    Name = "my_topic"
  }
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_s3_bucket.data_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "my_distribution"
  }
}

resource "aws_redshift_cluster" "my_redshift" {
  cluster_identifier = "my-redshift-cluster"
  node_type         = "dc2.large"
  master_username   = "masteruser"
  master_password   = var.redshift_password
  database_name     = "mydatabase"
  cluster_type      = "single-node"

  tags = {
    Name = "my_redshift_cluster"
  }
}

resource "aws_transit_gateway" "main" {
  description = "Main Transit Gateway"

  tags = {
    Name = "main-transit-gateway"
  }
}

resource "aws_xray_daemon" "my_xray" {
  name = "my_xray_daemon"

  tags = {
    Name = "my_xray_daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "rds_endpoint" {
  value = aws_rds_instance.staging_db.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "redshift_endpoint" {
  value = aws_redshift_cluster.my_redshift.endpoint
}",
