  "terraform": "resource \"aws_vpc\" \"main\" {  cidr_block = \"10.0.0.0/16\"  enable_dns_support = true  enable_dns_hostnames = true}\n\nresource \"aws_subnet\" \"subnet_a\" {  vpc_id     = aws_vpc.main.id  cidr_block = \"10.0.1.0/24\"  availability_zone = \"us-east-1a\"}\n\nresource \"aws_subnet\" \"subnet_b\" {  vpc_id     = aws_vpc.main.id  cidr_block = \"10.0.2.0/24\"  availability_zone = \"us-east-1b\"}\n\nresource \"aws_security_group\" \"eks_sg\" {  vpc_id = aws_vpc.main.id  ingress {    from_port   = 443    to_port     = 443    protocol    = \"tcp\"    cidr_blocks = [\"0.0.0.0/0\"]  }}\n\nresource \"aws_eks_cluster\" \"eks\" {  name     = \"ml-model-cluster\"  role_arn = \"<EKS-ROLE-ARN>\"  vpc_config {    subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]    security_group_ids = [aws_security_group.eks_sg.id]  }}\n\nresource \"aws_lambda_function\" \"model_inference\" {  function_name = \"modelInference\"  role = \"<LAMBDA-ROLE-ARN>\"  handler = \"index.handler\"  runtime = \"python3.8\"  s3_bucket = \"<YOUR-BUCKET>\"  s3_key = \"<YOUR-ZIP>\"}\n\nresource \"aws_dynamodb_table\" \"predictions\" {  name         = \"Predictions\"  billing_mode = \"PAY_PER_REQUEST\"  attribute {    name = \"prediction_id\"    type = \"S\"  }}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {  origin {    domain_name = \"<YOUR-API-ENDPOINT>\"    origin_id   = \"api\"  }  enabled = true  default_cache_behavior {    target_origin_id = \"api\"    viewer_protocol_policy = \"redirect-to-https\"  }}\n\nresource \"aws_elastic_load_balancer\" \"load_balancer\" {  name = \"ml-model-elb\"  security_groups = [aws_security_group.eks_sg.id]  subnets = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]}",
  "diagram": "graph TD\n    User([User])\n    CDN[Amazon CloudFront]\n    ELB[AWS Elastic Load Balancer]\n    EKS[Amazon EKS]\n    Lambda[AWS Lambda]\n    DB[Amazon DynamoDB]\n    Monitoring[Amazon CloudWatch]\n    User -->|Requests| CDN\n    CDN -->|Forward| ELB\n    ELB -->|Route| EKS\n    ELB -->|Route| Lambda\n    EKS -->|Read/Write| DB\n    Lambda -->|Read/Write| DB\n    EKS -->|Metrics| Monitoring\n    Lambda -->|Metrics| Monitoring"
}

