    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"SaaS Dashboard API\"\n}\n\nresource \"aws_lambda_function\" \"dashboard_function\" {\n  function_name = \"DashboardFunction\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids          = [aws_subnet.private.id]\n    security_group_ids  = [aws_security_group.allow_http.id]\n  }\n}\n\nresource \"aws_kinesis_stream\" \"event_stream\" {\n  name        = \"EventStream\"\n  shard_count = 1\n}\n\nresource \"aws_rds_cluster\" \"aurora\" {\n  cluster_identifier = \"aurora-cluster\"\n  engine = \"aurora\"\n  master_username = \"admin\"\n  master_password = \"Password123\"\n}\n\nresource \"aws_dynamodb_table\" \"event_table\" {\n  name         = \"EventTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"EventID\"\n    type = \"S\"\n  }\n  hash_key = \"EventID\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.api.invoke_url\n    origin_id   = \"APIGateway\"\n  }\n  enabled             = true\n  default_cache_behavior {\n    target_origin_id = \"APIGateway\"\n    viewer_protocol_policy = \"redirect-to-https\"\n  }\n}",
