    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"podcast_api\" {\n  name        = \"Podcast API\"\n  description = \"API for podcast platform\"\n}\n\nresource \"aws_lambda_function\" \"podcast_ingester\" {\n  function_name = \"PodcastIngester\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"podcast_records\" {\n  name         = \"PodcastRecords\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_rds_instance\" \"podcast_db\" {\n  identifier = \"podcast-db\"\n  instance_class = \"db.t3.medium\"\n  engine = \"mysql\"\n  username = \"admin\"\n  password = \"SuperSecretPassword\"\n  db_name = \"podcast\"\n}\n\nresource \"aws_sqs_queue\" \"podcast_queue\" {\n  name = \"PodcastQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"podcast_logs\" {\n  name = \"/aws/lambda/podcast-ingester\"\n}",
