  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1b\"\n}\n\nresource \"aws_security_group\" \"lambda_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_lambda_function\" \"banking_function\" {\n  function_name = \"bankingLambda\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role    = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids         = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]\n    security_group_ids = [aws_security_group.lambda_sg.id]\n  }\n}\n\nresource \"aws_dynamodb_table\" \"transactions\" {\n  name         = \"Transactions\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"transactionId\"\n    type = \"S\"\n  }\n  hash_key = \"transactionId\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"BankingAPI\"\n}\n\nresource \"aws_api_gateway_resource\" \"transactions\" {\n  rest_api_id = aws_api_gateway_rest_api.api.id\n  parent_id   = aws_api_gateway_rest_api.api.root_resource_id\n  path_part   = \"transactions\"\n}\n\nresource \"aws_api_gateway_method\" \"get_transactions\" {\n  rest_api_id   = aws_api_gateway_rest_api.api.id\n  resource_id   = aws_api_gateway_resource.transactions.id\n  http_method   = \"GET\"\n  authorization = \"NONE\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"lambda_logs\" {\n  name = \"/aws/lambda/bankingLambda\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Request| API[API Gateway]\n    API -->|Invoke| Lambda[AWS Lambda]\n    Lambda -->|Read/Write| DB[Amazon DynamoDB]\n    Lambda -->|Publish| SNS[Amazon SNS]\n    Lambda -->|Log| CW[Amazon CloudWatch]\n    API -->|Cache| CF[Amazon CloudFront]"
}

