variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_type" {
  description = "Instance type for the RDS database"
  default     = "db.t3.micro"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "my_lambda_function"
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow Lambda to access resources in the VPC"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda_sg"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2_sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow EC2 instances to communicate with each other"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2_sg"
  }
}

resource "aws_db_instance" "aurora_postgres" {
  allocated_storage    = 20
  identifier          = "aurora-postgres-instance"
  instance_class      = var.db_instance_type
  engine             = "aurora-postgresql"
  engine_version      = "14.1"
  db_name             = "mydatabase"
  username            = "admin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "aurora-postgres"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.lambda_sg.id]
  }

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "lambda_exec_role"
  }
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "lambda_logs"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "aurora_endpoint" {
  value = aws_db_instance.aurora_postgres.endpoint
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_VPC[VPC]
    AWS_Direct_Connect[Direct Connect]
    AWS_Lambda[Lambda]
    Amazon_EC2[EC2]
    Amazon_Aurora_PostgreSQL[(Aurora PostgreSQL)]
    AWS_Database_Migration_Service[(Database Migration Service)]
    AWS_Schema_Conversion_Tool[(Schema Conversion Tool)]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_VPC
    User --> AWS_Direct_Connect
    Amazon_VPC --> AWS_Lambda
    Amazon_VPC --> Amazon_EC2
    AWS_Direct_Connect --> AWS_Lambda
    AWS_Direct_Connect --> Amazon_EC2
    AWS_Lambda --> Amazon_Aurora_PostgreSQL
    AWS_Lambda --> AWS_Database_Migration_Service
    AWS_Lambda --> AWS_Schema_Conversion_Tool
    Amazon_EC2 --> Amazon_Aurora_PostgreSQL
    Amazon_EC2 --> AWS_Database_Migration_Service
    Amazon_EC2 --> AWS_Schema_Conversion_Tool
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Amazon_EC2 -->|metrics| Amazon_CloudWatch
    Amazon_EC2 -->|metrics| AWS_X_Ray"
}

