  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"order_processor\" {\n  filename         = \"order_processor.zip\"\n  function_name    = \"order_processor\"\n  role             = aws_iam_role.lambda_exec.arn\n  handler          = \"order_processor.handler\"\n  source_code_hash = filebase64sha256(\"order_processor.zip\")\n  runtime          = \"nodejs14.x\"\n}\n\nresource \"aws_dynamodb_table\" \"orders\" {\n  name         = \"Orders\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"OrderId\"\n    type = \"S\"\n  }\n  hash_key = \"OrderId\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"OrderAPI\"\n  description = \"API for order fulfillment\"\n}\n\nresource \"aws_sns_topic\" \"order_notifications\" {\n  name = \"OrderNotifications\"\n}\n\nresource \"aws_sqs_queue\" \"order_queue\" {\n  name = \"OrderQueue\"\n}",
