locals {
  common_tags = {
    ManagedBy = "terraform"
    Environment = "production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "public-subnet-${count.index}" })
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, { Name = "private-subnet-${count.index}" })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = local.common_tags
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "ecs_security_group"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_rds_instance" "db" {
  identifier = "mydb-instance"
  engine = "postgres"
  instance_class = var.db_instance_class
  allocated_storage = 20
  db_name = var.db_name
  username = var.db_username
  password = var.db_password
  vpc_security_group_ids = [aws_security_group.ecs.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  skip_final_snapshot = true

  tags = local.common_tags
}

resource "aws_db_subnet_group" "main" {
  name = "mydb-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = var.ecs_cluster_name

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "app" {
  family = "my-app"
  network_mode = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu = "256"
  memory = "512"

  container_definitions = jsonencode([{
    name = "my-app"
    image = "my-app-image:latest"
    portMappings = [{
      containerPort = 80
      hostPort = 80
      protocol = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_ecs_service" "app" {
  name = var.ecs_service_name
  cluster = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count = 1
  launch_type = "FARGATE"

  network_configuration {
    subnets = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  tags = local.common_tags
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway.rest_api.invoke_url
    origin_id = "api_gateway"
  }

  enabled = true
  is_ipv6_enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "main" {
  name = "my-api"
  description = "My API Gateway"

  tags = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name = "my-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = local.common_tags
}

resource "aws_sqs_queue" "main" {
  name = "my-sqs-queue"

  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "my-sns-topic"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/ecs/my-app"
  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "xray-daemon"

  tags = local.common_tags
}

output "vpc_id" {
  description = "The ID of the VPC"
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value = aws_subnet.private[*].id
}

output "rds_endpoint" {
  description = "The endpoint of the RDS instance"
  value = aws_rds_instance.db.endpoint
}

output "ecs_cluster_name" {
  description = "The name of the ECS cluster"
  value = aws_ecs_cluster.main.name
}

output "cloudfront_distribution_id" {
  description = "The ID of the CloudFront distribution"
  value = aws_cloudfront_distribution.main.id
}

output "dynamodb_table_name" {
  description = "The name of the DynamoDB table"
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  description = "The URL of the SQS queue"
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic"
  value = aws_sns_topic.main.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
