provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Owner       = "DevOps"
      Environment = "Production"
    }
  }
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "main-ecs-cluster"

  tags = {
    Name = "main-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = "app-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "app-container"
    image     = "my-app-image:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "app-task-definition"
  }
}

resource "aws_ecs_service" "app" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  tags = {
    Name = "app-ecs-service"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "main-rds-cluster"
  engine                 = "aurora"
  master_username        = "admin"
  master_password        = "SuperSecretPassword"
  skip_final_snapshot    = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.ecs_sg.id]

  tags = {
    Name = "main-rds-cluster"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main-db-subnet-group"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "main-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "main-dynamodb-table"
  }
}

resource "aws_sqs_queue" "main" {
  name = "main-sqs-queue"

  tags = {
    Name = "main-sqs-queue"
  }
}

resource "aws_sns_topic" "main" {
  name = "main-sns-topic"

  tags = {
    Name = "main-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "main-log-group"

  tags = {
    Name = "main-log-group"
  }
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_ecs_service.app.load_balancer_dns_name
    origin_id   = "ecs-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "ecs-origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "main-cloudfront-distribution"
  }
}

resource "aws_transit_gateway" "main" {
  description = "Main Transit Gateway"

  tags = {
    Name = "main-transit-gateway"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "ecs_cluster_id" {
  value = aws_ecs_cluster.main.id
}

output "rds_cluster_id" {
  value = aws_rds_cluster.main.id
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
