  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_application_load_balancer.main.dns_name\n    origin_id   = \"ALB\"\n  }\n}\n\nresource \"aws_lb\" \"main\" {\n  name               = \"my-load-balancer\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets            = [aws_subnet.public.id]\n}\n\nresource \"aws_lambda_function\" \"ticket_processor\" {\n  function_name = \"ticketProcessor\"\n  s3_bucket    = \"my-lambda-bucket\"\n  handler      = \"index.handler\"\n  runtime      = \"nodejs14.x\"\n}\n\nresource \"aws_ecs_cluster\" \"main\" {\n  name = \"ticketing-cluster\"\n}\n\nresource \"aws_dynamodb_table\" \"tickets\" {\n  name         = \"Tickets\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"ticketId\"\n    type = \"S\"\n  }\n  hash_key = \"ticketId\"\n}\n\nresource \"aws_sqs_queue\" \"ticket_queue\" {\n  name = \"ticketQueue\"\n}",
