  "terraform": "provider \"aws\" {\n  region = \"us-east-1\"\n}\n\nresource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"ecs_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_ecs_cluster\" \"main\" {\n  name = \"leaderboard-cluster\"\n}\n\nresource \"aws_ecs_task_definition\" \"leaderboard_task\" {\n  family                = \"leaderboard\"\n  network_mode         = \"awsvpc\"\n  requires_compatibilities = [\"FARGATE\"]\n  container_definitions = jsonencode([\n    {\n      name      = \"leaderboard-container\"\n      image     = \"your-image-url\"\n      memory    = 512\n      cpu       = 256\n      portMappings = [{\n        containerPort = 80\n        hostPort      = 80\n      }]\n    }\n  ])\n}\n\nresource \"aws_service\" \"ecs_service\" {\n  cluster        = aws_ecs_cluster.main.id\n  desired_count  = 1\n  task_definition = aws_ecs_task_definition.leaderboard_task.arn\n  launch_type    = \"FARGATE\"\n  network_configuration {\n    subnets          = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]\n    security_groups  = [aws_security_group.ecs_sg.id]\n    assign_public_ip = true\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"leaderboard_api\"\n}\n\nresource \"aws_dynamodb_table\" \"leaderboard_table\" {\n  name         = \"leaderboard\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"playerId\"\n    type = \"S\"\n  }\n  hash_key = \"playerId\"\n}\n\nresource \"aws_kinesis_stream\" \"leaderboard_stream\" {\n  name        = \"leaderboard_stream\"\n  shard_count = 1\n}\n",
  "diagram": "graph TD\n    User([User])\n    User -->|requests leaderboard| API[API Gateway]\n    API -->|routes to| ALB[Application Load Balancer]\n    ALB -->|forwards to| ECS[ECS Cluster]\n    ECS -->|reads/writes| DB[DynamoDB]\n    ECS -->|streams updates| Kinesis[Kinesis Stream]\n    Kinesis -->|real-time data| Analytics[Analytics Service]\n    API -->|cached content| CF[CloudFront]\n    CF -->|serves to| User"
}

