  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_api_gateway_v2_api\" \"websocket_api\" {\n  name          = \"chat-websocket-api\"\n  protocol_type = \"WEBSOCKET\"\n}\n\nresource \"aws_lambda_function\" \"chat_handler\" {\n  function_name = \"chatHandler\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids = [aws_subnet.public.id]\n  }\n}\n\nresource \"aws_dynamodb_table\" \"chat_messages\" {\n  name         = \"ChatMessages\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"MessageId\"\n    type = \"S\"\n  }\n  hash_key = \"MessageId\"\n}\n\nresource \"aws_sqs_queue\" \"chat_queue\" {\n  name = \"chatQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/chatHandler\"\n}\n\nresource \"aws_security_group\" \"allow_lambda\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n",
