resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${count.index}"
  })
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.project_name}-api-sg"
  description = "Security group for API Gateway and Lambda"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.project_name}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_code.bucket
  s3_key        = aws_s3_bucket_object.lambda_code.key

  environment {
    DB_CONNECTION_STRING = aws_secretsmanager_secret.db_connection.secret_string
  }

  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.project_name}-api"
  description = "API for ${var.project_name}"

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "api_resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = local.common_tags
}

resource "aws_api_gateway_method" "api_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.api_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri  = aws_lambda_function.api_lambda.invoke_arn
  }

  tags = local.common_tags
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin {
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD", "OPTIONS"]

    forwarded_values {
      query_string = true
    }
  }

  tags = local.common_tags
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "${var.project_name}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "ecs_task" {
  family                   = "${var.project_name}-task"
  network_mode             = "awsvpc"
  requires_compatibilities  = ["FARGATE"]
  cpu                      = var.ecs_cpu
  memory                   = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "${var.project_name}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.project_name}-dynamodb"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = local.common_tags
}

resource "aws_db_instance" "rds_instance" {
  identifier         = "${var.project_name}-rds"
  engine             = "postgres"
  instance_class     = var.db_instance_class
  allocated_storage   = var.db_allocated_storage
  db_name            = var.db_name
  username           = var.db_username
  password           = var.db_password
  skip_final_snapshot = true

  tags = local.common_tags
}

resource "aws_elasticache_cluster" "cache" {
  cluster_id           = "${var.project_name}-cache"
  engine               = "redis"
  node_type            = var.cache_node_type
  num_cache_nodes      = var.cache_node_count
  parameter_group_name = "default.redis3.2"

  tags = local.common_tags
}

resource "aws_sqs_queue" "main" {
  name = "${var.project_name}-sqs"

  tags = local.common_tags
}

resource "aws_sns_topic" "main" {
  name = "${var.project_name}-sns"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "main" {
  name = "${var.project_name}-xray-daemon"

  tags = local.common_tags
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "cache_endpoint" {
  value = aws_elasticache_cluster.cache.configuration_endpoint
