provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_username" {
  description = "Username for the RDS database."
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS database."
  type        = string
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  type        = string
  default     = "my-ecs-cluster"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "my-lambda-function"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "my-dynamodb-table"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue."
  type        = string
  default     = "my-sqs-queue"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic."
  type        = string
  default     = "my-sns-topic"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "allow_http" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-http"
  }
}

resource "aws_security_group" "allow_https" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow-https"
  }
}

resource "aws_rds_cluster" "default" {
  engine         = "aurora"
  engine_mode    = "provisioned"
  master_username = var.db_username
  master_password = var.db_password
  database_name   = "mydatabase"
  skip_final_snapshot = true

  vpc_security_group_ids = [aws_security_group.allow_http.id]

  tags = {
    Name = "my-rds-cluster"
  }
}

resource "aws_dynamodb_table" "default" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_sqs_queue" "default" {
  name = var.sqs_queue_name

  tags = {
    Name = var.sqs_queue_name
  }
}

resource "aws_sns_topic" "default" {
  name = var.sns_topic_name

  tags = {
    Name = var.sns_topic_name
  }
}

resource "aws_lambda_function" "default" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_cloudwatch_log_group" "default" {
  name = "/aws/lambda/${aws_lambda_function.default.function_name}"

  retention_in_days = 14

  tags = {
    Name = "CloudWatch Log Group for ${aws_lambda_function.default.function_name}"
  }
}

resource "aws_api_gateway_rest_api" "default" {
  name        = "MyAPI"
  description = "My API Gateway"

  tags = {
    Name = "MyAPI"
  }
}

resource "aws_api_gateway_resource" "default" {
  rest_api_id = aws_api_gateway_rest_api.default.id
  parent_id   = aws_api_gateway_rest_api.default.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "MyResource"
  }
}

resource "aws_api_gateway_method" "default" {
  rest_api_id   = aws_api_gateway_rest_api.default.id
  resource_id   = aws_api_gateway_resource.default.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "MyAPIMethod"
  }
}

resource "aws_cloudfront_distribution" "default" {
  origin {
    domain_name = aws_api_gateway_rest_api.default.execution_arn
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = ""

  default_cache_behavior {
    target_origin_id = "api_gateway"

    forwarded_values {
      query_string = false
    }

    viewer_protocol_policy = "redirect-to-https"
  }

  tags = {
    Name = "MyCloudFrontDistribution"
  }
}

resource "aws_elb" "default" {
  name               = "my-elb"
  availability_zones = aws_subnet.public[*].availability_zone

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "MyELB"
  }
}

resource "aws_cloudwatch_metric_alarm" "high_cpu" {
  alarm_name          = "High CPU Alarm"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name        = "CPUUtilization"
  namespace          = "AWS/EC2"
  period             = "60"
  statistic          = "Average"
  threshold          = "80"
  alarm_description  = "This metric monitors ec2 high cpu utilization"
  dimensions = {
    InstanceId = aws_instance.my_instance.id
  }

  tags = {
    Name = "HighCPUAlarm"
  }
}

resource "aws_xray_daemon" "default" {
  name = "xray-daemon"

  tags = {
    Name = "XRayDaemon"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "rds_endpoint" {
  description = "The endpoint of the RDS instance"
  value       = aws_rds_cluster.default.endpoint
}

output "dynamodb_table_name" {
  description = "The name of the DynamoDB table"
  value       = aws_dynamodb_table.default.name
}

output "sqs_queue_url" {
  description = "The URL of the SQS queue"
  value       = aws_sqs_queue.default.id
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic"
  value       = aws_sns_topic.default.arn
}

output "lambda_function_name" {
  description = "The name of the Lambda function"
  value       = aws_lambda_function.default.function_name
}

output "cloudfront_distribution_id" {
  description = "The ID of the CloudFront distribution"
  value       = aws_cloudfront_distribution.default.id
}

output "elb_dns_name" {
  description = "The DNS name of the ELB"
  value       = aws_elb.default.dns_name
