  "terraform": "variable "aws_region" {
  description = "Region for the AWS services to run in."
  type = string
  default = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_username" {
  description = "Username for the RDS database."
  type = string
  default = "admin"
}

variable "db_password" {
  description = "Password for the RDS database."
  type = string
}

variable "ecs_cluster_name" {
  description = "Name of the ECS cluster."
  type = string
  default = "my-ecs-cluster"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type = string
  default = "my-lambda-function"
}

variable "rds_instance_type" {
  description = "Instance type for RDS."
  type = string
  default = "db.t3.micro"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  type = string
  default = "my-dynamodb-table"
}

variable "sqs_queue_name" {
  description = "Name of the SQS queue."
  type = string
  default = "my-sqs-queue"
}

variable "sns_topic_name" {
  description = "Name of the SNS topic."
  type = string
  default = "my-sns-topic"
}

provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_db_instance" "default" {
  identifier = "mydb"
  engine = "mysql"
  instance_class = var.rds_instance_type
  allocated_storage = 20
  username = var.db_username
  password = var.db_password
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot = true

  tags = {
    Name = "mydb-instance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "my-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "my-db-subnet-group"
  }
}

resource "aws_ecs_cluster" "default" {
  name = var.ecs_cluster_name

  tags = {
    Name = var.ecs_cluster_name
  }
}

resource "aws_lambda_function" "default" {
  function_name = var.lambda_function_name
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = aws_s3_bucket.lambda_bucket.bucket
  s3_key = aws_s3_bucket_object.lambda_object.key

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = "${var.lambda_function_name}-bucket"

  tags = {
    Name = "${var.lambda_function_name}-bucket"
  }
}

resource "aws_s3_bucket_object" "lambda_object" {
  bucket = aws_s3_bucket.lambda_bucket.bucket
  key    = "function.zip"
  source = "path/to/your/lambda/function.zip"
}

resource "aws_dynamodb_table" "default" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_sqs_queue" "default" {
  name = var.sqs_queue_name

  tags = {
    Name = var.sqs_queue_name
  }
