  default     = "audiophile-e2e-pipeline-"
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

variable "ecs_instance_type" {
  description = "EC2 instance type for ECS"
  type        = string
  default     = "t3.micro"
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "redis_instance_type" {
  description = "ElastiCache instance type"
  type        = string
  default     = "cache.t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true
  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 2
  vpc_id = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_security_group_rule" "allow_http" {
  type              = "ingress"
  from_port        = 80
  to_port          = 80
  protocol         = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks      = ["0.0.0.0/0"]
}

resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_security_group_rule" "allow_rds" {
  type              = "ingress"
  from_port        = 5432
  to_port          = 5432
  protocol         = "tcp"
  security_group_id = aws_security_group.rds.id
  cidr_blocks      = [aws_security_group.ecs.id]
}

resource "aws_rds_instance" "db" {
  identifier         = "mydb"
  engine            = "postgres"
  instance_class    = var.db_instance_class
  allocated_storage  = 20
  username          = "admin"
  password          = var.rds_password
  db_name           = "mydatabase"
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot = true
  tags = {
    Name = "mydb-instance"
  }
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "my-redis"
  engine              = "redis"
  node_type           = var.redis_instance_type
  num_cache_nodes     = 1
  security_group_ids  = [aws_security_group.rds.id]
  tags = {
    Name = "my-redis-cluster"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my-queue"
  tags = {
    Name = "my-sqs-queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my-topic"
  tags = {
    Name = "my-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "my-log-group"
  retention_in_days = 14
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.bucket_prefix
  s3_key        = "lambda/my_lambda.zip"
  environment = {
    QUEUE_URL = aws_sqs_queue.my_queue.id
  }
  tags = {
    Name = "my-lambda-function"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name = "my-api"
  description = "My API Gateway"
  tags = {
    Name = "my-api-gateway"
  }
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id   = "myApiOrigin"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "myApiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "POST"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
  }
  tags = {
    Name = "my-cloudfront-distribution"
  }
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "my-cluster"
  tags = {
    Name = "my-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "service" {
  family                   = "service"
  container_definitions    = file("task-definitions/service.json")

  proxy_configuration {
    type = "APPMESH"
    container_name = "applicationContainerName"
    properties = {
      AppPorts           = "8080"
      EgressIgnoredIPs    = "169.254.170.2,169.254.169.254"
      IgnoredUID         = "1337"
      ProxyEgressPort    = 15001
      ProxyIngressPort    = 15000
    }
  }
}

output "rds_endpoint" {
  value = aws_rds_instance.db.endpoint
}

output "redis_endpoint" {
  value = aws_elasticache_cluster.redis.configuration_endpoint
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.my_topic.arn
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.my_api.execution_arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_ECS[ECS]
    AWS_Lambda[Lambda]
    Amazon_RDS[(RDS)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_API_Gateway --> Amazon_ECS
    Amazon_API_Gateway --> AWS_Lambda
    Application_Load_Balancer --> Amazon_ECS
    Application_Load_Balancer --> AWS_Lambda
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS --> Amazon_SQS
    Amazon_ECS --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray"
}

{
