    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"private_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"fraud_detection\" {\n  handler = \"index.handler\"\n  role    = aws_iam_role.lambda_exec.arn\n  runtime = \"nodejs14.x\"\n}\n\nresource \"aws_dynamodb_table\" \"transactions\" {\n  name           = \"Transactions\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"TransactionId\"\n    type = \"S\"\n  }\n  hash_key = \"TransactionId\"\n}\n\nresource \"aws_kinesis_stream\" \"fraud_stream\" {\n  name        = \"FraudStream\"\n  shard_count = 1\n}\n\nresource \"aws_ecs_cluster\" \"fraud_cluster\" {\n  name = \"FraudDetectionCluster\"\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"fraud-cache\"\n  engine     = \"redis\"\n  node_type  = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}\n\nresource \"aws_cloudwatch_log_group\" \"fraud_logs\" {\n  name = \"FraudDetectionLogs\"\n}\n",
