  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_websocket\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"chat_api\" {\n  name = \"Chat API\"\n}\n\nresource \"aws_lambda_function\" \"message_handler\" {\n  function_name = \"MessageHandler\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"messages\" {\n  name           = \"Messages\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"messageId\"\n    type = \"S\"\n  }\n  hash_key = \"messageId\"\n}\n\nresource \"aws_sns_topic\" \"chat_notifications\" {\n  name = \"ChatNotifications\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"chat-logs\"\n}",
