provider "aws" {
  region = var.region
}

locals {
  common_tags = {
    ManagedBy = "terraform"
    Environment = var.environment
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = merge(local.common_tags, {
    Name = "${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index}"
  })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index}"
  })
}

resource "aws_security_group" "alb" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-alb-sg"
  })
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-ecs-sg"
  })
}

resource "aws_security_group" "lambda" {
  vpc_id = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-lambda-sg"
  })
}

resource "aws_cloudfront_distribution" "api_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.invoke_url
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"

    forwarded_values {
      query_string = true
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-cloudfront"
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment} environment"

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "api_resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = local.common_tags
}

resource "aws_api_gateway_method" "api_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.api_resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = local.common_tags
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = local.common_tags
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${var.environment}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory

  container_definitions = jsonencode([{
    name      = "app"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = local.common_tags
}

resource "aws_ecs_service" "app" {
  name            = "${var.environment}-ecs-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.ecs_desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  tags = local.common_tags
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-lambda"
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    variables = {
      DB_TABLE = var.dynamodb_table_name
    }
  }

  tags = local.common_tags
}

resource "aws_dynamodb_table" "my_table" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"

  tags = local.common_tags
}

resource "aws_elasticache_cluster" "cache" {
  cluster_id           = "${var.environment}-cache"
  engine               = "redis"
  node_type            = var.cache_node_type
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"

  tags = local.common_tags
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-queue"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"

  tags = local.common_tags
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "ecs_cluster_id" {
  description = "ECS Cluster ID"
  value       = aws_ecs_cluster.main.id
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.api_distribution.id
