resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private_subnet" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-gateway-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-api-gateway-sg"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-lambda-sg"

  ingress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-lambda-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-ecs-sg"

  ingress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  tags = {
    Name = "${var.environment}-ecs-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = 20
  identifier = "${var.environment}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = "14.1"
  db_name = "application_db"
  username = "awsadmin"
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name

  tags = {
    Name = "${var.environment}-rds"
  }
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "${var.environment}-rds-subnet-group"
  subnet_ids = aws_subnet.private_subnet[*].id

  tags = {
    Name = "${var.environment}-rds-subnet-group"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-my-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec_role.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "${var.environment}-my-lambda"
  }
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "${var.environment}-lambda-exec-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json

  tags = {
    Name = "${var.environment}-lambda-exec-role"
  }
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "${var.environment}-ecs-cluster"

  tags = {
    Name = "${var.environment}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "my_task" {
  family                   = "${var.environment}-task"
  network_mode            = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([
    {
      name      = "my_container"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])

  tags = {
    Name = "${var.environment}-task"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment}"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "${var.environment}-api-resource"
  }
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.environment}-api-method"
  }
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_api_gateway_rest_api.my_api.execution_arn
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "${var.environment}-cloudfront"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "${var.environment}-my-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "${var.environment}-dynamodb-table"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-my-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  tags = {
    Name = "${var.environment}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "my_xray" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.my_api.execution_invoke_url
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)."
  type        = string
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of public subnet CIDR blocks."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of private subnet CIDR blocks."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets."
  type        = number
  default     = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets."
  type        = number
  default     = 2
}

variable "rds_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

variable "rds_password" {
  description = "Password for the database in the RDS instance."
  type        = string
}

variable "container_image" {
  description = "Container image for ECS task."
  type        = string
}

variable "lambda_bucket" {
  description = "S3 bucket for Lambda function code."
  type        = string
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    Application_Load_Balancer --> AWS_Lambda
    Application_Load_Balancer --> Amazon_ECS
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray"
}

