provider "aws" {
  region = var.region
}

default_tags {
  tags = {
    ManagedBy = "terraform"
    Purpose    = "production"
  }
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "${var.name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = var.public_subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count      = var.private_subnet_count
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.name}-private-${count.index}"
  }
}

resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.name}-api-gateway-sg"
  }
}

resource "aws_security_group" "fargate" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.api_gateway.id]
  }

  tags = {
    Name = "${var.name}-fargate-sg"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.name}-api"
  description = "API for ${var.name}"

  tags = {
    Name = "${var.name}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = {
    Name = "${var.name}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.name}-api-method"
  }
}

resource "aws_lambda_function" "lambda" {
  function_name = "${var.name}-lambda"
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn

  tags = {
    Name = "${var.name}-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect    = "Allow"
        Sid       = ""
      }
    ]
  })

  tags = {
    Name = "${var.name}-lambda-exec-role"
  }
}

resource "aws_rds_instance" "db" {
  identifier              = "${var.name}-db"
  engine                 = "postgres"
  instance_class         = var.db_instance_class
  allocated_storage       = var.db_allocated_storage
  username               = var.db_username
  password               = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.db_sg.id]

  tags = {
    Name = "${var.name}-db"
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "${var.name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.name}-db-subnet-group"
  }
}

resource "aws_security_group" "db_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.fargate.id]
  }

  tags = {
    Name = "${var.name}-db-sg"
  }
}

resource "aws_dynamodb_table" "table" {
  name           = "${var.name}-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.name}-dynamodb-table"
  }
}

resource "aws_sqs_queue" "queue" {
  name = "${var.name}-sqs-queue"

  tags = {
    Name = "${var.name}-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.name}-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.name}-xray-daemon"

  tags = {
    Name = "${var.name}-xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = aws_api_gateway_rest_api.api.execution_arn
}

output "lambda_function_name" {
  description = "Lambda Function Name"
  value       = aws_lambda_function.lambda.function_name
}

output "rds_instance_endpoint" {
  description = "RDS Instance Endpoint"
  value       = aws_rds_instance.db.endpoint
}

output "dynamodb_table_name" {
  description = "DynamoDB Table Name"
  value       = aws_dynamodb_table.table.name
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.queue.id
}",
