  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"api_gateway_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"VideoTranscodingAPI\"\n}\n\nresource \"aws_lambda_function\" \"transcoder\" {\n  function_name = \"videoTranscoder\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n}\n\nresource \"aws_s3_bucket\" \"video_bucket\" {\n  bucket = \"user-uploaded-videos\"\n}\n\nresource \"aws_dynamodb_table\" \"video_metadata\" {\n  name           = \"VideoMetadata\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"videoId\"\n    type = \"S\"\n  }\n  hash_key = \"videoId\"\n}\n\nresource \"aws_sqs_queue\" \"transcoding_queue\" {\n  name = \"TranscodingQueue\"\n}\n\nresource \"aws_ecs_cluster\" \"transcoding_cluster\" {\n  name = \"TranscodingCluster\"\n}",
