    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow RDS access from ECS"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

resource "aws_rds_instance" "db" {
  identifier = "mydb"
  engine     = "mysql"
  instance_class = "db.t3.micro"
  allocated_storage = 20
  username   = "admin"
  password   = "password"
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "mydb-instance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "default-db-subnet-group"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "my-dynamodb-table"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my-queue"

  tags = {
    Name = "my-sqs-queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my-topic"

  tags = {
    Name = "my-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/my-log-group"

  retention_in_days = 14

  tags = {
    Name = "my-log-group"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = "my_lambda_bucket"
  s3_key        = "my_lambda.zip"

  environment {
    SQS_QUEUE_URL = aws_sqs_queue.my_queue.id
    SNS_TOPIC_ARN = aws_sns_topic.my_topic.arn
  }

  tags = {
    Name = "my-lambda-function"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "lambda-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_exec.name
}

resource "aws_iam_role_policy_attachment" "lambda_sqs" {
  policy_arn = "arn:aws:iam::aws:policy/AWSSQSSendMessage"
  role       = aws_iam_role.lambda_exec.name
}

resource "aws_iam_role_policy_attachment" "lambda_sns" {
  policy_arn = "arn:aws:iam::aws:policy/AWSSNSSendMessage"
  role       = aws_iam_role.lambda_exec.name
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name = aws_s3_bucket.my_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "my-cloudfront-distribution"
  }
