variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "s3_bucket" {
  description = "S3 bucket for Terraform state"
}

variable "dynamodb_table" {
  description = "DynamoDB table for state locking"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-security-group"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "ecs-cluster"
}

resource "aws_ecs_task_definition" "app" {
  family                   = "app-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  container_definitions   = jsonencode([{
    name      = "app"
    image     = "nginx:latest"
    memory    = 512
    cpu       = 256
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "app-task-definition"
  }
}

resource "aws_ecs_service" "app" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  tags = {
    Name = "app-service"
  }
}

resource "aws_lambda_function" "app" {
  function_name = "app-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.s3_bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "app-lambda"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = "app-cluster"
  engine                 = "aurora"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true
  database_name          = "appdb"
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "app-rds-cluster"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "app-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "app-dynamodb-table"
  }
}

resource "aws_sqs_queue" "main" {
  name = "app-sqs-queue"

  tags = {
    Name = "app-sqs-queue"
  }
}

resource "aws_sns_topic" "main" {
  name = "app-sns-topic"

  tags = {
    Name = "app-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "/aws/lambda/app-lambda"

  tags = {
    Name = "app-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "main" {
  name = "xray-daemon"

  tags = {
    Name = "app-xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "ecs_cluster_id" {
  value = aws_ecs_cluster.main.id
}

output "rds_cluster_endpoint" {
  value = aws_rds_cluster.main.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
