  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"legal_doc_processor\" {\n  function_name = \"LegalDocProcessor\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = \"arn:aws:iam::account-id:role/execution_role\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"legal_docs_api\" {\n  name = \"LegalDocsAPI\"\n}\n\nresource \"aws_dynamodb_table\" \"documents\" {\n  name         = \"LegalDocuments\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"DocumentID\"\n    type = \"S\"\n  }\n  hash_key = \"DocumentID\"\n}\n\nresource \"aws_rds_instance\" \"legal_docs_db\" {\n  allocated_storage    = 20\n  engine             = \"mysql\"\n  engine_version     = \"8.0\"\n  instance_class     = \"db.t3.micro\"\n  identifier         = \"legal-docs-db\"\n  username           = \"admin\"\n  password           = \"password\"\n  db_subnet_group_name = aws_db_subnet_group.default.name\n}\n\nresource \"aws_sqs_queue\" \"document_queue\" {\n  name = \"DocumentQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/legal_doc_processor\"\n}",
