  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region  = var.aws_region
  profile = var.aws_profile
}

variable "aws_region" {
  description = "The AWS region to deploy resources"
  default     = "ap-southeast-1"
}

variable "aws_profile" {
  description = "The AWS profile to use"
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "global_accelerator_sg" {
  name        = "global-accelerator-sg"
  description = "Security group for Global Accelerator"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "global-accelerator-sg"
  }
}

resource "aws_global_accelerator" "example" {
  name = "example-accelerator"

  enabled = true

  ip_address_type = "IPV4"

  listener {
    port_range {
      from_port = 80
      to_port   = 80
    }

    protocol = "TCP"

    client_affinity = "NONE"
  }

  tags = {
    Name = "example-accelerator"
  }
}

resource "aws_cloudfront_distribution" "example" {
  origin {
    domain_name = "example.com"
    origin_id   = "example-origin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "http-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "example-origin"

    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]

    cached_methods = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "example-cloudfront"
  }
}

resource "aws_transit_gateway" "example" {
  description = "Example Transit Gateway"

  tags = {
    Name = "example-transit-gateway"
  }
}

resource "aws_directconnect_gateway" "example" {
  name = "example-directconnect-gateway"

  tags = {
    Name = "example-directconnect-gateway"
  }
}

resource "aws_instance" "csr" {
  ami           = var.csr_ami
  instance_type = var.csr_instance_type
  subnet_id     = aws_subnet.private[0].id

  tags = {
    Name = "Cisco-CSR"
  }
}

variable "csr_ami" {
  description = "AMI for Cisco CSR"
  default     = "ami-xxxxxxxx" # Replace with actual AMI ID
}

variable "csr_instance_type" {
  description = "Instance type for Cisco CSR"
  default     = "t3.medium"
}

resource "aws_cloudwatch_log_group" "example" {
  name = "example-log-group"

  retention_in_days = 14

  tags = {
    Name = "example-log-group"
  }
}

resource "aws_cloudtrail" "example" {
  name                          = "example-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.example.bucket
  is_multi_region_trail         = true
  enable_logging                = true
  include_global_service_events = true

  tags = {
    Name = "example-cloudtrail"
  }
}

resource "aws_s3_bucket" "example" {
  bucket = "example-cloudtrail-bucket"

  tags = {
    Name = "example-cloudtrail-bucket"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "global_accelerator_id" {
  value = aws_global_accelerator.example.id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.example.id
}

output "transit_gateway_id" {
  value = aws_transit_gateway.example.id
}

output "directconnect_gateway_id" {
  value = aws_directconnect_gateway.example.id
}

output "csr_instance_id" {
  value = aws_instance.csr.id
}

output "cloudwatch_log_group_id" {
  value = aws_cloudwatch_log_group.example.id
}

output "cloudtrail_id" {
  value = aws_cloudtrail.example.id
}",
  "diagram": "graph TD
    User([User / Client])
    AWS_Global_Accelerator[Global Accelerator]
    Amazon_CloudFront[CloudFront]
    Amazon_VPC[VPC]
    AWS_Transit_Gateway[Transit Gateway]
    AWS_Direct_Connect[Direct Connect]
    Cisco_CSR_on_EC2[Cisco CSR on EC2]
    Amazon_CloudWatch[CloudWatch]
    AWS_CloudTrail[CloudTrail]
    User --> AWS_Global_Accelerator
    User --> Amazon_CloudFront
    AWS_Global_Accelerator --> Amazon_VPC
    AWS_Global_Accelerator --> AWS_Transit_Gateway
    AWS_Global_Accelerator --> AWS_Direct_Connect
    Amazon_CloudFront --> Amazon_VPC
    Amazon_CloudFront --> AWS_Transit_Gateway
    Amazon_CloudFront --> AWS_Direct_Connect
    Amazon_VPC --> Cisco_CSR_on_EC2
    AWS_Transit_Gateway --> Cisco_CSR_on_EC2
    AWS_Direct_Connect --> Cisco_CSR_on_EC2
    Cisco_CSR_on_EC2 -->|metrics| Amazon_CloudWatch
    Cisco_CSR_on_EC2 -->|metrics| AWS_CloudTrail"
}

