provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Owner = "Your Name"
      Environment = var.environment
    }
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)."
  type        = string
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-${count.index}"
  }
}

resource "aws_security_group" "alb_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-alb-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-ecs-sg"
  }
}

resource "aws_lb" "application" {
  name               = "${var.environment}-app-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = false

  tags = {
    Name = "${var.environment}-app-lb"
  }
}

resource "aws_lb_target_group" "ecs" {
  name     = "${var.environment}-ecs-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.environment}-ecs-tg"
  }
}

resource "aws_lb_listener" "front_end" {
  load_balancer_arn = aws_lb.application.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.ecs.arn
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = {
    Name = "${var.environment}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${var.environment}-app"
  requires_compatibilities  = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "app"
    image     = var.app_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${var.environment}-app-task"
  }
}

resource "aws_ecs_service" "app" {
  name            = "${var.environment}-app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  tags = {
    Name = "${var.environment}-app-service"
  }
}

resource "aws_lambda_function" "example" {
  function_name = "${var.environment}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = "lambda.zip"

  environment {
    variables = {
      DYNAMODB_TABLE = aws_dynamodb_table.example.name
    }
  }

  tags = {
    Name = "${var.environment}-lambda"
  }
}

resource "aws_dynamodb_table" "example" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"

  tags = {
    Name = "${var.environment}-dynamodb-table"
  }
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "${var.environment}-redis"
  engine              = "redis"
  node_type           = "cache.t2.micro"
  num_cache_nodes     = 1
  parameter_group_name = "default.redis3.2"
  port                = 6379

  tags = {
    Name = "${var.environment}-redis"
  }
}

resource "aws_sqs_queue" "example" {
  name = "${var.environment}-sqs-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_sns_topic" "example" {
  name = "${var.environment}-sns-topic"

  tags = {
    Name = "${var.environment}-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/${aws_lambda_function.example.function_name}"

  retention_in_days = 14

  tags = {
    Name = "${var.environment}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "example" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "alb_dns_name" {
  value = aws_lb.application.dns_name
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.example.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.example.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.example.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    Amazon_Route_53[Route 53]
    Amazon_ECS_with_Fargate[ECS with Fargate]
    AWS_Lambda[Lambda]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SQS[SQS]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_CloudFront --> Amazon_Route_53
    Application_Load_Balancer --> Amazon_ECS_with_Fargate
    Application_Load_Balancer --> AWS_Lambda
    Amazon_Route_53 --> Amazon_ECS_with_Fargate
    Amazon_Route_53 --> AWS_Lambda
    Amazon_ECS_with_Fargate --> Amazon_DynamoDB
    Amazon_ECS_with_Fargate --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS_with_Fargate --> Amazon_SQS
    Amazon_ECS_with_Fargate --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS_with_Fargate -->|metrics| Amazon_CloudWatch
