provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  ipv6_cidr_block = var.vpc_ipv6_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.project_name}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.project_name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.project_name}-private-${count.index}"
  }
}

resource "aws_security_group" "ecs_sg" {
  name        = "${var.project_name}-ecs-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow ECS tasks to communicate"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "${var.project_name}-lambda-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow Lambda to access RDS and SQS"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.rds_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "${var.project_name}-rds-sg"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.project_name}-ecs-cluster"
}

resource "aws_ecs_task_definition" "fargate" {
  family                   = "${var.project_name}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  container_definitions    = jsonencode([{
    name      = "${var.project_name}-container"
    image     = var.container_image
    memory    = var.container_memory
    cpu       = var.container_cpu
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${var.project_name}-task"
  }
}

resource "aws_lambda_function" "main" {
  function_name = "${var.project_name}-lambda"
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn

  environment {
    DB_HOST = aws_db_instance.rds_instance.endpoint
    DB_NAME = var.db_name
  }

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "${var.project_name}-rds"
  instance_class      = var.rds_instance_class
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = var.db_name
  username            = var.rds_username
  password            = var.rds_password
  publicly_accessible  = false
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  skip_final_snapshot  = true

  tags = {
    Name = "${var.project_name}-rds"
  }
}

resource "aws_sqs_queue" "main" {
  name = "${var.project_name}-queue"

  tags = {
    Name = "${var.project_name}-queue"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "${var.project_name}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.project_name}-log-group"
  }
}

resource "aws_xray_daemon" "main" {
  name = "${var.project_name}-xray-daemon"

  tags = {
    Name = "${var.project_name}-xray-daemon"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "lambda_function_name" {
  value = aws_lambda_function.main.function_name
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name"
  type        = string
  default     = "my_project"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_ipv6_cidr" {
  description = "IPv6 CIDR block for the VPC"
  type        = string
  default     = "2600:1f14:abcd:1234::/64"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets"
  type        = number
  default     = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets"
  type        = number
  default     = 2
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "Database name"
  type        = string
  default     = "mydatabase"
}

variable "rds_username" {
  description = "RDS username"
  type        = string
  default     = "admin"
}

variable "rds_password" {
  description = "RDS password"
  type        = string
  sensitive = true
}

variable "container_image" {
  description = "Container image for ECS"
  type        = string
  default     = "myimage:latest"
}

variable "container_memory" {
  description = "Memory for ECS container"
  type        = number
  default     = 512
}

variable "container_cpu" {
  description = "CPU units for ECS container"
  type        = number
  default     = 256
}

variable "lambda_s3_bucket" {
  description = "S3 bucket for Lambda deployment package"
  type        = string
}

variable "lambda_s3_key" {
  description = "S3 key for Lambda deployment package"
  type        = string
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_VPC_with_IPv6_CIDR_blocks[VPC with IPv6 CIDR blocks]
    Amazon_ECS_with_Fargate[ECS with Fargate]
    Amazon_RDS_with_IPv6_support[(RDS with IPv6 support)]
    Amazon_SQS_for_decoupling_services[SQS for decoupling services]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_VPC_with_IPv6_CIDR_blocks
    Amazon_VPC_with_IPv6_CIDR_blocks --> Amazon_ECS_with_Fargate
    Amazon_ECS_with_Fargate --> Amazon_RDS_with_IPv6_support
    Amazon_ECS_with_Fargate --> Amazon_SQS_for_decoupling_services
    Amazon_ECS_with_Fargate -->|metrics| Amazon_CloudWatch"
}

