resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index}" })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index}" })
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-lambda-sg" })
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rds-sg" })

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = var.db_allocated_storage
  instance_class      = var.db_instance_class
  engine             = var.db_engine
  engine_version      = var.db_engine_version
  db_name            = var.db_name
  username           = var.db_username
  password           = var.db_password
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  publicly_accessible = false
  skip_final_snapshot = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rds" })
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${local.name_prefix}-api"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_code.bucket
  s3_key        = aws_s3_bucket_object.lambda_code.key
  environment {
    DB_HOST = aws_db_instance.rds_instance.address
    DB_USER = var.db_username
    DB_PASS = var.db_password
  }
  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${local.name_prefix}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${local.name_prefix}-api"
  description = "API for ${local.name_prefix}"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.api_lambda.invoke_arn
}

resource "aws_cloudwatch_log_group" "api_logs" {
  name = "/aws/api_gateway/${aws_api_gateway_rest_api.api.id}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_sqs_queue" "queue" {
  name = "${local.name_prefix}-queue"
  tags = local.common_tags
}

resource "aws_xray_daemon" "daemon" {
  name = "${local.name_prefix}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_deployment.api.invoke_url
  description = "The endpoint of the API Gateway"
}",
