    AWS_Direct_Connect --> Amazon_ECS
    AWS_Direct_Connect --> AWS_Lambda
    Amazon_Route_53 --> Amazon_ECS
    Amazon_Route_53 --> AWS_Lambda
    Amazon_ECS --> Amazon_RDS
