variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "db_instance_type" {
  description = "Instance type for Aurora Serverless"
  default     = "db.serverless"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "my_lambda_function"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.private_subnet_cidrs, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_sg"
  description = "Security group for Lambda function"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "alb_sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = false

  tags = {
    Name = "my-alb"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  environment {
    key = "value"
  }

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_exec.name
}

resource "aws_rds_cluster" "aurora_serverless" {
  cluster_identifier      = "aurora-serverless-cluster"
  engine                 = "aurora"
  engine_mode            = "serverless"
  master_username        = "admin"
  master_password        = "password"
  database_name          = "mydb"
  skip_final_snapshot    = true
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "aurora-serverless-cluster"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my_sns_topic"

  tags = {
    Name = "my_sns_topic"
  }
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name              = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "lambda-log-group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "alb_dns_name" {
  description = "DNS name of the Application Load Balancer"
  value       = aws_lb.application_load_balancer.dns_name
}

output "aurora_cluster_endpoint" {
  description = "Endpoint of the Aurora Serverless cluster"
  value       = aws_rds_cluster.aurora_serverless.endpoint
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    AWS_Lambda[Lambda]
    Aurora_Serverless[Aurora Serverless]
    Amazon_Aurora_Serverless[(Aurora Serverless)]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Application_Load_Balancer
    Application_Load_Balancer --> AWS_Lambda
    Application_Load_Balancer --> Aurora_Serverless
    AWS_Lambda --> Amazon_Aurora_Serverless
    Aurora_Serverless --> Amazon_Aurora_Serverless
    AWS_Lambda --> Amazon_SNS
    Aurora_Serverless --> Amazon_SNS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Aurora_Serverless -->|metrics| Amazon_CloudWatch
    Aurora_Serverless -->|metrics| AWS_X_Ray"
}

