resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
    Environment = local.environment
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-${count.index}"
    Environment = local.environment
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${local.name_prefix}-private-${count.index}"
    Environment = local.environment
  }
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-api-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-api-sg"
    Environment = local.environment
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-rds-sg"

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.api_sg.id]
  }

  tags = {
    Name = "${local.name_prefix}-rds-sg"
    Environment = local.environment
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = var.rds_allocated_storage
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = var.rds_engine_version
  db_name = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  skip_final_snapshot = true

  tags = {
    Name = "${local.name_prefix}-rds"
    Environment = local.environment
  }
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id = "${local.name_prefix}-redis"
  engine = "redis"
  node_type = var.redis_node_type
  num_cache_nodes = var.redis_node_count
  parameter_group_name = "default.redis3.2"
  security_group_ids = [aws_security_group.api_sg.id]

  tags = {
    Name = "${local.name_prefix}-redis"
    Environment = local.environment
  }
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${local.name_prefix}-api-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = var.lambda_s3_bucket
  s3_key = var.lambda_s3_key

  tags = {
    Name = "${local.name_prefix}-api-lambda"
    Environment = local.environment
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${local.name_prefix}-api"
  description = "API for ${local.name_prefix}"

  tags = {
    Name = "${local.name_prefix}-api"
    Environment = local.environment
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "v1"

  tags = {
    Name = "${local.name_prefix}-api-resource"
    Environment = local.environment
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    uri = aws_lambda_function.api_lambda.invoke_arn
    http_method = "POST"
  }

  tags = {
    Name = "${local.name_prefix}-api-method"
    Environment = local.environment
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "apiOrigin"
  }

  enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD", "OPTIONS"]
  }

  tags = {
    Name = "${local.name_prefix}-cdn"
    Environment = local.environment
  }
}

resource "aws_wafv2_web_acl" "web_acl" {
  name        = "${local.name_prefix}-web-acl"
  scope       = "REGIONAL"
  default_action {
    allow {}
  }

  rule {
    name     = "RateLimitRule"
    priority = 1
    action {
      block {}
    }
    statement {
      rate_based_statement {
        limit              = 1000
        aggregate_key_type = "IP"
        scope_down_statement {
          byte_match_statement {
            search_string = "bad-bot"
            field_to_match {
              uri_path {}
            }
            text_transformations {
              priority = 0
              type     = "NONE"
            }
          }
        }
      }
    }
  }

  tags = {
    Name = "${local.name_prefix}-web-acl"
    Environment = local.environment
  }
}

resource "aws_sqs_queue" "queue" {
  name = "${local.name_prefix}-queue"

  tags = {
    Name = "${local.name_prefix}-queue"
    Environment = local.environment
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"

  tags = {
    Name = "${local.name_prefix}-log-group"
    Environment = local.environment
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${local.name_prefix}-xray-daemon"

  tags = {
    Name = "${local.name_prefix}-xray-daemon"
    Environment = local.environment
  }
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "redis_endpoint" {
  value = aws_elasticache_cluster.redis.configuration_endpoint
