resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-gateway-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-api-gateway-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-ecs-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    security_groups = [aws_security_group.api_gateway_sg.id]
  }

  tags = {
    Name = "${var.environment}-ecs-sg"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-rds-sg"

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = 20
  identifier = "${var.environment}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = "14.1"
  db_name = var.db_name
  username = var.db_username
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "${var.environment}-rds-instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.environment}-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = aws_s3_bucket.lambda_bucket.bucket
  s3_key = "lambda.zip"

  tags = {
    Name = "${var.environment}-lambda"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${var.environment}-api"
  description = "API for ${var.environment}"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "myresource"

  tags = {
    Name = "${var.environment}-api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.environment}-api-method"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "APIGateway"

    custom_origin_config {
      http_port = 80
      https_port = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "APIGateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "${var.environment}-cloudfront"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "${var.environment}-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "${var.environment}-topic"

  tags = {
    Name = "${var.environment}-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "${var.environment}-log-group"

  tags = {
    Name = "${var.environment}-cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

resource "aws_securityhub_account" "security_hub" {}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type = string
  default = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)."
  type = string
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC."
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of public subnet CIDR blocks."
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of private subnet CIDR blocks."
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets."
  type = number
  default = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets."
  type = number
  default = 2
}

variable "rds_instance_class" {
  description = "RDS instance class."
  type = string
  default = "db.t3.micro"
}

variable "db_name" {
  description = "Database name."
  type = string
  default = "mydb"
}

variable "db_username" {
  description = "Database username."
  type = string
  default = "admin"
}

variable "rds_password" {
  description = "Password for the database in the RDS instance."
  type = string
}

variable "lambda_bucket" {
  description = "S3 bucket for Lambda deployment."
  type = string
}

resource "aws_s3_bucket" "lambda_bucket" {
  bucket = var.lambda_bucket

  tags = {
    Name = "${var.environment}-lambda-bucket"
  }
