  "terraform": "locals {
  environment = var.environment
  common_tags = {
    Name        = "${var.environment}-app"
    Environment = var.environment
  }
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

# Public Subnet
resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

# Private Subnet
resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

# Security Group for API Gateway
resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-api-gateway-sg"
  tags = local.common_tags
}

# Security Group for Application Load Balancer
resource "aws_security_group" "alb" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-alb-sg"
  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-rds-sg"
  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.alb.id]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

# RDS Instance
resource "aws_db_instance" "rds_instance" {
  allocated_storage = var.rds_allocated_storage
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = var.rds_engine_version
  db_name = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags = local.common_tags
}

# Lambda Function
resource "aws_lambda_function" "my_lambda" {
  function_name = "${local.environment}-my-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  source_code_hash = filebase64sha256("lambda.zip")
  environment {
    variables = {
      DB_HOST = aws_db_instance.rds_instance.endpoint
    }
  }
  tags = local.common_tags
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_exec" {
  name = "${local.environment}-lambda-exec-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# API Gateway
resource "aws_api_gateway_rest_api" "api" {
  name = "${local.environment}-api"
  description = "API for ${local.environment} environment"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "myresource"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

# Application Load Balancer
resource "aws_lb" "app_lb" {
  name = "${local.environment}-app-lb"
  internal = false
  load_balancer_type = "application"
  security_groups = [aws_security_group.alb.id]
  subnets = aws_subnet.public[*].id
  enable_deletion_protection = false
  tags = local.common_tags
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_lb.app_lb.dns_name
    origin_id = "myALB"
    custom_origin_config {
      http_port = 80
      https_port = 443
      origin_protocol_policy = "http-only"
    }
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "myALB"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD", "OPTIONS"]
    forwarded_values {
      query_string = false
    }
  }
  tags = local.common_tags
}

# SNS Topic
resource "aws_sns_topic" "notifications" {
  name = "${local.environment}-notifications"
  display_name = "Notifications for ${local.environment}"
  tags = local.common_tags
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

# X-Ray Daemon
resource "aws_xray_daemon" "daemon" {
  name = "${local.environment}-xray-daemon"
  image = "amazon/aws-xray-daemon"
  desired_count = 1
  task_definition = aws_ecs_task_definition.my_task_definition.arn
}

# Outputs
output "api_gateway_url" {
  value = aws_api_gateway_deployment.api.invoke_url
}

output "cloudfront_url" {
  value = aws_cloudfront_distribution.cdn.domain_name
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    Application_Load_Balancer --> AWS_Lambda
    Application_Load_Balancer --> Amazon_ECS
    AWS_Lambda --> Amazon_RDS
    Amazon_ECS --> Amazon_RDS
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS --> Amazon_SNS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray"
}

