          "unit": "data served"
        },
        {
          "service": "Amazon API Gateway",
          "monthly_usd": 50.0,
          "unit": "API calls"
        },
        {
          "service": "AWS Lambda",
          "monthly_usd": 30.0,
          "unit": "requests"
        },
        {
          "service": "Amazon ECS",
          "monthly_usd": 40.0,
          "unit": "container hours"
        },
        {
          "service": "Amazon DynamoDB",
          "monthly_usd": 25.0,
          "unit": "read/write capacity"
        },
        {
          "service": "Amazon RDS",
          "monthly_usd": 40.0,
          "unit": "instance hours"
        },
        {
          "service": "Amazon SQS",
          "monthly_usd": 5.0,
          "unit": "number of requests"
        },
        {
          "service": "Amazon CloudWatch",
          "monthly_usd": 10.0,
          "unit": "metrics and logs"
        }
      ],
      "total_monthly_usd": 220.0,
      "spike_estimate_usd": 300.0,
      "optimization": "Consider using AWS Lambda's provisioned concurrency for predictable workloads to avoid cold start latency."
    },
    "terraform": "resource \"aws_vpc\" \"main\" { ... }\nresource \"aws_security_group\" \"allow_http\" { ... }\nresource \"aws_cloudfront_distribution\" \"cdn\" { ... }\nresource \"aws_api_gateway_rest_api\" \"api\" { ... }\nresource \"aws_lambda_function\" \"function\" { ... }\nresource \"aws_ecs_cluster\" \"cluster\" { ... }\nresource \"aws_dynamodb_table\" \"table\" { ... }\nresource \"aws_db_instance\" \"db\" { ... }\nresource \"aws_sqs_queue\" \"queue\" { ... }\nresource \"aws_cloudwatch_log_group\" \"logs\" { ... }",
    "diagram": "graph TD\n    User([User])\n    User-->API_Gateway([Amazon API Gateway])\n    API_Gateway-->Lambda([AWS Lambda])\n    API_Gateway-->Load_Balancer([Application Load Balancer])\n    Load_Balancer-->ECS([Amazon ECS])\n    Lambda-->DynamoDB([Amazon DynamoDB])\n    Lambda-->RDS([Amazon RDS])\n    Load_Balancer-->SQS([Amazon SQS])\n    Lambda-->CloudWatch([Amazon CloudWatch])"
  }
}

