provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Owner       = "DevOps"
      Environment = "Production"
    }
  }
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = "my_lambda_bucket"
  s3_key        = "lambda.zip"

  environment {
    variables = {
      ENV_VAR = "value"
    }
  }

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = "my_api"
  description = "My API Gateway"

  tags = {
    Name = "my_api"
  }
}

resource "aws_api_gateway_resource" "my_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "my_resource"
  }
}

resource "aws_api_gateway_method" "my_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type             = "AWS_PROXY"
    integration_http_method = "POST"
    uri              = aws_lambda_function.my_lambda.invoke_arn
  }
}

resource "aws_ecs_cluster" "my_cluster" {
  name = "my_ecs_cluster"

  tags = {
    Name = "my_ecs_cluster"
  }
}

resource "aws_rds_cluster" "my_rds" {
  cluster_identifier      = "my-rds-cluster"
  engine                 = "aurora"
  master_username        = "admin"
  master_password        = "password"
  skip_final_snapshot    = true
  database_name          = "mydatabase"

  tags = {
    Name = "my_rds_cluster"
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "my_dynamodb_table"
  }
}

resource "aws_sns_topic" "my_topic" {
  name = "my_sns_topic"

  tags = {
    Name = "my_sns_topic"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_sqs_queue"

  tags = {
    Name = "my_sqs_queue"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/my_lambda_function"

  retention_in_days = 14

  tags = {
    Name = "my_log_group"
  }
}

resource "aws_xray_daemon" "my_xray" {
  name = "my_xray_daemon"

  tags = {
    Name = "my_xray_daemon"
  }
}

resource "aws_devops_guru_resource_collection" "my_devops_guru" {
  resource_collection {
    cloud_resource {
      resource_type = "AWS::Lambda::Function"
      resource_id   = aws_lambda_function.my_lambda.id
    }
  }

  tags = {
    Name = "my_devops_guru"
  }
}

output "api_gateway_url" {
  value = "${aws_api_gateway_deployment.my_api_deployment.invoke_url}"
}

data "aws_availability_zones" "available" {}",
