resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index}" })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index}" })
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-api-sg"
  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-lambda-sg"
  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    security_groups = [aws_security_group.api_sg.id]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.name_prefix}-rds-sg"
  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.api_sg.id]
  }
  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = local.common_tags
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = var.rds_allocated_storage
  identifier = "${local.name_prefix}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = var.rds_engine_version
  db_name = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  tags = local.common_tags
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${local.name_prefix}-api-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_role.arn
  s3_bucket = aws_s3_bucket.lambda_code.bucket
  s3_key = aws_s3_bucket_object.lambda_code.key
  environment {
    DB_HOST = aws_db_instance.rds_instance.endpoint
    DB_USER = var.rds_username
    DB_PASS = var.rds_password
  }
  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${local.name_prefix}-api"
  description = "API for ${var.project_name}"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "api_resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "v1"
}

resource "aws_api_gateway_method" "api_method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.api_resource.id
  http_method = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "api_integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.api_resource.id
  http_method = aws_api_gateway_method.api_method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.api_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "apiOrigin"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = true
    }
  }
  tags = local.common_tags
}

resource "aws_sqs_queue" "queue" {
  name = "${local.name_prefix}-queue"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "xray" {
  name = "${local.name_prefix}-xray"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.invoke_url
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "cloudfront_domain" {
  value = aws_cloudfront_distribution.cdn.domain_name
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    AWS_Lambda[Lambda]
