resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private_subnet" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-api-gateway-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-api-gateway-sg"
  }
}

resource "aws_security_group" "fargate_sg" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-fargate-sg"

  ingress {
    from_port = 80
    to_port = 80
    protocol = "tcp"
    security_groups = [aws_security_group.api_gateway_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-fargate-sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = var.rds_allocated_storage
  identifier = "${var.environment}-rds"
  instance_class = var.rds_instance_class
  engine = "postgres"
  engine_version = "14.1"
  db_name = var.rds_db_name
  username = var.rds_username
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "${var.environment}-rds"
  }
}

resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.main.id
  name = "${var.environment}-rds-sg"

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    security_groups = [aws_security_group.fargate_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-rds-sg"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.environment}-dynamodb-table"
  }
}

resource "aws_sqs_queue" "main" {
  name = "${var.environment}-sqs-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

resource "aws_sns_topic" "main" {
  name = "${var.environment}-sns-topic"

  tags = {
    Name = "${var.environment}-sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "${var.environment}-log-group"

  retention_in_days = 14

  tags = {
    Name = "${var.environment}-log-group"
  }
}

resource "aws_api_gateway_rest_api" "main" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment}"

  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "root" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "v1"

  tags = {
    Name = "${var.environment}-api-v1"
  }
}

resource "aws_api_gateway_method" "get" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.root.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "${var.environment}-api-get"
  }
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway_rest_api.main.execution_arn
    origin_id   = "api_gateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true
  default_cache_behavior {
    target_origin_id = "api_gateway"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "${var.environment}-cloudfront"
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${var.environment}-ecs-cluster"

  tags = {
    Name = "${var.environment}-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.environment}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.fargate_cpu
  memory                  = var.fargate_memory

  container_definitions = jsonencode([
    {
      name      = "${var.environment}-container"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])

  tags = {
    Name = "${var.environment}-ecs-task"
  }
}

resource "aws_ecs_service" "main" {
  name            = "${var.environment}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private_subnet[*].id
    security_groups  = [aws_security_group.fargate_sg.id]
    assign_public_ip = false
  }

  tags = {
    Name = "${var.environment}-ecs-service"
  }
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.main.execution_arn
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)"
  type        = string
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets"
  type        = number
  default     = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets"
  type        = number
  default     = 2
}

variable "rds_allocated_storage" {
  description = "Allocated storage for RDS instance"
  type        = number
  default     = 20
}

variable "rds_instance_class" {
  description = "Instance class for RDS"
  type        = string
  default     = "db.t3.micro"
}

variable "rds_db_name" {
  description = "Database name for RDS"
  type        = string
  default     = "mydatabase"
}

variable "rds_username" {
  description = "Username for RDS"
  type        = string
  default     = "awsadmin"
}

variable "rds_password" {
  description = "Password for RDS"
  type        = string
}

variable "fargate_cpu" {
  description = "CPU units for Fargate task"
  type        = string
  default     = "256"
}

variable "fargate_memory" {
  description = "Memory for Fargate task"
  type        = string
  default     = "512"
}

variable "container_image" {
  description = "Container image for Fargate task"
  type        = string
}

variable "desired_count" {
  description = "Desired count of Fargate tasks"
  type        = number
  default     = 1
