provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Owner       = "Your Name"
      Environment = var.environment
    }
  }
}

# VPC with public and private subnets
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = var.public_subnet_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count      = var.private_subnet_count
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

# Security Groups
resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-lambda-sg"
  }
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.environment}-ecs-sg"
  }
}

# Amazon RDS
resource "aws_db_instance" "default" {
  identifier         = "${var.environment}-rds"
  engine             = "mysql"
  instance_class     = var.db_instance_class
  allocated_storage   = var.db_allocated_storage
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "${var.environment}-rds"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.environment}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${var.environment}-db-subnet-group"
  }
}

# Amazon DynamoDB
resource "aws_dynamodb_table" "default" {
  name         = "${var.environment}-dynamodb"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "${var.environment}-dynamodb"
  }
}

# Amazon SNS
resource "aws_sns_topic" "default" {
  name = "${var.environment}-sns-topic"

  tags = {
    Name = "${var.environment}-sns-topic"
  }
}

# Amazon SQS
resource "aws_sqs_queue" "default" {
  name = "${var.environment}-sqs-queue"

  tags = {
    Name = "${var.environment}-sqs-queue"
  }
}

# AWS Lambda
resource "aws_lambda_function" "default" {
  function_name = "${var.environment}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key

  tags = {
    Name = "${var.environment}-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "${var.environment}-lambda-exec-role"
  }
}

# Amazon API Gateway
resource "aws_api_gateway_rest_api" "default" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment}"

  tags = {
    Name = "${var.environment}-api"
  }
}

# Amazon CloudFront
resource "aws_cloudfront_distribution" "default" {
  origin {
    domain_name = aws_api_gateway_rest_api.default.execution_arn
    origin_id   = "apiGatewayOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  tags = {
    Name = "${var.environment}-cloudfront"
  }
}

# Amazon CloudWatch
resource "aws_cloudwatch_log_group" "default" {
  name = "${var.environment}-log-group"

  tags = {
    Name = "${var.environment}-log-group"
  }
}

# AWS X-Ray
resource "aws_xray_daemon" "default" {
  name = "${var.environment}-xray-daemon"

  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

# AWS DevOps Guru
resource "aws_devops_guru_service_integration" "default" {
  service_integration_type = "AWS_SERVICE"
  tags = {
    Name = "${var.environment}-devops-guru"
  }
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.default.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.default.name
}

output "sns_topic_arn" {
  value = aws_sns_topic.default.arn
}

output "sqs_queue_url" {
  value = aws_sqs_queue.default.id
}

output "lambda_function_name" {
  value = aws_lambda_function.default.function_name
}

output "api_gateway_id" {
  value = aws_api_gateway_rest_api.default.id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.default.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_SNS[SNS]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    Amazon_DevOps_Guru[DevOps Guru]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_DynamoDB
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_DynamoDB
    AWS_Lambda --> Amazon_SNS
    AWS_Lambda --> Amazon_SQS
    Amazon_ECS --> Amazon_SNS
    Amazon_ECS --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_X_Ray
    AWS_Lambda -->|metrics| Amazon_DevOps_Guru
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_X_Ray
    Amazon_ECS -->|metrics| Amazon_DevOps_Guru"
}

