provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Owner       = "Your Name"
      Environment = "Production"
    }
  }
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster."
  type        = string
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  type        = string
  default     = "my_lambda_function"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda-sg"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = aws_s3_bucket_object.lambda_object.key

  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "my_api"
  description = "API for my application"

  tags = {
    Name = "my_api"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = {
    Name = "v1_resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "my_cdn"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "my_ecs_cluster"

  tags = {
    Name = "my_ecs_cluster"
  }
}

resource "aws_ecs_task_definition" "task" {
  family                   = "my_task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "my_container"
    image     = "my_image:latest"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "my_task"
  }
}

resource "aws_rds_cluster" "db" {
  cluster_identifier      = "my-db-cluster"
  engine                 = "aurora-postgresql"
  master_username        = "admin"
  master_password        = var.rds_password
  skip_final_snapshot    = true

  tags = {
    Name = "my_db_cluster"
  }
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "my-redis-cluster"
  engine               = "redis"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis3.2"

  tags = {
    Name = "my_redis_cluster"
  }
}

resource "aws_sns_topic" "sns" {
  name = "my_sns_topic"

  tags = {
    Name = "my_sns_topic"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"

  retention_in_days = 14

  tags = {
    Name = "my_log_group"
  }
}

resource "aws_cloudwatch_synthetics_canary" "canary" {
  name              = "my_canary"
  runtime_version   = "syn-nodejs-puppeteer-3.0"
  handler           = "index.handler"
  s3_bucket         = aws_s3_bucket.canary_bucket.bucket
  s3_key            = aws_s3_bucket_object.canary_object.key
  frequency         = 60
  success_retention_period = 30
  failure_retention_period = 30

  tags = {
    Name = "my_canary"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "my_xray_daemon"

  tags = {
    Name = "my_xray_daemon"
  }
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.cdn.id
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.ecs_cluster.name
}

output "rds_endpoint" {
  value = aws_rds_cluster.db.endpoint
}

output "redis_endpoint" {
  value = aws_elasticache_cluster.redis.configuration_endpoint
}

output "sns_topic_arn" {
  value = aws_sns_topic.sns.arn
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    Application_Load_Balancer[Application Load Balancer]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    Amazon_ElastiCache[(ElastiCache)]
    Amazon_SNS[SNS]
    Amazon_CloudWatch[CloudWatch]
    Amazon_CloudWatch_Synthetics[CloudWatch Synthetics]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_CloudFront --> Application_Load_Balancer
    Amazon_API_Gateway --> AWS_Lambda
    Amazon_API_Gateway --> Amazon_ECS
    Application_Load_Balancer --> AWS_Lambda
    Application_Load_Balancer --> Amazon_ECS
    AWS_Lambda --> Amazon_RDS
    AWS_Lambda --> Amazon_ElastiCache
    Amazon_ECS --> Amazon_RDS
    Amazon_ECS --> Amazon_ElastiCache
    AWS_Lambda --> Amazon_SNS
    Amazon_ECS --> Amazon_SNS
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| Amazon_CloudWatch_Synthetics
