resource "aws_api_gateway_rest_api" "api" {
  name        = "MyAPI"
  description = "API for my application"

  tags = {
    Name = "MyAPI"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"

  tags = {
    Name = "v1-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "GET-method"
  }
}

resource "aws_lambda_function" "lambda" {
  function_name = "MyLambdaFunction"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.data_bucket.id
  s3_key        = "lambda.zip"

  tags = {
    Name = "MyLambdaFunction"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "lambda-execution-role"
  }
}

resource "aws_ecs_cluster" "ecs" {
  name = "my-ecs-cluster"

  tags = {
    Name = "my-ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "task" {
  family                   = "my-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([
    {
      name      = "my-container"
      image     = "my-image:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort     = 80
          protocol     = "tcp"
        },
      ]
    },
  ])

  tags = {
    Name = "my-task-definition"
  }
}

resource "aws_ecs_service" "service" {
  name            = "my-service"
  cluster         = aws_ecs_cluster.ecs.id
  task_definition = aws_ecs_task_definition.task.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.allow_http.id]
    assign_public_ip = false
  }

  tags = {
    Name = "my-ecs-service"
  }
}

resource "aws_emr_cluster" "emr" {
  name          = "MyEMRCluster"
  release_label = "emr-6.3.0"
  applications  = ["Hadoop", "Spark"]

  ec2_attributes {
    subnet_id = aws_subnet.private[0].id
  }

  tags = {
    Name = "MyEMRCluster"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose" {
  name        = "my-firehose"
  destination = "s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.data_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn
  }

  tags = {
    Name = "my-firehose"
  }
}

resource "aws_iam_role" "firehose_role" {
  name = "firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "firehose-role"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/MyLambdaFunction"

  tags = {
    Name = "MyLambdaFunction-LogGroup"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "s3_bucket_name" {
  description = "S3 bucket name"
  value       = aws_s3_bucket.data_bucket.id
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.cdn.id
}

output "api_gateway_id" {
  description = "API Gateway ID"
  value       = aws_api_gateway_rest_api.api.id
}

output "ecs_cluster_id" {
  description = "ECS Cluster ID"
  value       = aws_ecs_cluster.ecs.id
}

output "emr_cluster_id" {
  description = "EMR Cluster ID"
  value       = aws_emr_cluster.emr.id
