  "terraform": "terraform {
  required_version = ">= 1.15.4"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }
}

provider "aws" {
  region = var.region
  profile = "default"

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

data "aws_region" "current" {}

# VPC Configuration
module "vpc" {
  source = "terraform-aws-modules/vpc/aws"

  azs                  = data.aws_availability_zones.all.names
  private_subnets     = var.private_subnets
  public_subnets      = var.public_subnets
  enable_dns_hostnames = true
  enable_dns_support   = true
  enable_nat_gateway    = true
  single_nat_gateway    = true

  tags = {
    Name = "${var.name}-vpc"
  }
}

# SNS Topic
resource "aws_sns_topic" "cost_alerts" {
  name = "${var.name}-cost-alerts"

  tags = {
    Name        = "${var.name}-cost-alerts"
    Environment = var.environment
  }
}

# Cost Explorer
resource "aws_cost_explorer_report" "monthly_report" {
  report_name = "${var.name}-monthly-cost-report"
  time_unit   = "MONTHLY"

  format_version = "1.0"
  compression    = "GZIP"

  s3_destination {
    output_path = "s3://${var.s3_bucket_name}/cost-reports/"
    format      = "CSV"
  }

  tags = {
    Name        = "${var.name}-monthly-cost-report"
    Environment = var.environment
  }
}

# Cost Anomaly Detection Alert
resource "aws_cost_anomaly_detection_alert" "cost_anomaly_alert" {
  alert_name = "${var.name}-cost-anomaly-alert"
  alert_type = "COST"

  threshold = var.anomaly_detection_threshold

  sns_topic_arn = aws_sns_topic.cost_alerts.arn

  tags = {
    Name        = "${var.name}-cost-anomaly-alert"
    Environment = var.environment
  }
}

# AWS Budgets
resource "aws_budgets_budget" "monthly_budget" {
  budget {
    budget_type = "COST"
    budget_limit {
      amount = var.budget_amount
      unit   = "USD"
    }
    time_unit = "MONTHLY"
    cost_filters = {
      Service = ["Amazon EC2"]
    }
  }

  notifications {
    notification {
      notification_type = "ACTUAL"
      comparison_operator = "GREATER_THAN"
      threshold = var.budget_threshold
      threshold_type = "PERCENTAGE"
      subscribers {
        address = aws_sns_topic.cost_alerts.arn
        subscription_type = "SNS"
      }
    }
  }

  tags = {
    Name        = "${var.name}-monthly-budget"
    Environment = var.environment
  }
}

# Outputs
output "sns_topic_arn" {
  description = "ARN of the SNS topic for cost alerts"
  value       = aws_sns_topic.cost_alerts.arn
}

output "monthly_budget_id" {
  description = "ID of the monthly budget"
  value       = aws_budgets_budget.monthly_budget.id
}

output "cost_anomaly_alert_id" {
  description = "ID of the cost anomaly detection alert"
  value       = aws_cost_anomaly_detection_alert.cost_anomaly_alert.id
}

# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name for resources"
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment tag"
  type        = string
  default     = "production"
}

variable "private_subnets" {
  description = "List of private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "public_subnets" {
  description = "List of public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

variable "s3_bucket_name" {
  description = "S3 bucket name for cost reports"
  type        = string
}

variable "anomaly_detection_threshold" {
  description = "Threshold for cost anomaly detection"
  type        = number
  default     = 100
}

variable "budget_amount" {
  description = "Monthly budget amount"
  type        = number
  default     = 500
}

variable "budget_threshold" {
  description = "Threshold percentage for budget notifications"
  type        = number
  default     = 80
}",
