  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_internet_gateway\" \"igw\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"my-api\"\n}\n\nresource \"aws_lambda_function\" \"my_function\" {\n  function_name = \"my_function\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_db_instance\" \"default\" {\n  allocated_storage    = 20\n  engine             = \"mysql\"\n  engine_version     = \"8.0\"\n  instance_class     = \"db.t3.micro\"\n  name               = \"mydb\"\n  username           = \"admin\"\n  password           = \"password\"\n  skip_final_snapshot = true\n  vpc_security_group_ids = [aws_security_group.allow_http.id]\n}\n\nresource \"aws_dynamodb_table\" \"my_table\" {\n  name           = \"my_table\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sqs_queue\" \"my_queue\" {\n  name = \"my_queue\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Requests| API_Gateway([API Gateway])\n    API_Gateway -->|Routes| Lambda([AWS Lambda])\n    Lambda -->|Reads/Writes| RDS[(Amazon RDS)]\n    Lambda -->|Reads/Writes| DynamoDB[(Amazon DynamoDB)]\n    Lambda -->|Sends Messages| SQS[(Amazon SQS)]\n    Lambda -->|Logs| CloudWatch([CloudWatch])\n    API_Gateway -->|Load Balancing| ELB([Elastic Load Balancer])\n    CloudFront([CloudFront]) -->|Delivers| User"
}

