resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

resource "aws_security_group" "alb" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "lambda" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_rds_cluster" "default" {
  cluster_identifier      = "${var.environment}-rds-cluster"
  engine                 = "aurora-postgresql"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true
  tags                   = local.common_tags
}

resource "aws_rds_cluster_instance" "default" {
  count              = var.db_instance_count
  cluster_identifier = aws_rds_cluster.default.id
  instance_class    = var.db_instance_class
  engine            = aws_rds_cluster.default.engine
  tags              = local.common_tags
}

resource "aws_dynamodb_table" "default" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags     = local.common_tags
}

resource "aws_sqs_queue" "default" {
  name = "${var.environment}-sqs-queue"
  tags = local.common_tags
}

resource "aws_sns_topic" "default" {
  name = "${var.environment}-sns-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "default" {
  name = "${var.environment}-log-group"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_lambda_function" "default" {
  function_name = "${var.environment}-lambda-function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_role.arn
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  tags          = local.common_tags
}

resource "aws_iam_role" "lambda_role" {
  name = "${var.environment}-lambda-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_api_gateway_rest_api" "default" {
  name        = "${var.environment}-api"
  description = "API for ${var.project_name}"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "default" {
  rest_api_id = aws_api_gateway_rest_api.default.id
  parent_id   = aws_api_gateway_rest_api.default.root_resource_id
  path_part   = "v1"
}

resource "aws_api_gateway_method" "default" {
  rest_api_id   = aws_api_gateway_rest_api.default.id
  resource_id   = aws_api_gateway_resource.default.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_cloudfront_distribution" "default" {
  origin {
    domain_name = aws_s3_bucket.default.bucket_regional_domain_name
    origin_id   = "S3Origin"
  }

  enabled = true
  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD"]
    cached_methods = ["GET", "HEAD"]
  }

  tags = local.common_tags
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.default.invoke_url
}

output "rds_endpoint" {
  value = aws_rds_cluster.default.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.default.name
