        },
        {
          "service": "Amazon API Gateway",
          "monthly_usd": 150.0,
          "unit": "1M calls"
        },
        {
          "service": "Amazon DynamoDB",
          "monthly_usd": 20.0,
          "unit": "storage and read/write capacity units"
        },
        {
          "service": "Amazon CloudFront",
          "monthly_usd": 30.0,
          "unit": "data transfer and requests"
        },
        {
          "service": "Amazon SNS",
          "monthly_usd": 5.0,
          "unit": "notifications"
        }
      ],
