  },
  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_1\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_2\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"news_aggregator\" {\n  function_name = \"newsAggregator\"\n  runtime      = \"nodejs14.x\"\n  handler      = \"index.handler\"\n  role         = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"NewsAggregatorAPI\"\n}\n\nresource \"aws_dynamodb_table\" \"articles\" {\n  name         = \"Articles\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"news-cache\"\n  engine     = \"redis\"\n  node_type  = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}\n\nresource \"aws_sqs_queue\" \"queue\" {\n  name = \"NewsQueue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"newsAggregatorLogGroup\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Requests News| API[API Gateway]\n    API -->|Triggers| Lambda[AWS Lambda]\n    Lambda -->|Fetches Data| DB[Amazon DynamoDB]\n    Lambda -->|Caches Responses| Cache[Amazon ElastiCache]\n    Cache -->|Provides Cache| User\n    DB -->|Returns Articles| Lambda\n    Lambda -->|Sends Messages| Queue[Amazon SQS]\n    Queue -->|Decouples| Processing[Processing Service]\n    Processing -->|Logs Metrics| Monitor[Amazon CloudWatch]\n    API -->|Distributes Load| ELB[Elastic Load Balancer]\n    User -->|Receives Content| CloudFront[Amazon CloudFront]"
