{
  "scenario_summary": "The client needs a cost-effective AWS architecture for a hotel booking platform that can handle 100,000 messages per day.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon API Gateway",
        "Application Load Balancer"
      ],
