    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"hotel_booking\" {\n  function_name = \"hotelBookingFunction\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  role = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"hotel_api\" {\n  name = \"HotelBookingAPI\"\n}\n\nresource \"aws_dynamodb_table\" \"bookings\" {\n  name         = \"Bookings\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"bookingId\"\n    type = \"S\"\n  }\n  hash_key = \"bookingId\"\n}\n\nresource \"aws_sqs_queue\" \"booking_queue\" {\n  name = \"BookingQueue\"\n}",
