variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type for HPC."
  default     = "c5n.18xlarge"
}

variable "key_name" {
  description = "Name of the EC2 key pair."
  default     = "my-key-pair"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2-security-group"
  vpc_id      = aws_vpc.main.id
  description = "Allow SSH and HTTP access to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-security-group"
  }
}

resource "aws_ec2_instance" "hpc_instance" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = aws_subnet.private[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "hpc-instance"
  }
}

data "aws_ami" "latest" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "my-hpc-data-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name        = "HPC Data Bucket"
    Environment = "Production"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_efs_file_system" "efs" {
  creation_token = "hpc-efs"
  performance_mode = "generalPurpose"

  tags = {
    Name = "HPC EFS"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "hpc-batch-env"
  type                     = "MANAGED"

  compute_resources {
    type              = "EC2"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.ec2_sg.id]
  }

  service_role = aws_iam_role.batch_service_role.arn
}

resource "aws_iam_role" "batch_service_role" {
  name = "batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })
}

resource "aws_transit_gateway" "tg" {
  description = "Transit Gateway for VPC connectivity"

  tags = {
    Name = "HPC Transit Gateway"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/batch/hpc-log-group"

  retention_in_days = 14

  tags = {
    Name = "HPC Batch Log Group"
  }
}

resource "aws_sqs_queue" "hpc_queue" {
  name = "hpc-queue"

  tags = {
    Name = "HPC SQS Queue"
  }
}

resource "aws_xray_daemon" "xray" {
  name = "xray-daemon"

  tags = {
    Name = "HPC X-Ray Daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "hpc_instance_id" {
  description = "HPC EC2 Instance ID"
  value       = aws_ec2_instance.hpc_instance.id
}

output "data_bucket_name" {
  description = "S3 Bucket for HPC data"
  value       = aws_s3_bucket.data_bucket.bucket
}

output "efs_id" {
  description = "EFS File System ID"
  value       = aws_efs_file_system.efs.id
}

output "batch_environment_name" {
  description = "Batch Compute Environment Name"
  value       = aws_batch_compute_environment.batch_env.compute_environment_name
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.hpc_queue.id
