provider "aws" {
  region  = var.aws_region
  profile = var.aws_profile

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

data "aws_region" "current" {}
data "aws_availability_zones" "all" {}

# VPC creation
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-vpc"
  })
}

# Public Subnet
resource "aws_subnet" "public" {
  count = length(data.aws_availability_zones.all.names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.all.names, count.index)

  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index}"
  })
}

# Private Subnet
resource "aws_subnet" "private" {
  count = length(data.aws_availability_zones.all.names)

  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.all.names, count.index)

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-igw"
  })
}

# Route Table for Public Subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-route-table"
  })
}

# Associate Public Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for API Gateway
resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-api-gateway-sg"
  })
}

# Security Group for Lambda
resource "aws_security_group" "lambda" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-lambda-sg"
  })
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda.id]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-rds-sg"
  })
}

# RDS Instance
module "rds" {
  source = "terraform-aws-modules/rds/aws"
  version = "2.20.0"

  name                 = "${var.environment}-postgres"
  engine               = "postgres"
  engine_version       = var.db_engine_version
  instance_class       = var.db_instance_class
  allocated_storage     = var.db_allocated_storage
  max_allocated_storage = var.db_max_allocated_storage
  storage_type         = var.db_storage_type
  username             = var.db_username
  password             = var.db_password
  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  skip_final_snapshot  = true
}

# DynamoDB Table
resource "aws_dynamodb_table" "main" {
  name         = "${var.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dynamodb-table"
  })
}

# SQS Queue
resource "aws_sqs_queue" "main" {
  name = "${var.environment}-sqs-queue"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-sqs-queue"
  })
}

# SNS Topic
resource "aws_sns_topic" "main" {
  name = "${var.environment}-sns-topic"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-sns-topic"
  })
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "main" {
  name = "${var.environment}-log-group"

  retention_in_days = 14

  tags = merge(local.common_tags, {
    Name = "${var.environment}-log-group"
  })
}

# Lambda Function
resource "aws_lambda_function" "main" {
  function_name = "${var.environment}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda.arn
  s3_bucket     = aws_s3_bucket.lambda_bucket.bucket
  s3_key        = aws_s3_bucket_object.lambda_object.key

  environment {
    variables = {
      DYNAMODB_TABLE = aws_dynamodb_table.main.name
      SQS_QUEUE_URL  = aws_sqs_queue.main.id
      SNS_TOPIC_ARN  = aws_sns_topic.main.arn
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-lambda"
  })
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway.rest_api.invoke_url
    origin_id   = "apiGateway"

    custom_origin_config {
      http_port              = 80
      https_port             = 443
      origin_protocol_policy = "https-only"
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiGateway"

    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-cloudfront"
  })
}

# API Gateway
resource "aws_api_gateway_rest_api" "main" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment}"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-api"
  })
}

# Transit Gateway
resource "aws_ec2_transit_gateway" "main" {
  description = "${var.environment}-transit-gateway"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-transit-gateway"
  })
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "rds_endpoint" {
  value = module.rds.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.main.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.main.arn
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
