provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "lambda-security-group"
  }
}

resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "rds-security-group"
  }
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.private_subnet.cidr_block]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.bucket_prefix
  s3_key        = "lambda/my_lambda.zip"
  environment {
    DATABASE_URL = aws_db_instance.rds_instance.endpoint
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Effect    = "Allow"
      Sid       = ""
    }]
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "my_api"
  description = "API for my application"
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "myresource"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.my_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"
  }
  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "my_cloudfront_distribution"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "my_ecs_cluster"
}

resource "aws_ecs_task_definition" "task" {
  family                   = "my_task"
  requires_compatibilities  = ["FARGATE"]
  network_mode             = "awsvpc"
  container_definitions    = jsonencode([{
    name      = "my_container"
    image     = "my_image:latest"
    memory    = "512"
    cpu       = "256"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort     = 80
      protocol     = "tcp"
    }]
  }])
}

resource "aws_ecs_service" "ecs_service" {
  name            = "my_service"
  cluster         = aws_ecs_cluster.ecs_cluster.id
  task_definition = aws_ecs_task_definition.task.arn
  desired_count   = 1
  launch_type     = "FARGATE"
  network_configuration {
    subnets          = [aws_subnet.private_subnet.id]
    security_groups  = [aws_security_group.lambda_sg.id]
    assign_public_ip = false
  }
}

resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/my_lambda"
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"
  image = "amazon/aws-xray-daemon"
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "api_gateway_url" {
  value = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_domain" {
  value = aws_cloudfront_distribution.cdn.domain_name
