  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private_subnet\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"app_function\" {\n  function_name = \"banking_app_function\"\n  runtime      = \"nodejs14.x\"\n  handler      = \"index.handler\"\n  role         = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"BankingAPI\"\n}\n\nresource \"aws_application_load_balancer\" \"main_lb\" {\n  name               = \"main-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.api_sg.id]\n  subnets            = [aws_subnet.public_subnet.id]\n}\n\nresource \"aws_rds_cluster\" \"aurora_db\" {\n  cluster_identifier = \"banking-aurora\"\n  engine            = \"aurora\"\n  master_username    = \"admin\"\n  master_password    = \"password\"\n  skip_final_snapshot = true\n}\n\nresource \"aws_dynamodb_table\" \"transactions\" {\n  name         = \"transactions\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"transaction_id\"\n    type = \"S\"\n  }\n  hash_key = \"transaction_id\"\n}\n\nresource \"aws_sqs_queue\" \"transaction_queue\" {\n  name = \"transactions_queue\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"api_logs\" {\n  name = \"/aws/api/gateway/banking\"\n  retention_in_days = 14\n}",
