    "spike_estimate_usd": 12.15,
    "optimization": "Switch to 1-year Reserved Instances for EC2/RDS/ElastiCache to save 30-40% on compute costs. Use S3 Intelligent-Tiering for infrequently accessed data."
  },
  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }
}

variable "region" {
  description = "AWS region"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "bucket_name" {
  description = "S3 bucket name for storage"
  default     = "my-unique-bucket-name"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "Main VPC"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block  = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block  = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Main IGW"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "Public Route Table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Lambda Security Group"
  }
}

resource "aws_security_group" "emr_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "EMR Security Group"
  }
}

resource "aws_security_group" "glue_sg" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Glue Security Group"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = var.bucket_name

  tags = {
    Name        = var.bucket_name
    Environment = "Production"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${var.region}.s3"
  route_table_ids = [aws_route_table.public.id]

  tags = {
    Name = "S3 VPC Endpoint"
  }
}

resource "aws_glue_catalog_database" "data_catalog" {
  name = "my_data_catalog"

  tags = {
    Name = "Glue Data Catalog"
  }
}

resource "aws_lambda_function" "transform_function" {
  function_name = "transform_function"
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  tags = {
    Name = "Lambda Transform Function"
  }
}

resource "aws_emr_cluster" "big_data_cluster" {
  name          = "BigDataCluster"
  release_label = "emr-6.3.0"
  applications  = ["Hadoop", "Spark"]

  ec2_attributes {
    subnet_id = aws_subnet.private[0].id
    emr_managed_master_security_group = aws_security_group.emr_sg.id
    emr_managed_slave_security_group = aws_security_group.emr_sg.id
  }

  tags = {
    Name = "EMR Cluster"
  }
}

resource "aws_kinesis_stream" "data_stream" {
  name        = "data_stream"
  shard_count = 1

  tags = {
    Name = "Kinesis Data Stream"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/transform_function"

  tags = {
    Name = "CloudWatch Log Group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "AWS X-Ray Daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "data_bucket_name" {
  description = "S3 bucket name for data storage"
  value       = aws_s3_bucket.data_bucket.bucket
}

output "lambda_function_name" {
  description = "Lambda function name"
  value       = aws_lambda_function.transform_function.function_name
}

output "emr_cluster_id" {
  description = "EMR Cluster ID"
  value       = aws_emr_cluster.big_data_cluster.id
}",
  "diagram": "graph TD
    User([User / Client])
    AWS_PrivateLink_for_secure_access_to_S3[PrivateLink for secure access to S3]
