  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"

  versioning {
    enabled = true
  }

  tags = {
    Name = "data-bucket"
    Environment = "production"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_lambda_function" "example" {
  function_name = "example_lambda"
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda.zip"
  handler       = "index.handler"
  runtime       = "nodejs14.x"

  environment {
    VARIABLE_NAME = "value"
  }

  tags = {
    Name = "example-lambda"
    Environment = "production"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "example-api"
  description = "API for example service"

  tags = {
    Name = "example-api"
    Environment = "production"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id   = "apiOrigin"

    custom_origin {
      origin_protocol_policy = "https-only"
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "POST", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "example-cdn"
    Environment = "production"
  }
}

resource "aws_global_accelerator_accelerator" "example" {
  name = "example-accelerator"
  enabled = true

  tags = {
    Name = "example-accelerator"
    Environment = "production"
  }
}

resource "aws_kinesis_stream" "example" {
  name        = "example-stream"
  shard_count = 1

  tags = {
    Name = "example-stream"
    Environment = "production"
  }
}

resource "aws_sqs_queue" "example" {
  name = "example-queue"

  tags = {
    Name = "example-queue"
    Environment = "production"
  }
}

resource "aws_cloudwatch_log_group" "example" {
  name = "/aws/lambda/example_lambda"

  retention_in_days = 14

  tags = {
    Name = "example-log-group"
    Environment = "production"
  }
}

resource "aws_xray_daemon" "example" {
  name = "example-xray-daemon"

  tags = {
    Name = "example-xray-daemon"
    Environment = "production"
  }
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket for data storage"
  value       = aws_s3_bucket.data_bucket.bucket
}

output "api_endpoint" {
  description = "API Gateway endpoint"
  value       = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.cdn.id
}

output "kinesis_stream_name" {
  description = "Kinesis Stream Name"
  value       = aws_kinesis_stream.example.name
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.example.id
