  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"podcast_processor\" {\n  function_name = \"PodcastProcessor\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n  vpc_config {\n    subnet_ids         = [aws_subnet.private.id]\n    security_group_ids = [aws_security_group.allow_http.id]\n  }\n}\n\nresource \"aws_dynamodb_table\" \"podcast_table\" {\n  name         = \"PodcastTable\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_sqs_queue\" \"podcast_queue\" {\n  name = \"PodcastQueue\"\n}\n\nresource \"aws_cloudfront_distribution\" \"podcast_distribution\" {\n  origin {\n    domain_name = aws_s3_bucket.podcast_bucket.bucket_regional_domain_name\n    origin_id   = \"S3Origin\"\n  }\n}\n\nresource \"aws_lb\" \"main\" {\n  name               = \"podcast-alb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets           = [aws_subnet.public.id]\n}\n",
  "diagram": "graph TD\n    User([User])\n    User -->|Request| ALB([AWS Application Load Balancer])\n    ALB -->|Forward| Lambda([AWS Lambda])\n    Lambda -->|Process| DynamoDB([Amazon DynamoDB])\n    Lambda -->|Send Message| SQS([Amazon SQS])\n    CloudFront([Amazon CloudFront]) -->|Serve| User"
}

