resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = local.common_tags
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-api-sg"
  tags = local.common_tags
}

resource "aws_security_group_rule" "allow_api_gateway" {
  type = "ingress"
  from_port = 443
  to_port = 443
  protocol = "tcp"
  security_group_id = aws_security_group.api_sg.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${local.environment}-api-lambda"
  handler = "index.handler"
  runtime = "nodejs14.x"
  role = aws_iam_role.lambda_exec.arn
  s3_bucket = aws_s3_bucket.lambda_code.bucket
  s3_key = aws_s3_bucket_object.lambda_code.key
  environment {
    DB_CONNECTION_STRING = aws_rds_instance.main.endpoint
  }
  tags = local.common_tags
}

resource "aws_api_gateway_rest_api" "api" {
  name = "${local.environment}-api"
  description = "API for the application"
  tags = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id = aws_api_gateway_rest_api.api.root_resource_id
  path_part = "v1"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.api_lambda.invoke_arn
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_api_gateway_rest_api.api.execution_arn
    origin_id = "apiOrigin"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "apiOrigin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    forwarded_values {
      query_string = true
    }
  }
  tags = local.common_tags
}

resource "aws_rds_instance" "main" {
  identifier = "${local.environment}-db"
  engine = "postgres"
  instance_class = var.db_instance_class
  allocated_storage = var.db_allocated_storage
  username = var.db_username
  password = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.api_sg.id]
  tags = local.common_tags
}

resource "aws_dynamodb_table" "main" {
  name = "${local.environment}-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = local.common_tags
}

resource "aws_sns_topic" "notifications" {
  name = "${local.environment}-notifications"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "api_logs" {
  name = "/aws/lambda/${aws_lambda_function.api_lambda.function_name}"
  retention_in_days = 14
  tags = local.common_tags
}

resource "aws_xray_daemon" "daemon" {
  name = "${local.environment}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_rest_api.api.execution_invoke_url
}

output "db_endpoint" {
  value = aws_rds_instance.main.endpoint
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type = string
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type = string
  default = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of public subnet CIDR blocks"
  type = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of private subnet CIDR blocks"
  type = list(string)
  default = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "public_subnet_count" {
  description = "Number of public subnets"
  type = number
  default = 2
}

variable "private_subnet_count" {
  description = "Number of private subnets"
  type = number
  default = 2
}

variable "db_instance_class" {
  description = "RDS instance class"
  type = string
  default = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for RDS"
  type = number
  default = 20
}

variable "db_username" {
  description = "Database username"
  type = string
}

variable "db_password" {
  description = "Database password"
  type = string
