  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_lambda_function\" \"ride_event_processor\" {\n  function_name = \"RideEventProcessor\"\n  handler      = \"index.handler\"\n  runtime      = \"nodejs14.x\"\n  role         = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"ride_events\" {\n  name         = \"RideEvents\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"event_id\"\n    type = \"S\"\n  }\n  hash_key = \"event_id\"\n}\n\nresource \"aws_kinesis_stream\" \"ride_events_stream\" {\n  name   = \"RideEventsStream\"\n  shard_count = 1\n}\n\nresource \"aws_api_gateway_rest_api\" \"ride_api\" {\n  name = \"RideAPI\"\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = aws_api_gateway_rest_api.ride_api.execution_arn\n    origin_id   = \"APIGateway\"\n  }\n}\n\nresource \"aws_iam_role\" \"lambda_exec\" {\n  name = \"lambda_exec_role\"\n  assume_role_policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Action    = \"sts:AssumeRole\"\n        Principal = { Service = \"lambda.amazonaws.com\" }\n        Effect    = \"Allow\"\n        Sid       = \"\"\n      }\n    ]\n  })\n}\n",
