variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  default     = "my_api_gateway"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  default     = "my_dynamodb_table"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution."
  default     = "my_cloudfront_distribution"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main_vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = {
    Name = "public_subnet_${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = {
    Name = "private_subnet_${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "lambda_security_group"
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "api_gateway_security_group"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = {
    Name = var.dynamodb_table_name
  }
}

resource "aws_lambda_function" "main" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")
  environment {
    TABLE_NAME = aws_dynamodb_table.main.name
  }
  tags = {
    Name = var.lambda_function_name
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.lambda_function_name}_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Effect = "Allow"
      Sid    = ""
    }]
  })
}

resource "aws_iam_policy_attachment" "lambda_policy" {
  name       = "${var.lambda_function_name}_policy_attachment"
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_api_gateway_rest_api" "main" {
  name        = var.api_gateway_name
  description = "API Gateway for Lambda integration"
  tags = {
    Name = var.api_gateway_name
  }
}

resource "aws_api_gateway_resource" "lambda_resource" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "lambda"
}

resource "aws_api_gateway_method" "lambda_method" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.lambda_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda_integration" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.lambda_resource.id
  http_method = aws_api_gateway_method.lambda_method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.main.invoke_arn
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name = "/aws/lambda/${aws_lambda_function.main.function_name}"
  retention_in_days = 14
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_api_gateway_rest_api.main.execution_arn
    origin_id   = "api_gateway_origin"
  }
  enabled = true
  default_cache_behavior {
    target_origin_id = "api_gateway_origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
  }
  tags = {
    Name = var.cloudfront_distribution_name
  }
}

output "api_gateway_invoke_url" {
  value = "${aws_api_gateway_rest_api.main.execution_arn}/lambda"
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.main.name
}

output "lambda_function_name" {
  value = aws_lambda_function.main.function_name
}

output "cloudfront_distribution_domain" {
  value = aws_cloudfront_distribution.main.domain_name
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_DynamoDB[(DynamoDB)]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_API_Gateway
    Amazon_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_DynamoDB
    AWS_Lambda -->|metrics| Amazon_CloudWatch"
}

