variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "environment" {
  description = "The environment for the deployment (e.g., production, staging)"
  default     = "production"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  tags = {
    Name = "${var.environment}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "${var.environment}-public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

resource "aws_security_group" "api_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.environment}-api-sg"
  }
}

resource "aws_security_group_rule" "allow_api_gateway" {
  type              = "ingress"
  from_port        = 443
  to_port          = 443
  protocol         = "tcp"
  security_group_id = aws_security_group.api_sg.id
  cidr_blocks      = ["0.0.0.0/0"]
}

resource "aws_lambda_function" "api_lambda" {
  function_name = "${var.environment}-api-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  environment {
    TABLE_NAME = aws_dynamodb_table.api_table.name
  }
  tags = {
    Name = "${var.environment}-api-lambda"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_policy.json
}

data "aws_iam_policy_document" "lambda_assume_policy" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_dynamodb_table" "api_table" {
  name         = "${var.environment}-api-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = {
    Name = "${var.environment}-api-table"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for ${var.environment} environment"
  tags = {
    Name = "${var.environment}-api"
  }
}

resource "aws_api_gateway_resource" "root" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"
}

resource "aws_api_gateway_method" "get_method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.root.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda_integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.root.id
  http_method = aws_api_gateway_method.get_method.http_method
  integration_http_method = "POST"
  type = "AWS_PROXY"
  uri = aws_lambda_function.api_lambda.invoke_arn
}

resource "aws_cloudwatch_log_group" "api_logs" {
  name = "/aws/api_gateway/${aws_api_gateway_rest_api.api.id}"
  retention_in_days = 14
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "${var.environment}-xray-daemon"
  role_arn = aws_iam_role.lambda_exec.arn
  tags = {
    Name = "${var.environment}-xray-daemon"
  }
}

output "api_endpoint" {
  value = aws_api_gateway_deployment.api.invoke_url
  description = "The endpoint of the API Gateway"
}",
