provider "aws" {
  region  = var.region
  profile = var.aws_profile

  ignore_tags {
    key_prefixes = ["kubernetes.io"]
  }
}

variable "region" {
  description = "The AWS region to deploy resources"
  default     = "ap-southeast-1"
}

variable "aws_profile" {
  description = "The AWS CLI profile to use"
  default     = "default"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t3.micro"
}

variable "db_instance_class" {
  description = "RDS instance class"
  default     = "db.t3.micro"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function"
  default     = "my_lambda_function"
}

data "aws_availability_zones" "available" {}

# VPC creation
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# Associate Public Subnets with Route Table
resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Security Group for EC2
resource "aws_security_group" "ec2_sg" {
  vpc_id = aws_vpc.main.id
  name = "ec2_sg"
  description = "Allow HTTP and SSH access"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2_security_group"
  }
}

# EC2 Instance
resource "aws_instance" "app" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "app-instance"
  }
}

# RDS Instance
resource "aws_db_instance" "default" {
  identifier = "mydb"
  engine     = "mysql"
  instance_class = var.db_instance_class
  allocated_storage = 20
  username   = "admin"
  password   = "password"
  db_name    = "mydb"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "mydb-instance"
  }
}

# DynamoDB Table
resource "aws_dynamodb_table" "my_table" {
  name         = "my_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name = "my_dynamodb_table"
  }
}

# SQS Queue
resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"

  tags = {
    Name = "my_sqs_queue"
  }
}

# SNS Topic
resource "aws_sns_topic" "my_topic" {
  name = "my_topic"

  tags = {
    Name = "my_sns_topic"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "my_log_group"
  retention_in_days = 14

  tags = {
    Name = "my_cloudwatch_log_group"
  }
}

# CloudTrail
resource "aws_cloudtrail" "my_trail" {
  name                          = "my_trail"
  s3_bucket_name                = "my-cloudtrail-bucket"
  is_multi_region_trail        = true
  enable_log_file_validation    = true
  include_global_service_events = true

  tags = {
    Name = "my_cloudtrail"
  }
}

# Lambda Function
resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x" # Example runtime
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = "my-lambda-bucket"
  s3_key        = "lambda_function.zip"

  tags = {
    Name = "my_lambda_function"
  }
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid    = ""
      },
    ]
  })

  tags = {
    Name = "lambda_exec_role"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "ec2_instance_id" {
  value = aws_instance.app.id
}

output "rds_instance_endpoint" {
  value = aws_db_instance.default.endpoint
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.my_table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.my_topic.arn
}

output "cloudwatch_log_group_name" {
  value = aws_cloudwatch_log_group.my_log_group.name
}

output "cloudtrail_arn" {
  value = aws_cloudtrail.my_trail.arn
}

output "lambda_function_arn" {
  value = aws_lambda_function.my_lambda.arn
}",
