resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support = true
  enable_dns_hostnames = true
  tags = merge(local.common_tags, { Name = "${local.environment}-vpc" })
}

resource "aws_subnet" "public" {
  count = var.public_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  tags = merge(local.common_tags, { Name = "${local.environment}-public-subnet-${count.index}" })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  tags = merge(local.common_tags, { Name = "${local.environment}-private-subnet-${count.index}" })
}

resource "aws_security_group" "ecs" {
  vpc_id = aws_vpc.main.id
  name = "${local.environment}-ecs-sg"
  tags = local.common_tags
}

resource "aws_security_group_rule" "allow_http" {
  type = "ingress"
  from_port = 80
  to_port = 80
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "allow_https" {
  type = "ingress"
  from_port = 443
  to_port = 443
  protocol = "tcp"
  security_group_id = aws_security_group.ecs.id
  cidr_blocks = ["0.0.0.0/0"]
}

resource "aws_iam_role" "ecs_task_role" {
  name = "${local.environment}-ecs-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume.json
  tags = local.common_tags
}

data "aws_iam_policy_document" "ecs_task_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_ecs_cluster" "main" {
  name = "${local.environment}-ecs-cluster"
  tags = local.common_tags
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.environment}-app"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_cpu
  memory                  = var.ecs_memory
  execution_role_arn      = aws_iam_role.ecs_task_role.arn
  task_role_arn           = aws_iam_role.ecs_task_role.arn

  container_definitions = jsonencode([{
    name      = "app"
    image     = var.app_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])
}

resource "aws_ecs_service" "app" {
  name            = "${local.environment}-app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${local.environment}-api"
  description = "API for ${local.environment} environment"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "v1"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_lambda_function" "lambda" {
  function_name = "${local.environment}-lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = var.lambda_s3_bucket
  s3_key        = var.lambda_s3_key
  tags          = local.common_tags
}

resource "aws_dynamodb_table" "table" {
  name         = "${local.environment}-dynamodb-table"
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags = local.common_tags
}

resource "aws_rds_cluster" "db" {
  cluster_identifier      = "${local.environment}-rds-cluster"
  engine                 = "aurora-postgresql"
  master_username        = var.db_username
  master_password        = var.db_password
  skip_final_snapshot    = true
  tags                   = local.common_tags
}

resource "aws_sqs_queue" "queue" {
  name = "${local.environment}-sqs-queue"
  tags = local.common_tags
}

resource "aws_sns_topic" "topic" {
  name = "${local.environment}-sns-topic"
  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/ecs/${local.environment}/logs"
  retention_in_days = 7
  tags = local.common_tags
}

resource "aws_xray_daemon" "daemon" {
  name = "${local.environment}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
  value = aws_api_gateway_deployment.api.invoke_url
}

output "dynamodb_table_name" {
  value = aws_dynamodb_table.table.name
}

output "sqs_queue_url" {
  value = aws_sqs_queue.queue.id
}

output "sns_topic_arn" {
  value = aws_sns_topic.topic.arn
