variable "region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "environment" {
  description = "The environment for the deployment (e.g., prod, dev)"
  default     = "prod"
}

variable "lambda_memory_size" {
  description = "Memory size for the Lambda function"
  default     = 128
}

variable "lambda_timeout" {
  description = "Timeout for the Lambda function in seconds"
  default     = 3
}

variable "api_gateway_stage" {
  description = "Stage name for the API Gateway"
  default     = "v1"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  default     = "my-table"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
  tags              = local.common_tags
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

resource "aws_lambda_function" "api_handler" {
  function_name = "${var.environment}-api-handler"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  memory_size   = var.lambda_memory_size
  timeout       = var.lambda_timeout
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"

  environment {
    TABLE_NAME = aws_dynamodb_table.main.name
  }

  tags = local.common_tags
}

resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect    = "Allow"
        Sid       = ""
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy_attachment" "lambda_dynamodb" {
  name       = "${var.environment}-lambda-dynamodb-attach"
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = aws_iam_policy.dynamodb_policy.arn
}

resource "aws_iam_policy" "dynamodb_policy" {
  name        = "${var.environment}-dynamodb-policy"
  description = "Policy for Lambda to access DynamoDB"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = ["dynamodb:PutItem", "dynamodb:GetItem", "dynamodb:Scan"]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.main.arn
      },
    ]
  })
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "${var.environment}-api"
  description = "API for my application"
  tags        = local.common_tags
}

resource "aws_api_gateway_resource" "items" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "items"
}

resource "aws_api_gateway_method" "get_items" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.items.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "lambda_integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.items.id
  http_method = aws_api_gateway_method.get_items.http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.api_handler.invoke_arn
}

resource "aws_dynamodb_table" "main" {
  name         = var.dynamodb_table_name
  billing_mode = "PAY_PER_REQUEST"
  attribute {
    name = "id"
    type = "S"
  }
  hash_key = "id"
  tags     = local.common_tags
}

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name_prefix = "/aws/lambda/${aws_lambda_function.api_handler.function_name}"
  retention_in_days = 14
}

resource "aws_xray_daemon" "xray" {
  name = "${var.environment}-xray-daemon"
  tags = local.common_tags
}

output "api_endpoint" {
