  "terraform": "resource \"aws_vpc\" \"main\" {  cidr_block = \"10.0.0.0/16\"}\n\nresource \"aws_subnet\" \"subnet1\" {  vpc_id     = aws_vpc.main.id  cidr_block = \"10.0.1.0/24\"}\n\nresource \"aws_security_group\" \"api_sg\" {  vpc_id = aws_vpc.main.id  ingress {    from_port   = 80    to_port     = 80    protocol    = \"tcp\"    cidr_blocks = [\"0.0.0.0/0\"]  }}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {  name = \"VideoTranscodingAPI\"}\n\nresource \"aws_lambda_function\" \"transcoder\" {  function_name = \"TranscoderFunction\"  handler = \"index.handler\"  runtime = \"nodejs14.x\"  role = aws_iam_role.lambda_exec.arn}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {  origin {    domain_name = aws_s3_bucket.video_bucket.bucket_regional_domain_name    origin_id   = \"S3Origin\"  }}\n\nresource \"aws_s3_bucket\" \"video_bucket\" {  bucket = \"user-uploaded-videos\"}\n\nresource \"aws_dynamodb_table\" \"metadata_table\" {  name         = \"VideoMetadata\"  billing_mode = \"PAY_PER_REQUEST\"  attribute {    name = \"video_id\"    type = \"S\"  }  primary_key {    name = \"video_id\"    type = \"S\"  }}\n\nresource \"aws_sqs_queue\" \"transcoding_queue\" {  name = \"TranscodingQueue\"}",
