provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_password" {
  description = "Password for RDS instance"
  type        = string
  sensitive   = true
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                 = aws_vpc.main.id
  cidr_block             = element(var.public_subnet_cidrs, count.index)
  availability_zone      = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                 = aws_vpc.main.id
  cidr_block             = element(var.private_subnet_cidrs, count.index)
  availability_zone      = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "lambda_sg" {
  name        = "lambda_security_group"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lambda_sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_security_group"
  description = "Security group for RDS instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    security_groups = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "mysql"
  engine_version      = "8.0"
  db_name             = "mydatabase"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  environment {
    RDS_HOST = aws_db_instance.rds_instance.address
  }

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy_attachment" "lambda_policy" {
  name       = "lambda_policy_attachment"
  roles      = [aws_iam_role.lambda_exec.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_ecs_cluster" "my_ecs_cluster" {
  name = "my_ecs_cluster"

  tags = {
    Name = "my_ecs_cluster"
  }
}

resource "aws_cloudtrail" "main" {
  name                          = "main-cloudtrail"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_bucket.bucket
  is_multi_region_trail         = true
  enable_log_file_validation     = true

  tags = {
    Name = "main_cloudtrail"
  }
}

resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket = "my-cloudtrail-bucket-${random_string.bucket_suffix.result}"

  tags = {
    Name = "cloudtrail_bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name              = "/aws/lambda/my_lambda_function"
  retention_in_days = 14

  tags = {
    Name = "lambda_log_group"
  }
}

resource "aws_config_configuration_recorder" "main" {
  name     = "main_config_recorder"
  role_arn = aws_iam_role.config_recorder.arn

  recording_group {
    all_supported = true
    include_global_resource_types = true
  }
}

resource "aws_iam_role" "config_recorder" {
  name = "config_recorder_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "config.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_policy_attachment" "config_recorder_policy" {
  name       = "config_recorder_policy_attachment"
  roles      = [aws_iam_role.config_recorder.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}",
  "diagram": "graph TD
    User([User / Client])
    AWS_IAM_Identity_Center[IAM Identity Center]
    AWS_VPC[VPC]
    Security_Groups[Security Groups]
    AWS_Lambda[Lambda]
    Amazon_ECS[ECS]
    Amazon_RDS[(RDS)]
    AWS_CloudTrail[CloudTrail]
    Amazon_CloudWatch[CloudWatch]
    AWS_Config[Config]
    User --> AWS_IAM_Identity_Center
    User --> AWS_VPC
    User --> Security_Groups
    AWS_IAM_Identity_Center --> AWS_Lambda
    AWS_IAM_Identity_Center --> Amazon_ECS
    AWS_VPC --> AWS_Lambda
    AWS_VPC --> Amazon_ECS
    Security_Groups --> AWS_Lambda
    Security_Groups --> Amazon_ECS
    AWS_Lambda --> Amazon_RDS
    Amazon_ECS --> Amazon_RDS
    AWS_Lambda -->|metrics| AWS_CloudTrail
    AWS_Lambda -->|metrics| Amazon_CloudWatch
    AWS_Lambda -->|metrics| AWS_Config
    Amazon_ECS -->|metrics| AWS_CloudTrail
    Amazon_ECS -->|metrics| Amazon_CloudWatch
    Amazon_ECS -->|metrics| AWS_Config"
}

