resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "${var.aws_region}a"

  tags = {
    Name = "public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"

  tags = {
    Name = "private-subnet"
  }
}

resource "aws_security_group" "api_gateway" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "api-gateway-sg"
  }
}

resource "aws_api_gateway_rest_api" "api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"

  tags = {
    Name = var.api_gateway_name
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = "my_lambda_function"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "lambda_exec_role"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "batch-compute-env"
  type                     = "MANAGED"

  compute_resources {
    type              = "EC2"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_types   = ["optimal"]
    subnets          = [aws_subnet.private.id]
    security_group_ids = [aws_security_group.api_gateway.id]
  }

  service_role = aws_iam_role.batch_service.arn

  tags = {
    Name = "batch_compute_env"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "my_ecs_cluster"

  tags = {
    Name = "my_ecs_cluster"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = var.versioning == "Enabled"
  }

  tags = {
    Name = "data_bucket"
  }
}

resource "aws_athena_database" "athena_db" {
  name   = "my_athena_db"
  bucket = aws_s3_bucket.data_bucket.bucket

  tags = {
    Name = "my_athena_db"
  }
}

resource "aws_redshift_cluster" "redshift" {
  cluster_identifier = "my-redshift-cluster"
  node_type         = "dc2.large"
  master_username   = "awsuser"
  master_password   = var.redshift_password
  database_name     = "dev"
  cluster_type      = "single-node"

  tags = {
    Name = "my_redshift_cluster"
  }
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "my_kinesis_stream"
  shard_count = 1

  tags = {
    Name = "my_kinesis_stream"
  }
}

resource "aws_sqs_queue" "sqs_queue" {
  name = "my_sqs_queue"

  tags = {
    Name = "my_sqs_queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/lambda/my_lambda_function"

  tags = {
    Name = "my_lambda_log_group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray_daemon"
  }
