  "terraform": "variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type."
  type        = string
  default     = "t3.micro"
}

variable "spot_instance_price" {
  description = "Maximum price for EC2 Spot Instances."
  type        = string
  default     = "0.01"
}

variable "bucket_prefix" {
  description = "Bucket prefix for the S3."
  type        = string
  default     = "audiophile-e2e-pipeline-"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "elb_sg" {
  name        = "elb_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow HTTP and HTTPS traffic to the ELB"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "elb-sg"
  }
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow SSH and internal traffic to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    security_groups = [aws_security_group.elb_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

resource "aws_elb" "main" {
  name               = "main-elb"
  availability_zones = aws_vpc.main.availability_zones
  security_groups    = [aws_security_group.elb_sg.id]

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  listener {
    instance_port     = 443
    instance_protocol = "HTTPS"
    lb_port           = 443
    lb_protocol       = "HTTPS"
    ssl_certificate_id = var.ssl_certificate_id
  }

  tags = {
    Name = "main-elb"
  }
}

resource "aws_instance" "spot_instance" {
  count         = 2
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  spot_price    = var.spot_instance_price
  subnet_id     = element(aws_subnet.private[*].id, count.index)

  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "spot-instance-${count.index + 1}"
  }
}

resource "aws_s3_bucket" "main" {
  bucket = "${var.bucket_prefix}${substr(md5(timestamp()), 0, 8)}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "main-s3-bucket"
  }
}

resource "aws_sqs_queue" "main" {
  name = "main-sqs-queue"

  tags = {
    Name = "main-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "main" {
  name = "main-log-group"

  retention_in_days = 14

  tags = {
    Name = "main-log-group"
  }
}

resource "aws_batch_compute_environment" "main" {
  compute_environment_name = "main-batch-compute-env"
  type                     = "MANAGED"

  compute_resources {
    type                 = "SPOT"
    min_v_cpus          = 0
    max_v_cpus          = 16
    desired_v_cpus      = 4
    instance_role       = "ecsInstanceRole"
    instance_types      = [var.instance_type]
    subnets             = aws_subnet.private[*].id
    security_group_ids  = [aws_security_group.ec2_sg.id]
  }

  service_role = "AWSBatchServiceRole"

  tags = {
    Name = "main-batch-compute-env"
  }
}

resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_s3_bucket.main.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.main.id
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "main-cloudfront-distribution"
  }
}

resource "aws_cloudfront_origin_access_identity" "main" {
  comment = "Origin Access Identity for CloudFront to access S3 bucket"
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

output "s3_bucket_name" {
  value = aws_s3_bucket.main.bucket
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.main.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_VPC[VPC]
    Elastic_Load_Balancer[Elastic Load Balancer]
    Amazon_EC2_Spot_Instances[EC2 Spot Instances]
    AWS_Batch[Batch]
    Amazon_S3[(S3)]
    Amazon_RDS[(RDS)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_VPC
    Amazon_CloudFront --> Elastic_Load_Balancer
    Amazon_VPC --> Amazon_EC2_Spot_Instances
    Amazon_VPC --> AWS_Batch
    Elastic_Load_Balancer --> Amazon_EC2_Spot_Instances
    Elastic_Load_Balancer --> AWS_Batch
    Amazon_EC2_Spot_Instances --> Amazon_S3
    Amazon_EC2_Spot_Instances --> Amazon_RDS
    AWS_Batch --> Amazon_S3
    AWS_Batch --> Amazon_RDS
    Amazon_EC2_Spot_Instances --> Amazon_SQS
    AWS_Batch --> Amazon_SQS
    Amazon_EC2_Spot_Instances -->|metrics| Amazon_CloudWatch
    Amazon_EC2_Spot_Instances -->|metrics| AWS_X_Ray
    AWS_Batch -->|metrics| Amazon_CloudWatch
    AWS_Batch -->|metrics| AWS_X_Ray"
}

