}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)
  subnet_id = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ec2_sg" {
  name        = "ec2_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow HTTP and SSH access to EC2 instances."

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-security-group"
  }
}

resource "aws_instance" "spot_instance" {
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  spot_price    = "0.05"
  subnet_id     = aws_subnet.public[0].id
  security_groups = [aws_security_group.ec2_sg.name]

  tags = {
    Name = "spot-instance"
  }
}

resource "aws_s3_bucket" "bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "my-s3-bucket"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "rds-instance"
  }
}

resource "aws_security_group" "rds_security_group" {
  name        = "rds_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS from EC2 instances."

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ec2_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my-sqs-queue"

  tags = {
    Name = "my-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "my-log-group"

  retention_in_days = 14

  tags = {
    Name = "my-log-group"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.my_identity.id
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"

    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS", "PUT", "POST", "PATCH", "DELETE"]
    cached_methods  = ["GET", "HEAD"]

    forwarded_values {
      query_string = false
    }
  }

  tags = {
    Name = "my-cloudfront-distribution"
  }
}

resource "aws_cloudfront_origin_access_identity" "my_identity" {
  comment = "Origin Access Identity for CloudFront"

  tags = {
    Name = "my-origin-access-identity"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "batch-compute-env"
  type                     = "MANAGED"
  state                   = "ENABLED"

  compute_resources {
    type              = "SPOT"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.ec2_sg.id]
  }

  service_role = aws_iam_role.batch_service_role.arn
}

resource "aws_iam_role" "batch_service_role" {
  name = "batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Effect = "Allow"
        Sid = ""
      },
    ]
  })

  tags = {
    Name = "batch-service-role"
  }
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.bucket.bucket
}

output "sqs_queue_url" {
  value = aws_sqs_queue.my_queue.id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.cdn.id
