  "terraform": "resource \"aws_vpc\" \"main\" {  cidr_block = \"10.0.0.0/16\"}\n\nresource \"aws_subnet\" \"main\" {  vpc_id = aws_vpc.main.id  cidr_block = \"10.0.1.0/24\"  availability_zone = \"us-east-1a\"}\n\nresource \"aws_lambda_function\" \"my_function\" {  function_name = \"my_function\"  handler = \"index.handler\"  runtime = \"nodejs14.x\"  memory_size = 128  timeout = 3  role = aws_iam_role.lambda_exec.arn  source_code_hash = filebase64sha256(\"function.zip\")}\n\nresource \"aws_api_gateway_rest_api\" \"my_api\" {  name = \"MyAPI\"}\n\nresource \"aws_dynamodb_table\" \"my_table\" {  name = \"MyTable\"  billing_mode = \"PAY_PER_REQUEST\"  attribute { name = \"customerId\"  type = \"S\"}} \n\nresource \"aws_sns_topic\" \"my_topic\" {  name = \"MySNSTopic\"}\n\nresource \"aws_cloudfront_distribution\" \"my_distribution\" {  origin {    domain_name = aws_api_gateway_rest_api.my_api.execution_arn  origin_id = \"APIGateway\"  }}",
