      "spike_estimate_usd": 1200.0,
      "optimization": "Consider using reserved instances for ECS or Fargate to save on compute costs over time."
    },
    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_ecs_cluster\" \"main\" {}\n\nresource \"aws_ecs_task_definition\" \"sensor_processing\" {\n  family                   = \"sensor_processing\"\n  network_mode            = \"awsvpc\"\n  requires_compatibilities = [\"FARGATE\"]\n  cpu                     = \"256\"\n  memory                  = \"512\"\n  container_definitions = jsonencode([\n    {\n      name      = \"sensor_data_processor\"\n      image     = \"your_docker_image\"\n      essential = true\n      portMappings = [{\n        containerPort = 80,\n        hostPort      = 80,\n        protocol      = \"tcp\"\n      }]\n    }\n  ])\n}\n\nresource \"aws_elasticloadbalancingv2_load_balancer\" \"main\" {\n  name               = \"app-lb\"\n  internal           = false\n  load_balancer_type = \"application\"\n  security_groups    = [aws_security_group.allow_http.id]\n  subnets           = [aws_subnet.public_subnet.id]\n}\n\nresource \"aws_dynamodb_table\" \"sensor_data\" {\n  name         = \"SensorData\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"sensor_id\"\n    type = \"S\"\n  }\n  hash_key = \"sensor_id\"\n}\n\nresource \"aws_kinesis_stream\" \"sensor_stream\" {\n  name        = \"SensorDataStream\"\n  shard_count = 1\n}",
    "diagram": "graph TD\n    User([User])\n    User -->|Requests| API_Gateway([Amazon API Gateway])\n    API_Gateway -->|Route Requests| Load_Balancer([AWS Elastic Load Balancer])\n    Load_Balancer -->|Distribute| Fargate([AWS Fargate])\n    Fargate -->|Process Data| Kinesis([Amazon Kinesis])\n    Kinesis -->|Store Data| DynamoDB([Amazon DynamoDB])\n    Fargate -->|Cache Data| ElastiCache([Amazon ElastiCache])\n    Fargate -->|Send Notifications| SNS([Amazon SNS])\n    Load_Balancer -->|Monitor| CloudWatch([Amazon CloudWatch])"
  }
}

{
