    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_internet_gateway\" \"main\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"telemedicine_function\" {\n  function_name = \"telemedicine\"\n  runtime = \"nodejs14.x\"\n  handler = \"index.handler\"\n  role = aws_iam_role.lambda_exec.arn\n  s3_bucket = \"your-bucket-name\"\n  s3_key    = \"your-code.zip\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"telemedicine_api\" {\n  name = \"Telemedicine API\"\n}\n\nresource \"aws_dynamodb_table\" \"telemedicine_table\" {\n  name         = \"TelemedicineData\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sns_topic\" \"telemedicine_notifications\" {\n  name = \"TelemedicineNotifications\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"telemedicine_logs\" {\n  name = \"/aws/lambda/telemedicine\"\n}",
