    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_lambda\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_s3_bucket\" \"data_lake\" {\n  bucket = \"my-data-lake-bucket\"\n}\n\nresource \"aws_lambda_function\" \"log_processor\" {\n  function_name = \"log_processor\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  s3_bucket = aws_s3_bucket.data_lake.id\n}\n\nresource \"aws_kinesis_stream\" \"log_stream\" {\n  name        = \"log_stream\"\n  shard_count = 5\n}\n\nresource \"aws_emr_cluster\" \"log_processing_cluster\" {\n  name          = \"LogProcessingCluster\"\n  release_label = \"emr-6.3.0\"\n  applications  = [\"Spark\"]\n  ec2_attributes {\n    subnet_id = aws_subnet.public.id\n    emr_on_demand_instance_group {\n      instance_type = \"m5.xlarge\"\n      instance_count = 3\n    }\n  }\n}\n",
