    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name        = \"FraudDetectionAPI\"\n  description = \"API for real-time fraud detection\"\n}\n\nresource \"aws_lambda_function\" \"fraud_detection\" {\n  function_name = \"FraudDetectionFunction\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"fraud_records\" {\n  name           = \"FraudRecords\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"transaction_id\"\n    type = \"S\"\n  }\n  global_secondary_index {\n    name            = \"status-index\"\n    hash_key        = \"status\"\n    projection_type = \"ALL\"\n  }\n}\n\nresource \"aws_kinesis_stream\" \"fraud_stream\" {\n  name        = \"FraudStream\"\n  shard_count = 1\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"fraud-cache\"\n  engine     = \"redis\"\n  node_type  = \"cache.t2.micro\"\n  num_cache_nodes = 1\n}",
