  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "c5n.large"
}

variable "elb_name" {
  description = "Elastic Load Balancer name"
  type        = string
  default     = "my-elb"
}

variable "cloudfront_distribution_name" {
  description = "CloudFront distribution name"
  type        = string
  default     = "my-cloudfront"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count      = length(var.private_subnet_cidrs)
  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "elb_sg" {
  name   = "elb-sg"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "elb-sg"
  }
}

resource "aws_security_group" "ec2_sg" {
  name   = "ec2-sg"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2-sg"
  }
}

resource "aws_elb" "main" {
  name               = var.elb_name
  availability_zones = aws_vpc.main.availability_zones

  listener {
    instance_port     = 80
    instance_protocol = "HTTP"
    lb_port           = 80
    lb_protocol       = "HTTP"
  }

  health_check {
    target              = "HTTP:80/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  security_groups = [aws_security_group.elb_sg.id]

  tags = {
    Name = var.elb_name
  }
}

resource "aws_instance" "compute" {
  count         = 2
  ami           = data.aws_ami.latest.id
  instance_type = var.instance_type
  subnet_id     = element(aws_subnet.private[*].id, count.index)

  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "compute-instance-${count.index + 1}"
  }
}

resource "aws_s3_bucket" "data_storage" {
  bucket = "my-data-storage-bucket"

  tags = {
    Name        = "data-storage"
    Environment = "production"
  }
}

resource "aws_fsx_lustre_file_system" "lustre" {
  storage_capacity = 1200
  deployment_type = "PERSISTENT"
  per_unit_storage_throughput = 200

  tags = {
    Name = "lustre-file-system"
  }
}

resource "aws_sqs_queue" "job_queue" {
  name = "job-queue"

  tags = {
    Name = "job-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "my-log-group"

  retention_in_days = 14

  tags = {
    Name = "my-log-group"
  }
}

resource "aws_batch_compute_environment" "batch" {
  compute_environment_name = "batch-compute-env"
  type                     = "MANAGED"

  compute_resources {
    type              = "EC2"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.ec2_sg.id]
  }

  service_role = "AWSBatchServiceRole"

  tags = {
    Name = "batch-compute-env"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.data_storage.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.s3_access_identity.id
    }
  }

  enabled = true

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = var.cloudfront_distribution_name
  }
}

resource "aws_cloudfront_origin_access_identity" "s3_access_identity" {
  comment = "Access identity for CloudFront to access S3 bucket"
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "Public Subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "Private Subnet IDs"
  value       = aws_subnet.private[*].id
}

output "elb_dns_name" {
  description = "DNS name of the Elastic Load Balancer"
  value       = aws_elb.main.dns_name
}

output "s3_bucket_name" {
  description = "S3 bucket name for data storage"
  value       = aws_s3_bucket.data_storage.bucket
}

output "cloudfront_distribution_id" {
  description = "CloudFront Distribution ID"
  value       = aws_cloudfront_distribution.cdn.id
}",
