terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.46"
    }
  }

  backend "s3" {}
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-security-group"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }

  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds-instance"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"

  tags = {
    Name        = "data-bucket"
    Environment = "Production"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_api_gateway_rest_api" "api" {
  name        = "MyAPI"
  description = "API for my application"

  tags = {
    Name = "api-gateway"
  }
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "items"

  tags = {
    Name = "api-resource"
  }
}

resource "aws_api_gateway_method" "method" {
  rest_api_id   = aws_api_gateway_rest_api.api.id
  resource_id   = aws_api_gateway_resource.resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "api-method"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.data_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.cdn_identity.id
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "cloudfront-distribution"
  }
}

resource "aws_cloudfront_origin_access_identity" "cdn_identity" {
  comment = "Origin Access Identity for CloudFront"

  tags = {
    Name = "cloudfront-origin-access-identity"
  }
}

resource "aws_ecs_cluster" "ecs_cluster" {
  name = "my-ecs-cluster"

  tags = {
    Name = "ecs-cluster"
  }
}

resource "aws_ecs_task_definition" "ecs_task" {
  family                   = "my-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = "256"
  memory                  = "512"

  container_definitions = jsonencode([{
    name      = "my-container"
    image     = "my-docker-image"
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "ecs-task-definition"
  }
}

resource "aws_ecs_service" "ecs_service" {
  name            = "my-ecs-service"
  cluster         = aws_ecs_cluster.ecs_cluster.id
  task_definition = aws_ecs_task_definition.ecs_task.id
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  tags = {
    Name = "ecs-service"
  }
}

resource "aws_batch_compute_environment" "batch_compute" {
  compute_environment_name = "my-batch-compute"
  type                     = "MANAGED"
  service_role            = aws_iam_role.batch_service_role.arn

  compute_resources {
    type              = "FARGATE"
    min_vcpus        = 0
    max_vcpus        = 16
    desired_vcpus    = 1
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.ecs_sg.id]
  }

  tags = {
    Name = "batch-compute-environment"
  }
}

resource "aws_batch_job_queue" "batch_queue" {
  name                 = "my-batch-queue"
  priority             = 1
  compute_environment  = aws_batch_compute_environment.batch_compute.id

  tags = {
    Name = "batch-job-queue"
  }
}

resource "aws_sqs_queue" "sqs_queue" {
  name = "my-sqs-queue"

  tags = {
    Name = "sqs-queue"
  }
}

resource "aws_sns_topic" "sns_topic" {
  name = "my-sns-topic"

  tags = {
    Name = "sns-topic"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/ecs/my-ecs-service"

  retention_in_days = 14

  tags = {
    Name = "cloudwatch-log-group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "vpc_id" {
  description = "VPC ID"
  value       = aws_vpc.main.id
}

output "rds_endpoint" {
  description = "RDS Endpoint"
  value       = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  description = "S3 Bucket Name"
  value       = aws_s3_bucket.data_bucket.id
}

output "api_gateway_url" {
  description = "API Gateway URL"
  value       = aws_api_gateway_rest_api.api.execution_arn
}

output "cloudfront_distribution_domain" {
  description = "CloudFront Distribution Domain"
  value       = aws_cloudfront_distribution.cdn.domain_name
}

output "ecs_service_name" {
  description = "ECS Service Name"
  value       = aws_ecs_service.ecs_service.name
}

output "sqs_queue_url" {
  description = "SQS Queue URL"
  value       = aws_sqs_queue.sqs_queue.id
}

output "sns_topic_arn" {
  description = "SNS Topic ARN"
  value       = aws_sns_topic.sns_topic.arn
}",
