variable "region" {
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "eks_cluster_name" {
  description = "EKS Cluster name"
  default     = "eks-auto-cluster"
}

variable "instance_type_c5n" {
  description = "EC2 Instance type for C5n"
  default     = "c5n.large"
}

variable "instance_type_p4d" {
  description = "EC2 Instance type for P4d"
  default     = "p4d.24xlarge"
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Main VPC"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                 = aws_vpc.main.id
  cidr_block             = var.public_subnet_cidrs[count.index]
  availability_zone      = element(data.aws_availability_zones.all.names, count.index)

  map_public_ip_on_launch = true

  tags = {
    Name = "Public Subnet ${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count              = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = element(data.aws_availability_zones.all.names, count.index)

  tags = {
    Name = "Private Subnet ${count.index + 1}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "Main IGW"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "Public Route Table"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "eks" {
  name   = "eks-security-group"
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "EKS Security Group"
  }
}

resource "aws_eks_cluster" "auto" {
  name     = var.eks_cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.31"

  vpc_config {
    subnet_ids = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  tags = {
    Name = var.eks_cluster_name
  }
}

resource "aws_iam_role" "cluster" {
  name = "${var.eks_cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role" "node" {
  name = "${var.eks_cluster_name}-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node.name
}

resource "aws_iam_role_policy_attachment" "node_registry_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node.name
}

resource "aws_ec2_instance" "c5n" {
  ami           = "ami-0c55b159cbfafe1f0" # Replace with a valid AMI ID
  instance_type = var.instance_type_c5n
  subnet_id     = aws_subnet.private[0].id
  security_groups = [aws_security_group.eks.id]

  tags = {
    Name = "C5n Instance"
  }
}

resource "aws_ec2_instance" "p4d" {
  ami           = "ami-0c55b159cbfafe1f0" # Replace with a valid AMI ID
  instance_type = var.instance_type_p4d
  subnet_id     = aws_subnet.private[1].id
  security_groups = [aws_security_group.eks.id]

  tags = {
    Name = "P4d Instance"
  }
}

resource "aws_s3_bucket" "data_storage" {
  bucket = "${var.eks_cluster_name}-data-storage"
  acl    = "private"

  tags = {
    Name = "Data Storage Bucket"
  }
}

resource "aws_efs_file_system" "shared" {
  creation_token = "${var.eks_cluster_name}-efs"
  performance_mode = "generalPurpose"

  tags = {
    Name = "Shared EFS"
  }
}

resource "aws_cloudwatch_log_group" "eks_logs" {
  name = "/aws/eks/${var.eks_cluster_name}/logs"
  retention_in_days = 7

  tags = {
    Name = "EKS Logs"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "${var.eks_cluster_name}-batch-env"
  type                     = "MANAGED"

  compute_resources {
    type              = "EC2"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = aws_iam_role.node.arn
    instance_type    = [var.instance_type_c5n, var.instance_type_p4d]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.eks.id]
  }

  service_role = aws_iam_role.batch_service.arn

  tags = {
    Name = "Batch Compute Environment"
  }
}

resource "aws_iam_role" "batch_service" {
  name = "${var.eks_cluster_name}-batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "batch.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "batch_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
  role       = aws_iam_role.batch_service.name
}

output "vpc_id" {
  value = aws_vpc.main.id
}

output "eks_cluster_name" {
  value = aws_eks_cluster.auto.name
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_storage.bucket
}

output "efs_id" {
  value = aws_efs_file_system.shared.id
}",
  "diagram": "graph TD
    User([User / Client])
    AWS_Transit_Gateway[Transit Gateway]
    Amazon_VPC[VPC]
    Route_53[Route 53]
    Amazon_EC2[EC2]
    AWS_Batch[Batch]
    Amazon_EKS[EKS]
    Amazon_S3[(S3)]
    Amazon_EFS[(EFS)]
    Amazon_CloudWatch[CloudWatch]
    AWS_Compute_Optimizer[Compute Optimizer]
    User --> AWS_Transit_Gateway
