provider "aws" {
  region = var.aws_region
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "${var.project_name}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr
  map_public_ip_on_launch = true
  availability_zone = var.availability_zone
  tags = {
    Name = "${var.project_name}-public-subnet"
  }
}

# Private Subnet
resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = var.availability_zone
  tags = {
    Name = "${var.project_name}-private-subnet"
  }
}

# Security Group for RDS
resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-rds-sg"
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_security_group.lambda_sg.id] # Allow Lambda access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Security Group for Lambda
resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-lambda-sg"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# RDS Instance
resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "${var.project_name}-rds"
  instance_class      = var.rds_instance_class
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = var.db_name
  username            = var.rds_username
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
}

# S3 Bucket
resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.project_name}-data-bucket"
  acl    = "private"

  tags = {
    Name = "${var.project_name}-data-bucket"
  }
}

# Lambda Function
resource "aws_lambda_function" "my_lambda" {
  function_name = "${var.project_name}-lambda"
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = var.lambda_s3_key
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec_role.arn

  tags = {
    Name = "${var.project_name}-lambda"
  }
}

# IAM Role for Lambda
resource "aws_iam_role" "lambda_exec_role" {
  name = "${var.project_name}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Effect    = "Allow"
      Sid       = ""
    }]
  })
}

# CloudWatch Log Group for Lambda
resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
}

# CloudTrail
resource "aws_cloudtrail" "main" {
  name                          = "${var.project_name}-cloudtrail"
  s3_bucket_name               = aws_s3_bucket.data_bucket.bucket
  is_multi_region_trail        = true
  enable_logging               = true
  tags = {
    Name = "${var.project_name}-cloudtrail"
  }
}

# CloudFront Distribution
resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.data_bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.cdn_identity.id
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods  = ["GET", "HEAD"]
  }

  tags = {
    Name = "${var.project_name}-cloudfront"
  }
}

resource "aws_cloudfront_origin_access_identity" "cdn_identity" {
  comment = "Origin Access Identity for CloudFront"
}

# AWS Direct Connect (Placeholder)
resource "aws_dx_connection" "dx_connection" {
  name             = "${var.project_name}-dx-connection"
  bandwidth       = "1Gbps"
  connection_type = "dedicated"
  location        = var.dx_location
  tags = {
    Name = "${var.project_name}-dx-connection"
  }
}

# AWS VPN (Placeholder)
resource "aws_vpn_gateway" "vpn_gateway" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${var.project_name}-vpn-gateway"
  }
}

# AWS DataSync (Placeholder)
resource "aws_datasync_agent" "datasync_agent" {
  name = "${var.project_name}-datasync-agent"
  tags = {
    Name = "${var.project_name}-datasync-agent"
  }
}

# AWS Database Migration Service (DMS) (Placeholder)
resource "aws_dms_replication_instance" "dms_instance" {
  replication_instance_id = "${var.project_name}-dms-instance"
  replication_instance_class = "dms.r5.large"
