  "terraform": "variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "ap-south-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  default     = "my_api_gateway"
}

variable "db_instance_class" {
  description = "Instance class for the Aurora DB."
  default     = "db.t3.medium"
}

variable "db_name" {
  description = "Database name for Aurora."
  default     = "mydatabase"
}

variable "db_username" {
  description = "Database username."
  default     = "admin"
}

variable "db_password" {
  description = "Database password."
  default     = "SuperSecretPassword123!"
}

provider "aws" {
  region = var.aws_region
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main_vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public_subnet_${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private_subnet_${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "lambda_security_group"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "api_gateway_sg" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "api_gateway_security_group"
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora_subnet_group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "aurora_subnet_group"
  }
}

resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "aurora-cluster"
  engine                 = "aurora-mysql"
  master_username        = var.db_username
  master_password        = var.db_password
  database_name          = var.db_name
  db_subnet_group_name   = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids = [aws_security_group.lambda_sg.id]

  tags = {
    Name = "aurora_cluster"
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec_role.arn
  filename      = "lambda_function.zip"

  environment {
    DB_HOST     = aws_rds_cluster.aurora.endpoint
    DB_USERNAME = var.db_username
    DB_PASSWORD = var.db_password
  }

  tags = {
    Name = "my_lambda_function"
  }
}

resource "aws_api_gateway_rest_api" "my_api" {
  name        = var.api_gateway_name
  description = "API Gateway for my application"

  tags = {
    Name = "my_api_gateway"
  }
}

resource "aws_api_gateway_resource" "my_api_resource" {
  rest_api_id = aws_api_gateway_rest_api.my_api.id
  parent_id   = aws_api_gateway_rest_api.my_api.root_resource_id
  path_part   = "myresource"

  tags = {
    Name = "my_api_resource"
  }
}

resource "aws_api_gateway_method" "my_api_method" {
  rest_api_id   = aws_api_gateway_rest_api.my_api.id
  resource_id   = aws_api_gateway_resource.my_api_resource.id
  http_method   = "GET"
  authorization = "NONE"

  integration {
    type = "AWS_PROXY"
    integration_http_method = "POST"
    uri = aws_lambda_function.my_lambda.invoke_arn
  }
}

resource "aws_sqs_queue" "my_queue" {
  name = "my_queue"

  tags = {
    Name = "my_queue"
  }
}

resource "aws_cloudwatch_log_group" "my_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "my_log_group"
  }
}

output "api_gateway_url" {
  value = "${aws_api_gateway_rest_api.my_api.execution_arn}/myresource"
}

output "lambda_function_arn" {
  value = aws_lambda_function.my_lambda.arn
}

output "aurora_endpoint" {
  value = aws_rds_cluster.aurora.endpoint
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    AWS_API_Gateway[API Gateway]
    AWS_Lambda[Lambda]
    Amazon_Aurora[(Aurora)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> AWS_API_Gateway
    AWS_API_Gateway --> AWS_Lambda
    AWS_Lambda --> Amazon_Aurora
    AWS_Lambda --> Amazon_SQS
    AWS_Lambda -->|metrics| Amazon_CloudWatch"
}

