  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  name = "lambda_sg"

  tags = {
    Name = "Lambda Security Group"
  }
}

resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.main.id
  name = "rds_security_group"

  ingress {
    from_port = 5432
    to_port = 5432
    protocol = "tcp"
    cidr_blocks = [aws_security_group.lambda_sg.id]
  }

  egress {
    from_port = 0
    to_port = 0
    protocol = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RDS Security Group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage = 20
  identifier = "rds-terraform"
  instance_class = "db.t3.micro"
  engine = "postgres"
  engine_version = "14.1"
  db_name = "crinacle_audiophile_ratings"
  username = "awsadmin"
  password = var.rds_password
  publicly_accessible = false
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "RDS Instance"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"
  versioning {
    enabled = true
  }

  tags = {
    Name = "Data Bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda_function.zip"

  tags = {
    Name = "My Lambda Function"
  }
}

resource "aws_iam_role" "lambda_exec" {
  name = "lambda_exec_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
        Sid = ""
      },
    ]
  })

  tags = {
    Name = "Lambda Execution Role"
  }
}

resource "aws_kinesis_stream" "my_kinesis" {
  name        = "my_kinesis_stream"
  shard_count = 1

  tags = {
    Name = "My Kinesis Stream"
  }
}

resource "aws_cloudwatch_log_group" "lambda_log_group" {
  name = "/aws/lambda/${aws_lambda_function.my_lambda.function_name}"
  retention_in_days = 14

  tags = {
    Name = "Lambda Log Group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray_daemon"

  tags = {
    Name = "X-Ray Daemon"
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "redshift-cluster"
  node_type         = "dc2.large"
  master_username   = "awsadmin"
  master_password   = var.redshift_password
  database_name     = "mydatabase"
  cluster_type      = "single-node"

  tags = {
    Name = "Redshift Cluster"
  }
}

resource "aws_directconnect_connection" "dx_connection" {
  name = "dx-connection"
  bandwidth = "1Gbps"
  connection_type = "dedicated"
  location = "New York"
  vlan = 100

  tags = {
    Name = "Direct Connect Connection"
  }
}

resource "aws_transit_gateway" "transit_gateway" {
  description = "My Transit Gateway"

  tags = {
    Name = "Transit Gateway"
  }
}

resource "aws_snowball_job" "snowball_job" {
  job_type = "IMPORT"
  snowball_type = "STANDARD"
  resources {
    S3_resource {
      bucket_arn = aws_s3_bucket.data_bucket.arn
    }
  }

  tags = {
    Name = "Snowball Job"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
}

output "lambda_function_name" {
  value = aws_lambda_function.my_lambda.function_name
}

output "redshift_endpoint" {
  value = aws_redshift_cluster.redshift_cluster.endpoint
