  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"api_sg\" {\n  vpc_id = aws_vpc.main.id\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"LeaderboardAPI\"\n}\n\nresource \"aws_lambda_function\" \"score_processor\" {\n  function_name = \"ScoreProcessor\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n}\n\nresource \"aws_dynamodb_table\" \"leaderboard\" {\n  name         = \"Leaderboard\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"PlayerId\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_kinesis_stream\" \"score_updates\" {\n  name   = \"ScoreUpdates\"\n  shard_count = 1\n}\n\nresource \"aws_ecs_cluster\" \"game_cluster\" {\n  name = \"GameCluster\"\n}",
