  "terraform": "terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

variable "instance_type" {
  description = "EC2 instance type for Batch."
  type        = string
  default     = "t3.micro"
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count             = length(var.public_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_subnet_cidrs, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "batch_sg" {
  name        = "batch_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow Batch jobs to communicate"

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "batch_sg"
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "rds_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS instance"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_sg"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "batch-compute-env"
  type                     = "MANAGED"
  service_role             = aws_iam_role.batch_service_role.arn
  state                    = "ENABLED"

  compute_resources {
    type              = "SPOT"
    min_vCpus        = 0
    max_vCpus        = 16
    desired_vCpus    = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = [var.instance_type]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.batch_sg.id]
  }

  tags = {
    Name = "batch_compute_env"
  }
}

resource "aws_batch_job_queue" "job_queue" {
  name                 = "job-queue"
  priority             = 1
  compute_environment  = [aws_batch_compute_environment.batch_env.arn]

  tags = {
    Name = "job_queue"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "data_bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_sqs_queue" "task_queue" {
  name = "task-queue"

  tags = {
    Name = "task_queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "batch-log-group"

  retention_in_days = 14

  tags = {
    Name = "batch_log_group"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"
  image = "amazon/aws-xray-daemon"
  desired_count = 1
  task_definition = aws_ecs_task_definition.xray_task.arn
}

resource "aws_ecs_task_definition" "xray_task" {
  family                   = "xray-task"
  network_mode             = "awsvpc"
  requires_compatibilities  = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"

  container_definitions = jsonencode([{
    name      = "xray-daemon"
    image     = "amazon/aws-xray-daemon"
    essential = true
    portMappings = [{
      containerPort = 2000
      hostPort      = 2000
      protocol      = "udp"
    }]
  }])

  tags = {
    Name = "xray_task"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
}

output "sqs_queue_url" {
  value = aws_sqs_queue.task_queue.id
}",
