{
  "scenario_summary": "The client needs a scalable and reliable architecture for an HR management system with 1 million daily active users.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "Amazon API Gateway",
        "Application Load Balancer"
      ],
      "compute": [
