      "optimization": "Implementing AWS Lambda to handle certain workloads can save costs by reducing the need for always-on EC2 instances."
    },
    "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"HRManagementAPI\"\n}\n\nresource \"aws_lambda_function\" \"hr_lambda\" {\n  function_name = \"HRLambda\"\n  handler       = \"handler.lambda_handler\"\n  runtime       = \"python3.8\"\n}\n\nresource \"aws_ecs_cluster\" \"hr_cluster\" {\n  name = \"HRManagementCluster\"\n}\n\nresource \"aws_rds_instance\" \"hr_db\" {\n  identifier = \"hr-database\"\n  engine = \"postgres\"\n  instance_class = \"db.t3.micro\"\n  allocated_storage = 20\n}\n\nresource \"aws_dynamodb_table\" \"hr_table\" {\n  name           = \"HRData\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  hash_key       = \"UserId\"\n  attribute {\n    name = \"UserId\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_sqs_queue\" \"hr_queue\" {\n  name = \"HRQueue\"\n}",
