  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_security_group\" \"allow_lambda\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_iot_topic_rule\" \"sensor_data_rule\" {\n  name = \"sensor_data_rule\"\n  sql = \"SELECT * FROM 'sensor/data'\"\n  sql_version = \"2016-03-23\"\n  action {\n    lambda {\n      function_arn = aws_lambda_function.process_sensor_data.arn\n    }\n  }\n}\n\nresource \"aws_lambda_function\" \"process_sensor_data\" {\n  function_name = \"processSensorData\"\n  s3_bucket = \"my-lambda-bucket\"\n  s3_key = \"function.zip\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n  memory_size = 128\n  timeout = 20\n}\n\nresource \"aws_kinesis_stream\" \"sensor_stream\" {\n  name        = \"sensor_stream\"\n  shard_count = 1\n}\n\nresource \"aws_dynamodb_table\" \"sensor_data\" {\n  name           = \"sensor_data\"\n  billing_mode   = \"PAY_PER_REQUEST\"\n  hash_key       = \"sensor_id\"\n  attribute {\n    name = \"sensor_id\"\n    type = \"S\"\n  }\n}\n\nresource \"aws_elasticache_cluster\" \"cache\" {\n  cluster_id = \"sensor_cache\"\n  engine = \"redis\"\n  node_type = \"cache.t2.micro\"\n  num_cache_nodes = 1\n  parameter_group_name = \"default.redis3.2\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"lambda_logs\" {\n  name = \"/aws/lambda/processSensorData\"\n  retention_in_days = 14\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|sends data| AWS_IoT_Core[AWS IoT Core]\n    AWS_IoT_Core -->|triggers| AWS_Lambda[AWS Lambda]\n    AWS_Lambda -->|processes data| Amazon_Kinesis[Amazon Kinesis]\n    Amazon_Kinesis -->|stores| Amazon_DynamoDB[Amazon DynamoDB]\n    Amazon_DynamoDB -->|caches| Amazon_ElastiCache[Amazon ElastiCache]\n    AWS_Lambda -->|logs| Amazon_CloudWatch[Amazon CloudWatch]"
}

