provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster"
  type        = string
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id     = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "rds_security_group" {
  name        = "rds_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS instance"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_security_group.ec2_security_group.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_security_group" "ec2_security_group" {
  name        = "ec2_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to EC2 instances"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ec2_security_group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_s3_bucket" "bucket" {
  bucket = "${var.bucket_prefix}${random_string.bucket_suffix.result}"
  acl    = "private"

  tags = {
    Name = "audiophile-s3-bucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_sqs_queue" "queue" {
  name = "audiophile-sqs-queue"

  tags = {
    Name = "audiophile-sqs-queue"
  }
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "audiophile-log-group"

  retention_in_days = 14

  tags = {
    Name = "audiophile-log-group"
  }
}

resource "aws_batch_compute_environment" "batch_env" {
  compute_environment_name = "audiophile-batch-env"
  type                     = "MANAGED"

  compute_resources {
    type              = "SPOT"
    min_v_cpus       = 0
    max_v_cpus       = 16
    desired_v_cpus   = 4
    instance_role    = "ecsInstanceRole"
    instance_type    = ["optimal"]
    subnets          = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.ec2_security_group.id]
  }

  service_role = "AWSBatchServiceRole"

  tags = {
    Name = "audiophile-batch-env"
  }
}

resource "aws_cloudfront_distribution" "cdn" {
  origin {
    domain_name = aws_s3_bucket.bucket.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.cdn_identity.id
    }
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3Origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD", "OPTIONS"]
    cached_methods = ["GET", "HEAD"]
    forwarded_values {
      query_string = false
    }
    min_ttl = 0
    default_ttl = 86400
    max_ttl = 31536000
  }

  tags = {
    Name = "audiophile-cdn"
  }
}

resource "aws_cloudfront_origin_access_identity" "cdn_identity" {
  comment = "Origin Access Identity for CloudFront"

  tags = {
    Name = "audiophile-cdn-identity"
  }
}

resource "aws_vpc_endpoint" "sqs" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.sqs"
  vpc_endpoint_type = "Interface"
  subnet_ids        = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.ec2_security_group.id]

  tags = {
    Name = "sqs-vpc-endpoint"
  }
}

resource "aws_xray_daemon" "xray_daemon" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.bucket.bucket
}

output "sqs_queue_url" {
  value = aws_sqs_queue.queue.id
}

output "cloudfront_distribution_id" {
  value = aws_cloudfront_distribution.cdn.id
}",
  "diagram": "graph TD
    User([User / Client])
    Amazon_CloudFront[CloudFront]
    Amazon_VPC[VPC]
    AWS_PrivateLink[PrivateLink]
    AWS_Batch[Batch]
    Amazon_EC2_Spot_Instances[EC2 Spot Instances]
    Amazon_RDS[(RDS)]
    Amazon_S3[(S3)]
    Amazon_SQS[SQS]
    Amazon_CloudWatch[CloudWatch]
    AWS_X_Ray[X-Ray]
    User --> Amazon_CloudFront
    Amazon_CloudFront --> Amazon_VPC
    Amazon_CloudFront --> AWS_PrivateLink
    Amazon_VPC --> AWS_Batch
    Amazon_VPC --> Amazon_EC2_Spot_Instances
    AWS_PrivateLink --> AWS_Batch
    AWS_PrivateLink --> Amazon_EC2_Spot_Instances
    AWS_Batch --> Amazon_RDS
    AWS_Batch --> Amazon_S3
    Amazon_EC2_Spot_Instances --> Amazon_RDS
    Amazon_EC2_Spot_Instances --> Amazon_S3
    AWS_Batch --> Amazon_SQS
    Amazon_EC2_Spot_Instances --> Amazon_SQS
    AWS_Batch -->|metrics| Amazon_CloudWatch
    AWS_Batch -->|metrics| AWS_X_Ray
    Amazon_EC2_Spot_Instances -->|metrics| Amazon_CloudWatch
    Amazon_EC2_Spot_Instances -->|metrics| AWS_X_Ray"
