variable "aws_region" {
  description = "Region for the AWS services to run in."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "rds_password" {
  description = "Password for the database in the RDS cluster."
  type        = string
}

variable "redshift_password" {
  description = "Password for the database in the Redshift cluster."
  type        = string
}

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  enable_dns_support = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.public_subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id
  cidr_block = element(var.private_subnet_cidrs, count.index)

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_security_group" "rds_security_group" {
  name        = "rds_security_group"
  vpc_id      = aws_vpc.main.id
  description = "Allow access to RDS from specific sources."

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"] # Allow all outbound traffic
  }

  tags = {
    Name = "rds_security_group"
  }
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  identifier          = "rds-terraform"
  instance_class      = "db.t3.micro"
  engine             = "postgres"
  engine_version      = "14.1"
  db_name             = "crinacle_audiophile_ratings"
  username            = "awsadmin"
  password            = var.rds_password
  publicly_accessible  = false
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "rds_instance"
  }
}

resource "aws_s3_bucket" "data_bucket" {
  bucket = "${var.bucket_prefix}${substr(md5(aws_db_instance.rds_instance.id), 0, 8)}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "data_bucket"
  }
}

resource "aws_lambda_function" "example_lambda" {
  function_name = "example_lambda"
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  s3_bucket     = aws_s3_bucket.data_bucket.bucket
  s3_key        = "lambda.zip"

  tags = {
    Name = "example_lambda"
  }
}

resource "aws_ecs_cluster" "example_cluster" {
  name = "example_cluster"

  tags = {
    Name = "example_cluster"
  }
}

resource "aws_glue_catalog_database" "example_database" {
  name = "example_database"

  tags = {
    Name = "example_database"
  }
}

resource "aws_redshift_cluster" "example_redshift" {
  cluster_identifier = "example-redshift"
  node_type         = "dc2.large"
  master_username   = "awsadmin"
  master_password   = var.redshift_password
  database_name     = "exampledb"
  cluster_type      = "single-node"

  tags = {
    Name = "example_redshift"
  }
}

resource "aws_kinesis_stream" "example_stream" {
  name        = "example_stream"
  shard_count = 1

  tags = {
    Name = "example_stream"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "example_firehose" {
  name        = "example_firehose"
  destination = "s3"

  s3_configuration {
    bucket_arn = aws_s3_bucket.data_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn
  }

  tags = {
    Name = "example_firehose"
  }
}

resource "aws_cloudwatch_log_group" "example_log_group" {
  name = "/aws/lambda/example_lambda"

  tags = {
    Name = "example_log_group"
  }
}

resource "aws_xray_daemon" "example_xray" {
  name = "example_xray"

  tags = {
    Name = "example_xray"
  }
}

output "rds_endpoint" {
  value = aws_db_instance.rds_instance.endpoint
}

output "s3_bucket_name" {
  value = aws_s3_bucket.data_bucket.bucket
}

output "redshift_endpoint" {
  value = aws_redshift_cluster.example_redshift.endpoint
