    "optimization": "Switch to 1-year Reserved Instances for EC2/RDS/ElastiCache to save 30-40% on compute costs. Use S3 Intelligent-Tiering for infrequently accessed data."
  },
  "terraform": "locals {
  environment = var.environment
  name_prefix = "${var.environment}-app"
}

# VPC for the application
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Public Subnet
resource "aws_subnet" "public_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_1
  availability_zone = var.availability_zone_1

  tags = {
    Name = "${local.name_prefix}-public-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidr_2
  availability_zone = var.availability_zone_2

  tags = {
    Name = "${local.name_prefix}-public-2"
  }
}

# Private Subnet
resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_1
  availability_zone = var.availability_zone_1

  tags = {
    Name = "${local.name_prefix}-private-1"
  }
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr_2
  availability_zone = var.availability_zone_2

  tags = {
    Name = "${local.name_prefix}-private-2"
  }
}

# Security Group for Application Load Balancer
resource "aws_security_group" "alb_sg" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-alb-sg"
  }
}

# Security Group for ECS Tasks
resource "aws_security_group" "ecs_sg" {
  name        = "${local.name_prefix}-ecs-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-ecs-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "app_lb" {
  name               = "${local.name_prefix}-app-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  enable_deletion_protection = false

  tags = {
    Name = "${local.name_prefix}-app-lb"
  }
}

# Target Group for ECS
resource "aws_lb_target_group" "ecs_target_group" {
  name     = "${local.name_prefix}-ecs-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold  = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${local.name_prefix}-ecs-tg"
  }
}

# Listener for Application Load Balancer
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "forward"
    target_group_arn = aws_lb_target_group.ecs_target_group.arn
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-ecs-cluster"

  tags = {
    Name = "${local.name_prefix}-ecs-cluster"
  }
}

# ECS Task Definition
resource "aws_ecs_task_definition" "app_task" {
  family                   = "${local.name_prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode            = "awsvpc"
  cpu                     = var.ecs_task_cpu
  memory                  = var.ecs_task_memory
  execution_role_arn      = aws_iam_role.ecs_execution_role.arn
  task_role_arn           = aws_iam_role.ecs_task_role.arn

  container_definitions = jsonencode([{
    name      = "${local.name_prefix}-container"
    image     = var.container_image
    essential = true
    portMappings = [{
      containerPort = 80
      hostPort      = 80
      protocol      = "tcp"
    }]
  }])

  tags = {
    Name = "${local.name_prefix}-task"
  }
}

# ECS Service
resource "aws_ecs_service" "app_service" {
  name            = "${local.name_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app_task.arn
  desired_count   = var.desired_count
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = [aws_subnet.private_1.id, aws_subnet.private_2.id]
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }

  depends_on = [aws_lb_listener.http]

  tags = {
    Name = "${local.name_prefix}-service"
  }
}

# RDS Aurora Cluster
resource "aws_rds_cluster" "aurora" {
  cluster_identifier      = "${local.name_prefix}-aurora-cluster"
  engine                 = "aurora-postgresql"
  master_username         = var.db_username
  master_password         = var.db_password
  database_name           = var.db_name
  skip_final_snapshot     = true
  vpc_security_group_ids   = [aws_security_group.ecs_sg.id]
  db_subnet_group_name     = aws_db_subnet_group.aurora_subnet_group.name

  tags = {
    Name = "${local.name_prefix}-aurora-cluster"
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "${local.name_prefix}-aurora-subnet-group"
  subnet_ids = [aws_subnet.private_1.id, aws_subnet.private_2.id]

  tags = {
    Name = "${local.name_prefix}-aurora-subnet-group"
  }
}

# SNS Topic
resource "aws_sns_topic" "app_topic" {
  name = "${local.name_prefix}-sns-topic"

  tags = {
    Name = "${local.name_prefix}-sns-topic"
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "app_log_group" {
  name              = "${local.name_prefix}-log-group"
  retention_in_days = 14

  tags = {
    Name = "${local.name_prefix}-log-group"
  }
}

# Outputs
output "vpc_id" {
  value = aws_vpc.main.id
}

output "alb_dns_name" {
  value = aws_lb.app_lb.dns_name
}

output "ecs_cluster_name" {
  value = aws_ecs_cluster.main.name
}

output "aurora_cluster_endpoint" {
  value = aws_rds_cluster.aurora.endpoint
}

output "sns_topic_arn" {
  value = aws_sns_topic.app_topic.arn
}",
  "diagram": "graph TD
    User([User / Client])
    CloudFront[CloudFront]
    Application_Load_Balancer[Application Load Balancer]
    ECS_Fargate[ECS Fargate]
    Amazon_Aurora[(Aurora)]
    SNS[SNS]
    CloudWatch[CloudWatch]
    User --> CloudFront
    CloudFront --> Application_Load_Balancer
    Application_Load_Balancer --> ECS_Fargate
    ECS_Fargate --> Amazon_Aurora
    ECS_Fargate --> SNS
    ECS_Fargate -->|metrics| CloudWatch"
}

{
  "scenario_summary": "The client needs a secure AWS architecture for a news aggregator capable of handling 10,000 requests per second.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "AWS WAF",
        "Amazon API Gateway"
      ],
      "compute": [
        "AWS Lambda",
        "Amazon ECS"
      ],
      "database": [
        "Amazon DynamoDB"
      ],
      "messaging": [
        "Amazon SNS"
      ],
      "monitoring": [
        "Amazon CloudWatch",
        "AWS X-Ray"
      ]
    },
    "reasoning": "Using Amazon CloudFront as a CDN will enhance performance by caching content closer to users, thus reducing latency. AWS WAF provides an additional layer of security by protecting web applications from common web exploits. For the compute layer, AWS Lambda is suitable for handling burst traffic with automatic scaling, while Amazon ECS can manage containerized applications, providing flexibility and control over the environment. The choice of Amazon DynamoDB as the database allows for fast and predictable performance with seamless scalability, which is crucial for a news aggregator expecting high traffic.\n\nIn terms of messaging, Amazon SNS enables reliable message delivery to multiple subscribers, which can be useful for alerting users about new news articles. Monitoring with Amazon CloudWatch and AWS X-Ray will allow for real-time visibility into application performance and bottlenecks, ensuring issues can be addressed quickly. The architecture is designed to be highly scalable, reliable, and cost-effective, leveraging AWS services that automatically scale to meet demand while maintaining security best practices."
  },
  "trade_offs": [
    {
      "decision": "AWS Lambda vs Amazon ECS",
      "chose": "AWS Lambda",
      "reason": "AWS Lambda automatically scales with incoming requests, making it ideal for handling burst traffic effectively.",
      "when_to_switch": "If the application requires long-running processes or more control over the environment, Amazon ECS may be the better choice."
    },
    {
      "decision": "Amazon DynamoDB vs Amazon RDS",
      "chose": "Amazon DynamoDB",
      "reason": "Amazon DynamoDB provides low-latency access and can scale horizontally to handle high request rates without the need for complex sharding strategies.",
      "when_to_switch": "If the application requires complex queries and transactions, Amazon RDS might be more appropriate."
    },
    {
      "decision": "AWS WAF vs AWS Shield",
      "chose": "AWS WAF",
      "reason": "AWS WAF provides customizable web application firewall rules that help protect against specific attacks while providing detailed logging.",
      "when_to_switch": "If DDoS protection is a primary concern, integrating AWS Shield may be beneficial."
    }
  ],
  "cost": {
    "monthly_breakdown": [
      {
        "service": "Amazon CloudFront",
        "monthly_usd": 100.0,
        "unit": "Data transfer out"
      },
      {
        "service": "AWS Lambda",
        "monthly_usd": 50.0,
        "unit": "Invocations"
      },
      {
        "service": "Amazon API Gateway",
        "monthly_usd": 30.0,
        "unit": "API calls"
      },
      {
        "service": "Amazon DynamoDB",
        "monthly_usd": 150.0,
        "unit": "Read/Write capacity"
      },
      {
        "service": "Amazon SNS",
        "monthly_usd": 20.0,
        "unit": "Messages"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 10.0,
        "unit": "Monitoring"
      }
    ],
    "total_monthly_usd": 360.0,
    "spike_estimate_usd": 500.0,
    "optimization": "Utilize AWS Lambda's provisioned concurrency for predictable traffic patterns to reduce cold start latencies."
  },
  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  map_public_ip_on_launch = true\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_cloudfront_distribution\" \"cdn\" {\n  origin {\n    domain_name = \"your-api-gateway-url\"\n    origin_id   = \"apiGateway\"\n  }\n  enabled = true\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"news-aggregator-api\"\n}\n\nresource \"aws_lambda_function\" \"handler\" {\n  function_name = \"newsAggregator\"\n  handler = \"index.handler\"\n  runtime = \"nodejs14.x\"\n}\n\nresource \"aws_dynamodb_table\" \"news_table\" {\n  name         = \"newsItems\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sns_topic\" \"news_alerts\" {\n  name = \"newsAlerts\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"/aws/lambda/newsAggregator\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Requests| API_Gateway([Amazon API Gateway])\n    API_Gateway -->|Triggers| Lambda([AWS Lambda])\n    Lambda -->|Reads/Writes| DynamoDB([Amazon DynamoDB])\n    Lambda -->|Sends Alerts| SNS([Amazon SNS])\n    API_Gateway -->|Logs| CloudWatch([Amazon CloudWatch])\n    User -->|Content Delivery| CloudFront([Amazon CloudFront])"
}

{
  "scenario_summary": "The client needs a scalable and cost-effective architecture for processing large volumes of genomics data.",
  "architecture": {
    "layers": {
