  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet_a\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_subnet\" \"subnet_b\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n}\n\nresource \"aws_security_group\" \"allow_api\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks  = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"data_ingestion\" {\n  function_name = \"data_ingestion\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role          = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_ecs_cluster\" \"genomics_pipeline\" {\n  name = \"genomics_pipeline\"\n}\n\nresource \"aws_s3_bucket\" \"genomic_data\" {\n  bucket = \"genomic-data-storage\"\n}\n\nresource \"aws_dynamodb_table\" \"metadata\" {\n  name         = \"genomic_metadata\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sqs_queue\" \"processing_queue\" {\n  name = \"genomics_processing_queue\"\n}",
  "diagram": "graph TD\n    User([User])\n    User -->|Data Request| API[API Gateway]\n    API -->|Trigger| Lambda[AWS Lambda]\n    Lambda -->|Store Data| S3[Amazon S3]\n    Lambda -->|Send Message| SQS[Amazon SQS]\n    SQS -->|Trigger| ECS[Amazon ECS]\n    ECS -->|Read Metadata| DynamoDB[Amazon DynamoDB]\n    Lambda -->|Monitoring| CloudWatch[CloudWatch]"
}

{
  "scenario_summary": "The client needs a scalable CI/CD platform to support 500 engineering teams.",
