  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id            = aws_vpc.main.id\n  cidr_block        = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"ci_cd_trigger\" {\n  function_name = \"ci_cd_trigger\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  s3_bucket     = \"my-bucket\"\n  s3_key        = \"lambda.zip\"\n}\n\nresource \"aws_ecs_cluster\" \"ci_cd_cluster\" {\n  name = \"ci_cd_cluster\"\n}\n\nresource \"aws_rds_cluster\" \"main\" {\n  engine         = \"aurora\"\n  master_username = \"user\"\n  master_password = \"password\"\n  db_cluster_identifier = \"my-cluster\"\n}\n\nresource \"aws_dynamodb_table\" \"ci_cd_table\" {\n  name       = \"ci_cd_table\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sns_topic\" \"ci_cd_notifications\" {\n  name = \"ci_cd_notifications\"\n}",
  "diagram": "graph TD\n    User([User])\n    User-->API[API Gateway]\n    API-->Lambda[AWS Lambda]\n    Lambda-->ECS[Amazon ECS]\n    ECS-->RDS[Amazon RDS]\n    ECS-->DynamoDB[Amazon DynamoDB]\n    Lambda-->SNS[Amazon SNS]\n    ECS-->CodeBuild[AWS CodeBuild]\n    CodeBuild-->CodeDeploy[AWS CodeDeploy]\n    SNS-->CloudWatch[Amazon CloudWatch]"
