{
  "scenario_summary": "The client needs to compare API Gateway and ALB for routing traffic to Lambda functions for a REST API workload.",
  "architecture": {
    "layers": {
      "edge": [
        "Amazon CloudFront"
      ],
      "networking": [
        "API Gateway"
      ],
      "compute": [
        "AWS Lambda"
      ],
      "database": [
        "Amazon DynamoDB"
      ],
      "messaging": [],
      "monitoring": [
        "Amazon CloudWatch"
      ]
    },
    "reasoning": "API Gateway is specifically designed for creating and managing APIs, making it an ideal choice for REST API workloads. It provides built-in features such as request validation, API versioning, and detailed monitoring capabilities, which are essential for managing API traffic efficiently. Additionally, API Gateway integrates seamlessly with AWS Lambda, allowing for automatic scaling based on demand without the need for provisioning servers. This serverless architecture reduces operational overhead and costs, as clients only pay for the requests made to the API and the compute time used by Lambda functions.

On the other hand, while Application Load Balancer (ALB) can route traffic to Lambda functions, it is primarily designed for load balancing HTTP/HTTPS traffic to EC2 instances or containers. It lacks the advanced API management features that API Gateway offers, such as caching, throttling, and detailed metrics. For a REST API workload, API Gateway provides a more tailored solution that enhances reliability and scalability, making it the preferred choice for this scenario."
  },
  "trade_offs": [
    {
      "decision": "API Gateway vs Application Load Balancer (ALB)",
      "chose": "API Gateway",
      "reason": "API Gateway offers advanced API management features, such as request validation, rate limiting, and built-in monitoring, which are essential for REST APIs.",
      "when_to_switch": "If the workload requires advanced load balancing features or if the API needs to handle WebSocket connections, ALB may be a better fit."
    },
    {
      "decision": "DynamoDB vs RDS",
      "chose": "DynamoDB",
      "reason": "DynamoDB is a fully managed NoSQL database that offers automatic scaling and low-latency performance, making it ideal for serverless applications that require high availability and scalability.",
      "when_to_switch": "If the application requires complex queries and transactions that are better suited for a relational database, Amazon RDS would be the appropriate choice."
    },
    {
      "decision": "Lambda vs EC2",
      "chose": "Lambda",
      "reason": "AWS Lambda allows for a serverless architecture where compute resources are automatically managed and scaled based on demand, reducing operational overhead and costs.",
      "when_to_switch": "If the application requires long-running processes or needs to maintain state across requests, EC2 instances may be more suitable."
    }
  ],
  "cost": {
    "monthly_breakdown": [
      {
        "service": "Amazon CloudFront",
        "monthly_usd": 10.0,
        "unit": "per 1TB transfer"
      },
      {
        "service": "API Gateway",
        "monthly_usd": 3.5,
        "unit": "per 1M requests"
      },
      {
        "service": "AWS Lambda",
        "monthly_usd": 0.2,
        "unit": "per 1M requests"
      },
      {
        "service": "Amazon DynamoDB",
        "monthly_usd": 25.0,
        "unit": "estimated (moderate traffic)"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 10.0,
        "unit": "estimated"
      },
      {
        "service": "Data Transfer (egress)",
        "monthly_usd": 9.0,
        "unit": "per 100GB egress"
      }
    ],
    "total_monthly_usd": 57.7,
    "spike_estimate_usd": 77.9,
    "optimization": "Switch to 1-year Reserved Instances for EC2/RDS/ElastiCache to save 30-40% on compute costs. Use S3 Intelligent-Tiering for infrequently accessed data."
  },
  "terraform": "terraform {
  required_version = "~> 1.9.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.49.0"
    }
  }
  backend "s3" {
    bucket         = "dev-aman-tf-bucket"
    region         = "us-east-1"
    key            = "eks/terraform.tfstate"
    dynamodb_table = "Lock-Files"
    encrypt        = true
  }
}

variable "aws_region" {
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)."
  default     = "prod"
}

variable "lambda_function_name" {
  description = "Name of the Lambda function."
  default     = "my_lambda_function"
}

variable "api_gateway_name" {
  description = "Name of the API Gateway."
  default     = "my_api_gateway"
}

variable "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  default     = "my_dynamodb_table"
}

variable "cloudfront_distribution_name" {
  description = "Name of the CloudFront distribution."
  default     = "my_cloudfront_distribution"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "MyProject"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  tags      = local.common_tags
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone = "${var.aws_region}a"
  tags              = merge(local.common_tags, { Name = "${var.environment}-public-subnet" })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}a"
  tags              = merge(local.common_tags, { Name = "${var.environment}-private-subnet" })
}

resource "aws_security_group" "lambda_sg" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "my_lambda" {
  function_name = var.lambda_function_name
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
  filename      = "lambda.zip"
  source_code_hash = filebase64sha256("lambda.zip")
  environment = {
    DYNAMODB_TABLE = aws_dynamodb_table.my_table.name
  }
  tags = local.common_tags
}

