      {
        "service": "AWS Lambda",
        "monthly_usd": 30.0,
        "unit": "1 million requests"
      },
      {
        "service": "Amazon Kinesis",
        "monthly_usd": 50.0,
        "unit": "shards"
      },
      {
        "service": "Amazon DynamoDB",
        "monthly_usd": 10.0,
        "unit": "read/write capacity units"
      },
      {
        "service": "Amazon CloudWatch",
        "monthly_usd": 5.0,
