  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"subnet1\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n}\n\nresource \"aws_iot_topic_rule\" \"sensor_data\" {\n  sql = \"SELECT * FROM 'sensor/data'\"\n}\n\nresource \"aws_lambda_function\" \"process_sensor_data\" {\n  function_name = \"processSensorData\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n  role         = aws_iam_role.lambda_exec.arn\n}\n\nresource \"aws_dynamodb_table\" \"sensor_data\" {\n  name         = \"SensorData\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"device_id\"\n    type = \"S\"\n  }\n  key_schema {\n    attribute_name = \"device_id\"\n    key_type      = \"HASH\"\n  }\n}\n\nresource \"aws_kinesis_stream\" \"sensor_stream\" {\n  name        = \"SensorStream\"\n  shard_count = 1\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"SensorAPI\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"lambda_logs\" {\n  name = \"/aws/lambda/${aws_lambda_function.process_sensor_data.function_name}\"\n}",
