    {
      name      = "app-container"
      image     = "your-docker-image"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    }
  ])
}

resource "aws_ecs_service" "app" {
  name            = "app-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.private.id]
    assign_public_ip = false
  }
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name = "/ecs/app"

  retention_in_days = 14

  tags = {
    Name = "app-logs"
  }
}

resource "aws_xray_daemon" "app" {
  name = "xray-daemon"

  tags = {
    Name = "xray-daemon"
  }
}

resource "aws_cloudfront_distribution" "video_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_storage.bucket_regional_domain_name
    origin_id   = "S3-${aws_s3_bucket.video_storage.id}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.s3.id
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "S3-${aws_s3_bucket.video_storage.id}"
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD", "OPTIONS"]
