    {
      "decision": "Kinesis vs SQS",
      "chose": "Kinesis",
      "reason": "Kinesis supports real-time processing, message ordering, and retention for replay, which are essential for event streaming use cases.",
      "when_to_switch": "If the workload requires strict message delivery guarantees without the need for real-time processing, SQS could be considered."
    },
    {
      "decision": "Lambda vs EC2 for compute",
      "chose": "Lambda",
      "reason": "AWS Lambda provides a serverless architecture that automatically scales with the number of events, reducing operational overhead and costs.",
      "when_to_switch": "If the workload requires long-running processes or specific custom environments, EC2 may be more suitable."
    },
    {
      "decision": "DynamoDB vs RDS for database",
