  "terraform": "resource \"aws_vpc\" \"main\" {\n  cidr_block = \"10.0.0.0/16\"\n}\n\nresource \"aws_subnet\" \"public\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.1.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_subnet\" \"private\" {\n  vpc_id     = aws_vpc.main.id\n  cidr_block = \"10.0.2.0/24\"\n  availability_zone = \"us-east-1a\"\n}\n\nresource \"aws_security_group\" \"allow_http\" {\n  vpc_id = aws_vpc.main.id\n  ingress {\n    from_port   = 80\n    to_port     = 80\n    protocol    = \"tcp\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}\n\nresource \"aws_lambda_function\" \"dna_processor\" {\n  function_name = \"DNAProcessor\"\n  handler       = \"index.handler\"\n  runtime       = \"nodejs14.x\"\n}\n\nresource \"aws_api_gateway_rest_api\" \"api\" {\n  name = \"genomics-api\"\n}\n\nresource \"aws_s3_bucket\" \"dna_bucket\" {\n  bucket = \"genomics-data-bucket\"\n}\n\nresource \"aws_dynamodb_table\" \"metadata\" {\n  name         = \"GenomicsMetadata\"\n  billing_mode = \"PAY_PER_REQUEST\"\n  attribute {\n    name = \"id\"\n    type = \"S\"\n  }\n  hash_key = \"id\"\n}\n\nresource \"aws_sqs_queue\" \"task_queue\" {\n  name = \"genomics-tasks\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"log_group\" {\n  name = \"genomics-log-group\"\n}",
